function normalizeApplicationDealProduct(value, fallback = "") {
  const firstValue = String(value || "").trim();
  const secondValue = String(fallback || "").trim();
  const source = firstValue || secondValue;
  if (!source) return "";
  if (APPLICATION_DEAL_PRODUCT_TYPES.includes(source)) return source;
  const normalized = source.toLowerCase();
  if (/лизинг/.test(normalized)) return "Лизинг";
  if (/гарант/.test(normalized)) return "Банковская гарантия";
  return DEFAULT_APPLICATION_DEAL_PRODUCT_TYPE;
}

function normalizeApplicationDealProducts(values = []) {
  return uniqueItems(values.map((item) => normalizeApplicationDealProduct(item)).filter(Boolean));
}

function renderApplicationDealProductOptions(value = "") {
  const normalizedValue = normalizeApplicationDealProduct(value) || DEFAULT_APPLICATION_DEAL_PRODUCT_TYPE;
  return APPLICATION_DEAL_PRODUCT_TYPES
    .map((item) => `<option value="${escapeHtml(item)}" ${item === normalizedValue ? "selected" : ""}>${escapeHtml(item)}</option>`)
    .join("");
}

