function getUnifiedTaskType(type) {
  const value = String(type || "")
    .replace(/\s*\((документарный|физический)\)\s*$/i, "")
    .trim();
  return /^постановка\s+в\s+залог$/i.test(value) ? TASK_TYPE_REGISTRATION : value;
}

