function normalizeTaskStatus(status) {
  if (status === LEGACY_TASK_STATUS_REWORK) return "Ожидание";
  if (status === LEGACY_TASK_STATUS_APPROVAL) return "Назначена";
  return TASK_STATUSES.includes(status) ? status : (status || "Назначена");
}

function normalizeTaskHistoryEvent(event = {}) {
  const status = event.status ? normalizeTaskStatus(event.status) : "";
  return {
    ...event,
    action: normalizeTaskHistoryAction(event.action),
    status,
    oldValue: event.oldValue ?? event.valueBefore ?? "",
    newValue: event.newValue ?? event.valueAfter ?? event.result ?? "",
    comment: event.comment || event.reason || ""
  };
}

