function renderApplicationTaskLinks(application) {
  const tasks = getApplicationTasks(application);
  if (!tasks.length) return `<span class="muted">0 ${pluralize(0, "задача", "задачи", "задач")}</span>`;
  const visibleTask = tasks.find((task) => canViewTaskRecord(task, getRole()));
  const direction = visibleTask ? getTaskDirection(visibleTask) : getAvailableTaskDirections(getRole())[0];
  if (!direction) return `<span>${tasks.length} ${pluralize(tasks.length, "задача", "задачи", "задач")}</span>`;
  const route = getTaskDirectionConfig(direction).path;
  return renderApplicationCountLink(application, route, tasks.length, ["задача", "задачи", "задач"]);
}

function getTaskCardRoute(taskOrId) {
  const rawId = typeof taskOrId === "object" ? taskOrId?.id || taskOrId?.number : taskOrId;
  const id = legacyObjectNumberAliases[String(rawId || "")] || String(rawId || "");
  return `/app/tasks/${encodeURIComponent(id)}`;
}

function getApplicationCardRoute(application) {
  const rawId = application?.number || application?.id || "";
  const id = legacyObjectNumberAliases[rawId] || rawId;
  return `/app/applications/${encodeURIComponent(id)}`;
}

function renderRegistryRecordLink(route, label, className = "link registry-object-link") {
  return `<a class="${escapeHtml(className)}" href="#${escapeHtml(route)}" target="_blank" rel="noopener noreferrer">${escapeHtml(label)}</a>`;
}

function renderApplicationRegistryNumberLink(application) {
  const number = application?.number || application?.id || "-";
  if (!application) return `<span class="muted">-</span>`;
  return renderRegistryRecordLink(getApplicationCardRoute(application), number);
}

function isDraftApplication(application) {
  return getApplicationRegistryStatus(application?.status) === "Черновик";
}

function renderApplicationRegistryNumberCell(application) {
  return renderApplicationRegistryNumberLink(application);
}

function renderApplicationRegistryDeleteAction(application) {
  if (!application || !hasPermission(getRole(), "appDelete")) return "";
  const deleteDisabled = !isDraftApplication(application);
  return `
    <button type="button" class="icon-btn application-registry-delete-button" data-action="open-delete-application" data-application="${escapeHtml(application.id)}" aria-label="Удалить заявку ${escapeHtml(application.number || application.id)}" title="${deleteDisabled ? "Удалять можно только заявку в статусе «Черновик»" : "Удалить черновик заявки"}" ${deleteDisabled ? "disabled aria-disabled=\"true\"" : ""}>
      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3" /></svg>
    </button>
  `;
}

function openApplicationDeleteConfirmation(applicationId) {
  const application = (state.data.applications || []).find((item) => item.id === applicationId);
  if (!application || !hasPermission(getRole(), "appDelete") || !isDraftApplication(application)) return;
  if (getApplicationTasks(application).length) {
    addToast("Заявку нельзя удалить", "Черновик не должен иметь связанных задач.", "warn");
    return;
  }
  state.modal = { type: "deleteApplication", applicationId };
}

function confirmApplicationDelete(applicationId) {
  const application = (state.data.applications || []).find((item) => item.id === applicationId);
  if (!application || !hasPermission(getRole(), "appDelete") || !isDraftApplication(application)) return;
  if (getApplicationTasks(application).length) {
    state.modal = null;
    addToast("Заявку нельзя удалить", "Черновик не должен иметь связанных задач.", "warn");
    return;
  }
  deletedApplicationIds = [...new Set([...deletedApplicationIds, application.id, application.number].filter(Boolean))];
  state.data.applications = state.data.applications.filter((item) => item.id !== application.id && item.number !== application.number);
  state.modal = null;
  resetRegistryPagination("applications");
  persistTaskState();
  addToast("Черновик удален", application.number || application.id, "ok");
}

function renderApplicationLinkedTasksField(application) {
  const tasks = getApplicationTasks(application);
  const taskLinks = tasks.map((task) => `
    ${canViewTaskRecord(task, getRole())
      ? `<button class="link registry-object-link application-linked-task-link" data-route="${escapeHtml(getTaskCardRoute(task))}">${escapeHtml(task.id)}</button>`
      : `<span class="application-linked-task-link muted">${escapeHtml(task.id)}</span>`}
  `).join("");
  return `
    <div class="application-linked-tasks-field">
      <span>Связанные задачи</span>
      <div class="application-linked-tasks-list">
        ${taskLinks || `<span class="muted">Задачи будут созданы после регистрации заявки</span>`}
      </div>
    </div>
  `;
}

function renderApplicationLinkedTasksTable(application) {
  const tasks = getApplicationTasks(application);
  return `
    <section class="application-linked-tasks-table-section">
      <div class="panel-title">
        <div>
          <h2>Связанные задачи</h2>
          <span class="panel-note">Задачи, созданные в рамках заявки.</span>
        </div>
      </div>
      ${tasks.length ? `
        <div class="application-linked-tasks-table-wrap">
          <table class="application-linked-tasks-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Номер</th>
                <th>Тип</th>
                <th>Статус</th>
                <th>Исполнитель</th>
                <th>Дата создания</th>
                <th>Срок</th>
              </tr>
            </thead>
            <tbody>
              ${tasks.map((task) => `
                <tr>
                  <td>${renderApplicationLinkedTaskIdCell(task)}</td>
                  <td>${escapeHtml(task.number || task.taskNumber || task.id || "-")}</td>
                  <td>${escapeHtml(getTaskDisplayType(task))}</td>
                  <td>${badge(task.status || "-")}</td>
                  <td>${escapeHtml(task.assignee || "-")}</td>
                  <td>${escapeHtml(getTaskCreatedDateTime(task))}</td>
                  <td>${escapeHtml(task.dueDate || "-")}</td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      ` : `<div class="empty-state compact">Задачи будут созданы после регистрации заявки.</div>`}
    </section>
  `;
}

function renderApplicationReturnNotice(application) {
  const activeReturns = getApplicationReturnRequests(application);
  if (!activeReturns.length) return "";
  const returnItems = activeReturns.map(({ task, request }) => {
    const initiator = request.initiator || getTaskApplicationInitiator(task);
    const canRespond = getRole().user === initiator && task.assignee === initiator;
    return `
      <article class="application-return-item">
        <div class="application-return-item-heading">
          <div>
            <button class="link application-return-task-link" data-route="${escapeHtml(getTaskCardRoute(task))}">${escapeHtml(task.id || "Открыть задачу")}</button>
            <span class="application-return-task-type">${escapeHtml(getTaskDisplayType(task))}</span>
          </div>
        </div>
        <div class="application-return-notice-details">
          <div class="application-return-notice-reason">
            <span>Причина возврата</span>
            <strong>${escapeHtml(request.reason || "Не указана")}</strong>
          </div>
          <div class="application-return-notice-instruction">
            <span>Комментарий при возврате</span>
            <p>${escapeHtml(request.comment || "Исполнитель не добавил пояснение.")}</p>
          </div>
          <div class="application-return-notice-meta">
            <span>Вернул</span>
            <strong>${escapeHtml(request.user || "Не указан")}</strong>
          </div>
          <div class="application-return-notice-meta">
            <span>Дата возврата</span>
            <strong>${escapeHtml(request.date || "Не указана")}</strong>
          </div>
        </div>
        <div class="application-return-response">
          <label>
            <span>Комментарий инициатора *</span>
            <textarea data-application-return-response="${escapeHtml(task.id)}" required maxlength="1000" ${canRespond ? "" : "disabled"} placeholder="Например: документы приложены, сведения уточнены.">${escapeHtml(request.responseComment || "")}</textarea>
          </label>
          <button class="btn btn-primary" type="button" data-action="submit-application-return-response" data-task="${escapeHtml(task.id)}" ${canRespond ? "" : "disabled"}>Вернуть исполнителю</button>
        </div>
        ${canRespond ? "" : `<p class="application-return-response-note">Ответить может инициатор заявки: ${escapeHtml(initiator)}.</p>`}
      </article>
    `;
  }).join("");
  return `
    <section class="application-return-notice" aria-labelledby="applicationReturnTitle">
      <div class="application-return-notice-heading">
        <span class="application-return-notice-mark" aria-hidden="true">!</span>
        <div>
          <h2 id="applicationReturnTitle">Требуется доработка заявки</h2>
          <p>Ответьте отдельно по каждому возврату. Будет отправлена только выбранная задача.</p>
        </div>
      </div>
      <div class="application-return-list">${returnItems}</div>
    </section>
  `;
}

function renderApplicationLinkedTaskIdCell(task) {
  const id = task?.id || "-";
  if (!task || !canViewTaskRecord(task, getRole())) return `<span class="muted">${escapeHtml(id)}</span>`;
  return `<button class="link registry-object-link application-linked-task-link" data-route="${escapeHtml(getTaskCardRoute(id))}">${escapeHtml(legacyObjectNumberAliases[id] || id)}</button>`;
}

const APPLICATION_REGISTRY_COLLATERAL_PAGE_SIZE = 40;

function renderApplicationCollateralLinks(application) {
  const collaterals = getApplicationCollaterals(application);
  if (!collaterals.length) return `<span class="muted">0 залогов</span>`;
  const count = collaterals.length;
  const isOpen = state.applicationRegistryCollateralDrawer?.applicationNumber === application.number;
  return `
    <button type="button" class="task-registry-collateral-count" data-action="open-application-collateral-drawer"
      data-application="${escapeHtml(application.id || application.number)}" data-application-number="${escapeHtml(application.number)}"
      aria-controls="applicationRegistryCollateralDrawer" aria-expanded="${isOpen}" title="Открыть список объектов залога">
      <span>${count} ${pluralize(count, "залог", "залога", "залогов")}</span>
    </button>
  `;
}

function renderApplicationRegistryCollateralDrawerContent(application, collaterals, drawerState = state.applicationRegistryCollateralDrawer) {
  const limit = Math.max(APPLICATION_REGISTRY_COLLATERAL_PAGE_SIZE, Number(drawerState?.limit) || APPLICATION_REGISTRY_COLLATERAL_PAGE_SIZE);
  const visible = collaterals.slice(0, limit);
  const rowsMarkup = visible.map((collateral) => {
    const identifier = getCollateralObjectIdentifier(collateral);
    const pledgeNumber = getCollateralSuzNumber(collateral) || collateral.id || "—";
    const pledgorNames = [...new Set((Array.isArray(collateral.pledgors) ? collateral.pledgors : [])
      .map((pledgor) => String(pledgor?.name || "").trim())
      .filter(Boolean))];
    const pledgeNumberMarkup = hasPermission(getRole(), "collateralView")
      ? renderRegistryRecordLink(getCollateralCardRoute(collateral.id, { application }), pledgeNumber, "link task-registry-collateral-object-link")
      : `<strong class="task-registry-collateral-object-id">${escapeHtml(pledgeNumber)}</strong>`;
    return `
      <tr>
        <td>${pledgeNumberMarkup}</td>
        <td>${escapeHtml(identifier || "—")}</td>
        <td>${escapeHtml(getCollateralTypeLabel(collateral) || "—")}</td>
        <td>${escapeHtml(getCollateralStatusForFt(collateral))}</td>
        <td>${escapeHtml(pledgorNames.join(", ") || "—")}</td>
      </tr>
    `;
  }).join("");
  return `
    <table class="task-registry-collateral-table">
      <thead><tr><th>Номер залога</th><th>Идентификатор залога</th><th>Вид залога</th><th>Статус объекта</th><th>Залогодатель</th></tr></thead>
      <tbody>${rowsMarkup}</tbody>
    </table>
  `;
}

function renderApplicationRegistryCollateralDrawer() {
  const drawerState = state.applicationRegistryCollateralDrawer;
  if (!drawerState?.applicationId) return "";
  const application = getApplicationByIdOrNumber(drawerState.applicationId);
  if (!application) return "";
  const collaterals = getApplicationCollaterals(application);
  return `
    <aside class="task-registry-collateral-drawer" id="applicationRegistryCollateralDrawer" role="complementary" aria-labelledby="applicationRegistryCollateralTitle">
      <header class="task-registry-collateral-drawer-header">
        <h2 id="applicationRegistryCollateralTitle">Объекты залога</h2>
        <button type="button" class="icon-btn" data-action="close-application-collateral-drawer" aria-label="Закрыть список залогов" title="Закрыть">×</button>
      </header>
      <div class="task-registry-collateral-drawer-content" data-application-collateral-drawer-content>
        ${renderApplicationRegistryCollateralDrawerContent(application, collaterals, drawerState)}
      </div>
    </aside>
  `;
}

function loadNextApplicationRegistryCollateralBatch(content) {
  const drawerState = state.applicationRegistryCollateralDrawer;
  const application = drawerState ? getApplicationByIdOrNumber(drawerState.applicationId) : null;
  if (!content || !application) return false;
  const collaterals = getApplicationCollaterals(application);
  if (drawerState.limit >= collaterals.length) return false;
  const scrollTop = content.scrollTop;
  drawerState.limit = Math.min(drawerState.limit + APPLICATION_REGISTRY_COLLATERAL_PAGE_SIZE, collaterals.length);
  content.innerHTML = renderApplicationRegistryCollateralDrawerContent(application, collaterals, drawerState);
  content.scrollTop = scrollTop;
  return true;
}

function fillApplicationRegistryCollateralDrawerUntilScrollable() {
  const content = app.querySelector("[data-application-collateral-drawer-content]");
  while (content && content.scrollHeight <= content.clientHeight && loadNextApplicationRegistryCollateralBatch(content)) {
    // Render batches only until the panel can scroll or every object is visible.
  }
}

function renderApplicationContractLinks(application) {
  const contracts = getApplicationContracts(application);
  return renderContractNumberList(contracts, application?.contractNumber);
}

function renderApplicationCountLink(application, route, count, forms) {
  if (!count) return `<span class="muted">0 ${pluralize(0, forms[0], forms[1], forms[2])}</span>`;
  return renderRegistryRecordLink(`${route}?applicationNumber=${encodeURIComponent(application.number)}`, `${count} ${pluralize(count, forms[0], forms[1], forms[2])}`);
}

function getApplicationRegistryColumns(includeDeleteAction = false) {
  return [
    { key: "application", label: "Номер заявки", render: (application) => renderApplicationRegistryNumberCell(application) },
    { key: "createdAt", label: "Дата создания заявки", sortType: "date", sortValue: (application) => getApplicationCreatedDate(application), render: (application) => escapeHtml(formatRegistryDateTime(getApplicationCreatedDate(application))) },
    { key: "type", label: "Тип заявки", sortType: "text", sortValue: getApplicationType, render: (application) => escapeHtml(getApplicationType(application)) },
    { key: "subtype", label: "Подтип заявки", sortType: "text", sortValue: getApplicationSubtype, render: (application) => escapeHtml(getApplicationSubtype(application)) },
    { key: "purpose", label: "Цель заявки", sortType: "text", sortValue: getApplicationPurpose, render: (application) => escapeHtml(getApplicationPurpose(application)) },
    { key: "initiator", label: "Инициатор заявки", sortType: "text", sortValue: getApplicationInitiator, render: (application) => escapeHtml(getApplicationInitiator(application)) },
    { key: "initiatorSegment", label: "Сегмент инициатора", sortType: "text", sortValue: getApplicationRegistrySegment, render: (application) => escapeHtml(getApplicationRegistrySegment(application)) },
    { key: "client", label: "Клиент", sortType: "text", sortValue: getApplicationClientName, render: (application) => escapeHtml(getApplicationClientName(application)) },
    { key: "inn", label: "ИНН клиента", render: (application) => escapeHtml(getApplicationInn(application)) },
    { key: "status", label: "Статус заявки", sortType: "text", sortValue: (application) => getApplicationRegistryStatus(application.status), render: (application) => badge(getApplicationRegistryStatus(application.status)) },
    { key: "tasks", label: "Задачи", render: (application) => renderApplicationTaskLinks(application) },
    { key: "collateral", label: "Залог", render: (application) => renderApplicationCollateralLinks(application) },
    { key: "contract", label: "Кредитный договор", headerMarkup: "Кредитный<br>договор", headerClass: "application-contract-header", render: (application) => renderApplicationContractLinks(application) },
    ...(includeDeleteAction ? [{ key: "actions", label: "Действия", headerMarkup: '<span class="visually-hidden">Действия</span>', headerClass: "application-actions-header", draggable: false, render: (application) => renderApplicationRegistryDeleteAction(application) }] : [])
  ];
}

function isApplicationVisibleInRegistry(application, role = getRole()) {
  return role?.id !== "initiator" || getApplicationInitiator(application) === role.user;
}

function renderApplicationsRegistry() {
  const role = getRole();
  const filters = state.filters.applications;
  const rows = (state.data.applications || []).filter((application) =>
    isApplicationVisibleInRegistry(application, role)
    && matches(application.number || application.id, filters.number)
    && matchesExact(getApplicationType(application), filters.type)
    && matchesExact(getApplicationSubtype(application), filters.subtype)
    && matchesExact(getApplicationPurpose(application), filters.purpose)
    && matchesExact(getApplicationInitiator(application), filters.initiator)
    && matchesExact(getApplicationRegistrySegment(application), filters.initiatorSegment)
    && matches(getApplicationClientSearchText(application), filters.clientName)
    && matchesAnyExact(getApplicationProducts(application), filters.product)
    && matchesSelectedValues(getApplicationRegistryStatus(application.status), filters.status)
    && matches(getApplicationContractSearchText(application), filters.contractNumber)
    && matches(getApplicationCollateralSearchText(application), filters.collateralId)
    && matches(getApplicationCollateralNameSearchText(application), filters.collateralName)
    && matchesDateOnlyRange(getApplicationCreatedDate(application), filters.createdFrom, filters.createdTo)
  );
  const pageKey = "applications";
  const allColumns = getApplicationRegistryColumns(hasPermission(role, "appDelete"));
  const visibleColumns = getVisibleRegistryColumns(allColumns, "applications");
  const deleteActionColumn = allColumns.find((column) => column.key === "actions");
  const columns = deleteActionColumn
    ? [...visibleColumns.filter((column) => column.key !== "actions"), deleteActionColumn]
    : visibleColumns;
  const sortedRows = sortRegistryRows(rows, allColumns, getRegistrySortEntries("applications"));
  const pageData = getRegistryPageData(sortedRows, pageKey);
  const filterGridMarkup = `
    <div class="filter-grid registry-filter-grid applications-filter-grid">
      ${filterInput("applications", "number", "Номер заявки")}
      ${filterSelect("applications", "type", "Тип заявки", getApplicationTypeFilterOptions())}
      ${filterSelect("applications", "subtype", "Подтип заявки", getApplicationSubtypeFilterOptions())}
      ${filterSelect("applications", "purpose", "Цель заявки", getApplicationPurposeOptions())}
      ${filterMultiSelect("applications", "status", "Статус заявки", getApplicationStatusOptions())}
      ${filterSelect("applications", "initiator", "Инициатор заявки", getApplicationInitiatorOptions())}
      ${filterSelect("applications", "initiatorSegment", "Сегмент инициатора", getApplicationInitiatorSegmentOptions())}
      ${filterInput("applications", "clientName", "Клиент", "Наименование, ФИО или ИНН")}
      ${filterSelect("applications", "product", "Продукт", getApplicationProductOptions())}
      ${filterInput("applications", "contractNumber", "Кредитный договор")}
      ${filterInput("applications", "collateralId", "Идентификатор залога")}
      ${filterInput("applications", "collateralName", "Наименование залога")}
      ${filterDateRange("applications", "createdFrom", "createdTo", "Дата создания заявки")}
      <button class="btn btn-secondary" data-action="reset-filters" data-scope="applications">Сбросить</button>
    </div>
  `;
  return `
    <section class="registry-work-area registry-work-area-applications">
      ${renderRegistryPageHeader("Реестр заявок",
        hasPermission(role, "appCreateEdit") ? `<button class="btn btn-primary" data-route="/app/applications/new">Создать заявку</button>` : "")}
      ${renderRegistryFilterPanel("applications", filterGridMarkup)}
      <section class="panel table-panel" data-registry-table="applications" tabindex="-1">
        <div class="registry-results-summary">${renderRegistryResultCount("applications", rows.length)}</div>
        <div class="registry-table-scroll">
        <table class="applications-table${deleteActionColumn ? " has-delete-action" : ""}" aria-label="Реестр заявок" data-registry-column-table data-registry-scope="applications" style="min-width:${getRegistryTableMinWidth(columns, "applications")}px">
          ${renderRegistryColumnWidths(columns, "applications")}
          <thead><tr>${columns.map((column) => renderRegistrySortHeader(column, "applications")).join("")}</tr></thead>
          <tbody>${pageData.rows.length ? pageData.rows.map((application) => `
            <tr>${columns.map((column) => `<td>${column.render(application)}</td>`).join("")}</tr>
          `).join("") : `<tr><td colspan="${columns.length}"><span class="muted">Заявки не найдены</span></td></tr>`}</tbody>
        </table>
        </div>
        ${renderRegistryPagination(pageKey, pageData)}
      </section>
      ${renderApplicationRegistryCollateralDrawer()}
    </section>
  `;
}

function renderCollateralControlPanel(rows, activeKpi = "") {
  const controlRows = getCollateralControlRows(rows);
  return `
    <section class="panel chart-panel collateral-control-panel">
      <div class="panel-title">
        <div>
          <h2>Контроль залогов по видам имущества</h2>
        </div>
        <span class="panel-note">${controlRows.length} типов</span>
      </div>
      <div class="collateral-control-grid">
        <div class="collateral-control-head" aria-hidden="true">
          <span>Вид имущества</span>
          <span>Залоговая стоимость</span>
          <span>Контрольные сигналы</span>
        </div>
        ${controlRows.length ? controlRows.map((row) => {
          const controlFilter = getCollateralControlKpi(row.type);
          return `
          <button type="button" class="collateral-control-row ${row.tone} ${activeKpi === controlFilter ? "active" : ""}" data-action="registry-kpi" data-scope="collaterals" data-filter="kpi" data-value="${escapeHtml(controlFilter)}">
            <span class="collateral-control-type">
              <strong>${escapeHtml(row.type)}</strong>
              <small>${row.count} шт. · с сигналами: ${row.attentionCount}</small>
            </span>
            <span class="collateral-control-value">
              <span class="collateral-control-bar"><i style="width:${row.share}%"></i></span>
              <strong>${escapeHtml(formatShortMoney(row.pledgeValue))}</strong>
            </span>
            <span class="collateral-control-signals">
              ${renderCollateralControlMetric(row.criticalCount, "Риск", "danger")}
              ${renderCollateralControlMetric(row.appraisalCount, "Оценка", "warning")}
              ${renderCollateralControlMetric(row.insuranceCount, "Полис", "warning")}
              ${renderCollateralControlMetric(row.monitoringCount, "Осмотр", "warning")}
            </span>
          </button>
        `;
        }).join("") : `<div class="empty-state">Нет объектов в выбранном срезе</div>`}
      </div>
    </section>
  `;
}

function getCollateralControlKpi(type) {
  return `control:${type}`;
}

function getCollateralControlKpiType(kpi) {
  const prefix = "control:";
  return String(kpi || "").startsWith(prefix) ? String(kpi).slice(prefix.length) : "";
}

function getCollateralControlRows(rows) {
  const totalPledge = sumBy(rows, (item) => item.pledgeValue);
  const grouped = rows.reduce((acc, item) => {
    acc[item.type] = acc[item.type] || [];
    acc[item.type].push(item);
    return acc;
  }, {});
  return Object.entries(grouped).map(([type, items]) => {
    const pledgeValue = sumBy(items, (item) => item.pledgeValue);
    const criticalCount = items.filter((item) => riskTone(item) === "danger").length;
    const appraisalCount = items.filter(hasCollateralAppraisalIssue).length;
    const insuranceCount = items.filter(hasCollateralInsuranceIssue).length;
    const monitoringCount = items.filter(hasCollateralMonitoringIssue).length;
    const attentionCount = new Set(items
      .filter((item) => riskTone(item) === "danger" || hasCollateralAppraisalIssue(item) || hasCollateralInsuranceIssue(item) || hasCollateralMonitoringIssue(item))
      .map((item) => item.id)).size;
    return {
      type,
      count: items.length,
      pledgeValue,
      criticalCount,
      appraisalCount,
      insuranceCount,
      monitoringCount,
      attentionCount,
      share: totalPledge ? Math.max(3, Math.round((pledgeValue / totalPledge) * 100)) : 0,
      tone: criticalCount ? "danger" : attentionCount ? "warning" : "ok"
    };
  }).sort((a, b) =>
    b.criticalCount - a.criticalCount
    || b.attentionCount - a.attentionCount
    || b.pledgeValue - a.pledgeValue
    || a.type.localeCompare(b.type, "ru")
  );
}

function renderCollateralControlMetric(value, label, tone) {
  return `
    <span class="collateral-control-metric ${value ? tone : "ok"}">
      <strong>${value}</strong>
      <small>${escapeHtml(label)}</small>
    </span>
  `;
}

function hasCollateralAppraisalIssue(collateral) {
  return collateral.appraisalStatus === "Истекает" || collateral.appraisalStatus === "Просрочена";
}

function hasCollateralInsuranceIssue(collateral) {
  const premiumStatus = collateral.insurance?.premiumStatus || "";
  return collateral.insuranceStatus === "Истекает"
    || collateral.insuranceStatus === "Не оплачена"
    || (premiumStatus && premiumStatus !== "Оплачена");
}

function hasCollateralMonitoringIssue(collateral) {
  const nextInspectionDays = daysUntil(collateral.monitoring?.nextInspection);
  return nextInspectionDays !== null && nextInspectionDays <= 30;
}

function daysUntil(dateValue) {
  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return null;
  const today = new Date("2026-06-18T00:00:00");
  return Math.ceil((date - today) / 86400000);
}

function getInsurancePolicyRows() {
  return state.data.collaterals.map((collateral) => {
    const insurance = collateral.insurance || {};
    const contract = getContract(collateral.contractIds?.[0]);
    const due = insurance.to || collateral.insuranceDue || "";
    const days = daysUntil(due);
    return {
      id: insurance.policy || `INS-${collateral.id}`,
      company: insurance.company || "Не выбрана",
      collateral,
      contract,
      clientId: collateral.clientId,
      clientName: collateral.clientName,
      amount: Number(insurance.amount || 0),
      premiumStatus: insurance.premiumStatus || "Не проверено",
      status: collateral.insuranceStatus || "Не указано",
      from: insurance.from || "-",
      to: due || "-",
      daysLeft: days,
      source: insurance.source || collateral.source || "-"
    };
  });
}

