function getInspectionChecklistReference(code) {
  if (code.startsWith("AUTO-DOCS")) return { source: "ПТС/ПСМ/ЭПТС/ЭПСМ, СТС, ДКП, документы оплаты, особые отметки", documents: "ПТС/ПСМ/СТС или электронные сведения, договор купли-продажи, акт приема-передачи, таможенные документы при наличии" };
  if (code.startsWith("AUTO-INSPECT")) return { source: "Физический осмотр ТС/СМ, фото/видео, показания приборов", documents: "Акт осмотра ТС/СМ, фото обязательных ракурсов, фото VIN/PIN/рамы/шильдика, фото пробега/моточасов" };
  if (code === "AUTO-RISK-FNP") return { source: "ФНП, проверка по VIN/PIN/номеру шасси/кузова и залогодателю", documents: "Скриншот или выписка из реестра уведомлений о залоге движимого имущества" };
  if (code === "AUTO-RISK-RESTRICTIONS") return { source: "SpectrumData или аналогичный внешний источник, проверка по VIN/госномеру", documents: "Отчет внешнего источника по ДТП, запретам, арестам, розыску и регистрационным ограничениям" };
  if (code.startsWith("AUTO-RISK")) return { source: "Визуальный осмотр, внешний источник, договорные и регистрационные документы", documents: "Фото повреждений, отчет внешней проверки, документы на дополнительное оборудование при наличии" };
  if (code.startsWith("AUTO-FILE")) return { source: "Итоговые материалы осмотра", documents: "Акт осмотра ТС/СМ, фото фронт/зад/боковые стороны, салон, пробег/моточасы, VIN/PIN/шильдик, дефекты" };

  if (code.startsWith("REALTY-RIGHTS")) return { source: "ЕГРН, правоустанавливающие документы, сведения о собственниках и ограничениях", documents: "Выписка ЕГРН, договор-основание, сведения об аренде/обременениях при наличии" };
  if (code.startsWith("REALTY-ID")) return { source: "ЕГРН, кадастровые сведения, техническая документация, акт осмотра", documents: "Выписка ЕГРН, кадастровый план, технический план/паспорт, фото объекта и участка" };
  if (code.startsWith("REALTY-STATE")) return { source: "Физический осмотр объекта и территории", documents: "Акт проверки недвижимого имущества, фото фасада/помещений/инженерных систем/подъездных путей, документы аренды при наличии" };
  if (code.startsWith("REALTY-FILE")) return { source: "Итоговые материалы осмотра и данные сделки", documents: "Акт проверки недвижимого имущества, фото объекта, договор купли-продажи или иной документ цены приобретения" };

  if (code.startsWith("EQ-ID")) return { source: "Документы поставки и физическая сверка маркировки", documents: "Инвойс, договор поставки, акт ввода, фото серийного/заводского номера, инвентарные сведения" };
  if (code.startsWith("EQ-STATE")) return { source: "Осмотр оборудования, запуск или демонстрация технического состояния, условия эксплуатации", documents: "Акт осмотра оборудования, фото общего вида, маркировки, наработки, места эксплуатации, документы аренды при наличии" };
  if (code.startsWith("EQ-FILE")) return { source: "Итоговые материалы осмотра оборудования", documents: "Акт осмотра оборудования, фото обязательных ракурсов, фото дефектов и шильдиков" };

  if (code.startsWith("GOODS-ACCOUNT")) return { source: "Складская справка, учетные данные клиента и фактический пересчет", documents: "Складская справка залогодателя, акт проверки товаров в обороте, учетные ведомости" };
  if (code.startsWith("GOODS-STATE")) return { source: "Осмотр места хранения и товарных остатков", documents: "Акт проверки товаров в обороте, фото мест хранения, фото товаров и видимых дефектов" };
  if (code.startsWith("GOODS-CONTROL")) return { source: "Осмотр склада, контроль доступа, охраны и пожарной безопасности", documents: "Акт проверки товаров в обороте, фото охраны/видеонаблюдения/пожарной сигнализации, схема доступа при наличии" };

  if (code.startsWith("ANIMAL-ID")) return { source: "Осмотр поголовья, учетные данные, идентификационные признаки", documents: "Реестр поголовья, инвентаризационная ведомость, фото бирок/клейм/чипов, данные по живой массе" };
  if (code.startsWith("ANIMAL-VET")) return { source: "Ветеринарные документы, технологические карты, осмотр условий содержания", documents: "Ветеринарные журналы, программа вакцинации, документы по кормам, технологическая карта содержания" };
  if (code.startsWith("ANIMAL-CONTROL")) return { source: "Осмотр фермы, санитарные ограничения, фото/видео фиксация", documents: "Акт осмотра животных, фото/видео материалов, комментарий по ограничениям доступа" };

  if (code.startsWith("DOC-SM")) return { source: "ПСМ/ЭПСМ, свидетельство о регистрации СМ, договор приобретения, акт приема-передачи, документы оплаты и учетные сведения", documents: "ПСМ/ЭПСМ, свидетельство о регистрации самоходной машины, договор-основание, акт приема-передачи, платежные документы, счет 01 / справка о балансовой стоимости" };
  if (code.startsWith("DOC-AIR")) return { source: "Реестр воздушных судов, регистрационные и эксплуатационные документы, документы на базирование и ремонт", documents: "Свидетельство о регистрации ВС, выписка из реестра ВС об отсутствии обременений, документ-основание права, сертификат летной годности, формуляр ВС и двигателей, документы на место базирования, сертификат эксплуатанта, договоры с авиаремонтными организациями" };
  if (code.startsWith("DOC-LAND")) return { source: "ЕГРН, правоустанавливающие документы, кадастровые сведения и документы об ограничениях", documents: "Выписка ЕГРН, документ-основание права собственности, сведения о кадастровом номере, площади, категории земель и разрешенном использовании, документы аренды, сервитутов и иных обременений, счет 01 / справка о балансовой стоимости при необходимости" };
  if (code.startsWith("DOC-RIGHTS")) return { source: "Правоустанавливающие документы, договоры приобретения, регистрационные свидетельства и сведения залогодателя", documents: "Документ-основание, подтверждение права собственности, реквизиты залогодателя, ИНН" };
  if (code.startsWith("DOC-REGISTRY")) return { source: "АБС, внешние реестры, регистрационные и кадастровые сведения", documents: "Выписки и свидетельства по объекту, сведения об обременениях, запретах и статусе записи" };
  if (code.startsWith("DOC-FILE")) return { source: "Пакет документов задачи и карточка активного залога", documents: "Реестр документов, страховые документы или основание отсутствия страхования, итоговый лист проверки" };

  return { source: "Осмотр объекта, документы по объекту и данные карточки залога", documents: "Акт осмотра, фотофиксация, правоустанавливающие и идентификационные документы" };
}

function inspectionChecklistItem(code, name, okLabel, warnLabel, badLabel, defaultValue = "ok") {
  const reference = getInspectionChecklistReference(code);
  return {
    code,
    name,
    source: reference.source,
    documents: reference.documents,
    defaultValue,
    values: [
      { code: "ok", label: okLabel, status: "ok" },
      { code: "warn", label: warnLabel, status: "warn" },
      { code: "bad", label: badLabel, status: "bad" }
    ]
  };
}

function renderTaskFormGrid(fields, className = "task-form-grid") {
  return `
    <div class="${className}">
      ${fields.map((field) => renderTaskField(field)).join("")}
    </div>
  `;
}

function renderTaskField(field) {
  const value = field.value ?? "";
  const classes = ["task-field", field.wide ? "wide" : "", field.full ? "full-span" : ""].filter(Boolean).join(" ");
  const extraAttrs = field.attrs ? ` ${field.attrs}` : "";
  if (field.textarea) {
    return `<label class="${classes}">${escapeHtml(field.label)}<textarea ${field.readonly ? "readonly" : ""}${extraAttrs}>${escapeHtml(value)}</textarea></label>`;
  }
  if (field.type === "select") {
    const options = getTaskFieldSelectOptions(field.options || [], value);
    return `<label class="${classes}">${escapeHtml(field.label)}<select${extraAttrs}>${options.map((option) => `<option value="${escapeHtml(option.value)}" ${String(option.value) === String(value) ? "selected" : ""}>${escapeHtml(option.label)}</option>`).join("")}</select></label>`;
  }
  if (field.type === "multiselect") {
    return renderTaskMultiSelectField(field, classes, extraAttrs);
  }
  return `<label class="${classes}">${escapeHtml(field.label)}<input type="${escapeHtml(field.type || "text")}" value="${escapeHtml(value)}" ${field.readonly ? "readonly" : ""}${extraAttrs}></label>`;
}

function renderTaskMultiSelectField(field, classes, extraAttrs = "") {
  const selectedValues = normalizeMultiValue(field.value);
  const selectedSet = new Set(selectedValues);
  const options = getTaskFieldSelectOptions(field.options || [], "");
  const optionByValue = new Map(options.map((option) => [String(option.value), option]));
  const summaryValues = selectedValues
    .map((value) => optionByValue.get(String(value))?.label || value)
    .filter(Boolean);
  const summary = summaryValues.length ? summaryValues.join(", ") : (field.placeholder || "Не выбрано");
  return `
    <div class="${classes} task-field-multiselect">
      <span class="task-field-label">${escapeHtml(field.label)}</span>
      <details class="task-multi-select">
        <summary>${escapeHtml(summary)}</summary>
        <div class="task-multi-select-options">
          ${options.map((option) => `
            <label>
              <input type="checkbox" value="${escapeHtml(option.value)}" ${selectedSet.has(String(option.value)) ? "checked" : ""} ${field.readonly ? "disabled" : ""}${extraAttrs}>
              <span>${escapeHtml(option.label)}</span>
            </label>
          `).join("")}
        </div>
      </details>
    </div>
  `;
}

function normalizeMultiValue(value) {
  if (Array.isArray(value)) return value.map((item) => String(item || "").trim()).filter(Boolean);
  if (value === undefined || value === null || value === "") return [];
  return String(value).split(/[;,]/).map((item) => item.trim()).filter(Boolean);
}

function updateTaskMultiSelectSummary(detailsEl) {
  if (!detailsEl) return;
  const summaryEl = detailsEl.querySelector("summary");
  if (!summaryEl) return;
  const selected = [...detailsEl.querySelectorAll("input[type='checkbox']:checked")]
    .map((item) => item.closest("label")?.querySelector("span")?.textContent?.trim() || item.value)
    .filter(Boolean);
  summaryEl.textContent = selected.length ? selected.join(", ") : "Не выбрано";
}

function getTaskFieldSelectOptions(options, currentValue) {
  const rows = [];
  const seen = new Set();
  [...options, currentValue]
    .filter((item) => item !== undefined && item !== null && item !== "")
    .forEach((item) => {
      const option = typeof item === "object"
        ? {
          value: item.value ?? item.id ?? item.name ?? item.label ?? "",
          label: item.label ?? item.name ?? item.value ?? item.id ?? ""
        }
        : { value: item, label: item };
      const key = String(option.value);
      if (!key || seen.has(key)) return;
      seen.add(key);
      rows.push(option);
    });
  return rows;
}

function renderGoodsInventoryCheckTable(task, collateral) {
  if (collateral?.type !== "Товары в обороте") return "";
  const rows = getGoodsInventoryRows(collateral);
  return `
    <section class="panel table-panel goods-inventory-check-panel">
      <div class="panel-title">
        <div><h2>Проверка товаров по складской справке</h2></div>
        ${badge(`${rows.length} строки`, "info")}
      </div>
      <table>
        <thead>
          <tr><th>Вид имущества</th><th>Артикул</th><th>Ед. изм.</th><th>Кол-во по данным учета клиента</th><th>Стоимость по данным учета клиента</th><th>Кол-во фактически</th><th>Соответствие данным учета</th></tr>
        </thead>
        <tbody>${rows.map((row) => `
          <tr>
            <td>${escapeHtml(row.kind)}</td>
            <td>${escapeHtml(row.article)}</td>
            <td>${escapeHtml(row.unit)}</td>
            <td><input type="number" value="${escapeHtml(row.accountingQty)}" aria-label="Количество по учету ${escapeHtml(row.article)}"></td>
            <td><input type="number" value="${escapeHtml(row.accountingValue)}" aria-label="Стоимость по учету ${escapeHtml(row.article)}"></td>
            <td><input type="number" value="${escapeHtml(row.actualQty)}" aria-label="Количество фактически ${escapeHtml(row.article)}"></td>
            <td>
              <select aria-label="Соответствие ${escapeHtml(row.article)}">
                ${["Соответствует", "Есть расхождения", "Не соответствует"].map((option) => `<option ${option === row.match ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}
              </select>
            </td>
          </tr>
        `).join("")}</tbody>
      </table>
    </section>
  `;
}

function getGoodsInventoryRows(collateral) {
  const totalValue = Number(collateral?.marketValue || collateral?.pledgeValue || 0);
  const mainKind = collateral?.fields?.["Группа товаров"] || collateral?.fields?.["Вид товара в обороте"] || collateral?.description || "Товары в обороте";
  const firstValue = Math.round(totalValue * 0.6);
  const secondValue = Math.max(0, totalValue - firstValue);
  return [
    { kind: mainKind, article: "LOT-01", unit: "шт.", accountingQty: 1200, accountingValue: firstValue, actualQty: 1200, match: "Соответствует" },
    { kind: mainKind, article: "LOT-02", unit: "шт.", accountingQty: 800, accountingValue: secondValue, actualQty: 800, match: "Соответствует" }
  ];
}

function getLatestCompletedInspection(collateral) {
  const schedule = collateral?.monitoring?.schedule || [];
  return [...schedule].reverse().find((item) => item.status === "Завершен") || schedule[0] || {};
}

function renderPledgeOperationBlock(task, collateral) {
  const collaterals = getTaskCollaterals(task);
  const taskContracts = getTaskContracts(task, collaterals);
  const contract = getTaskActiveContract(task, collateral);
  const commonContract = taskContracts.length === 1 ? taskContracts[0] : contract;
  const registrationScenario = getTaskRegistrationScenario(task);
  const registrationStatus = task?.registrationStatuses?.[collateral?.id] || collateral?.encumbrances?.[0]?.status || "Готовится регистрация";
  const externalService = getRegistrationExternalService(registrationScenario, collateral, task);
  const externalInstruction = getRegistrationExternalInstruction(registrationScenario, externalService);
  const registrationAttrs = (field) => `data-registration-field="${field}" data-task="${escapeHtml(task.id)}" data-collateral="${escapeHtml(collateral?.id || "")}"`;
  return `
    <section class="task-specific-form pledge-operation-form">
      <section class="panel task-form-panel pledge-registration-panel">
        <div class="panel-title">
          <div><h2>Регистрационные данные</h2></div>
          ${badge(registrationStatus, "info")}
        </div>
        ${renderTaskFormGrid([
          { label: "Объект залога", value: collateral?.description || "Объект залога", wide: true },
          { label: "Вид залога", value: collateral?.type || "Вид залога" },
          { label: "Общий договор по задаче", value: commonContract?.number || task.contractNumber || task.contractId || "Договор не указан" },
          { label: "Количество объектов", value: collaterals.length ? String(collaterals.length) : "1" },
          { label: "Клиент по договору", value: commonContract?.clientName || contract?.clientName || "Клиент по договору" },
          { label: "Залогодатель", value: collateral?.clientName || "Залогодатель" },
          { label: "ИНН залогодателя", value: collateral?.clientId || "ИНН не указан" },
          { label: "Профильный идентификатор объекта", value: getCollateralObjectIdentifier(collateral) },
          { label: "Сценарий регистрации", value: registrationScenario, type: "select", options: REGISTRATION_SCENARIOS, attrs: registrationAttrs("scenario"), wide: true },
          { label: "Статус регистрации", value: registrationStatus, type: "select", options: ["Готовится регистрация", "Проверяется комплект", "Передано в АБС", "Зарегистрировано", "Требует уточнения", "Ошибка регистрации"], attrs: registrationAttrs("status") },
          { label: "Внешний сервис", value: externalService, readonly: true },
          { label: "Ссылка / инструкция перехода", value: externalInstruction, readonly: true, wide: true },
          { label: "Основание операции", value: "Регистрация предметов залога по заявке и проверенному комплекту документов.", textarea: true, wide: true }
        ], "task-form-grid compact")}
      </section>
      ${renderPledgeRegistrationResultPanel(task, collateral, registrationStatus)}
      <section class="panel integration-call">
        <h2>Внешний контур регистрации</h2>
        <p>На этапе 1 регистратор выполняет действие во внешнем контуре вручную и фиксирует результат в карточке задачи.</p>
        <button class="btn btn-primary" data-action="open-registration-instruction" data-task="${task.id}">Открыть инструкцию</button>
      </section>
    </section>
  `;
}

function getRegistrationExternalService(scenario, collateral, task = null) {
  const application = getTaskApplication(task);
  const segment = application?.initiatorSegment || task?.initiatorSegment || "";
  if (scenario === REGISTRATION_SCENARIO_MOVABLE) return "NotCom";
  if (scenario === REGISTRATION_SCENARIO_REAL_ESTATE_VISIT) return "МФЦ / Росреестр";
  if (scenario === REGISTRATION_SCENARIO_REAL_ESTATE_ELECTRONIC) {
    return /рознич/i.test(segment) ? "СКБ-Техно" : "Технокад";
  }
  return getCollateralRegistrationScenario(collateral) === REGISTRATION_SCENARIO_MOVABLE ? "NotCom" : "МФЦ / Росреестр";
}

function getRegistrationExternalInstruction(scenario, service) {
  if (service === "NotCom") return "Перейти во внешний контур NotCom и вручную зарегистрировать уведомление о залоге движимого имущества.";
  if (service === "МФЦ / Росреестр") return "Подготовить пакет для личной подачи и зафиксировать результат регистрации недвижимости.";
  if (service === "Технокад") return "Перейти в Технокад и выполнить электронную регистрацию недвижимости для корпоративного сегмента.";
  if (service === "СКБ-Техно") return "Перейти в СКБ-Техно и выполнить электронную регистрацию недвижимости для розничного сегмента.";
  return "Открыть внешний контур регистрации и зафиксировать регистрационный номер или ошибку.";
}

function renderPledgeRegistrationResultPanel(task, collateral, registrationStatus) {
  const registrationNumber = task?.registrationNumbers?.[collateral?.id] || collateral?.encumbrances?.[0]?.number || "";
  const registrationError = task?.registrationErrors?.[collateral?.id] || (/ошибка/i.test(registrationStatus) ? "Ошибка внешнего контура требует уточнения и возврата на инициатора." : "");
  const showRegistrationError = shouldShowRegistrationErrorField(task, collateral, registrationStatus, registrationNumber);
  const registrationAttrs = (field) => `data-registration-field="${field}" data-task="${escapeHtml(task.id)}" data-collateral="${escapeHtml(collateral?.id || "")}"`;
  const fields = [
    { label: "Регистрационный номер", value: registrationNumber, placeholder: "Заполняется после успешной регистрации", attrs: registrationAttrs("number"), wide: true },
    ...(showRegistrationError ? [{ label: "Текст ошибки внешней регистрации", value: registrationError, textarea: true, attrs: registrationAttrs("error"), wide: true }] : [])
  ];
  return `
    <section class="panel task-form-panel registration-result-panel">
      <div class="panel-title">
        <div><h2>Результат регистрации</h2></div>
      </div>
      ${renderTaskFormGrid(fields, "task-form-grid compact")}
    </section>
  `;
}

function shouldShowRegistrationErrorField(task, collateral, registrationStatus, registrationNumber) {
  if (String(registrationNumber || "").trim()) return false;
  if (/ошибка|требует уточнения|не зарегистр/i.test(String(registrationStatus || ""))) return true;
  const expertOutcome = getTaskExpertConclusionOutcome(task?.expertOutcome || getTaskExpertDefaults(task, collateral ? [collateral] : getTaskCollaterals(task)).result);
  return expertOutcome === "Отрицательное";
}

function renderCollateralObjectCheckTable(task, collateral, options = {}) {
  const context = options.context || "registration";
  const rows = getCollateralObjectCheckRows(task, collateral, context);
  const editable = Boolean(options.editable && task);
  const summary = getObjectCheckSummary(rows);
  const showEvidence = context === "collateral";
  const headers = ["Проверка", "Источник", "Дата проверки", "Результат", "Статус", "Комментарий"];
  if (showEvidence) headers.push("Основание");
  return `
    <section class="panel table-panel object-checks-panel">
      <div class="panel-title">
        <div><h2>Проверка предмета залога</h2></div>
        ${badge(summary.label, summary.tone)}
      </div>
      <div class="table-wrap compact-table">
        <table class="object-checks-table ${showEvidence ? "object-checks-table--with-evidence" : "object-checks-table--task"}">
          <thead><tr>${headers.map((header) => `<th>${escapeHtml(header)}</th>`).join("")}</tr></thead>
          <tbody>${rows.map((row) => `
            <tr>
              <td><strong>${escapeHtml(row.name)}</strong>${row.note ? `<small>${escapeHtml(row.note)}</small>` : ""}</td>
              <td>${escapeHtml(row.source || "-")}</td>
              <td>${escapeHtml(row.checkedAt || "-")}</td>
              <td>${escapeHtml(row.result || "-")}</td>
              <td>${renderObjectCheckStatusCell(task, collateral, row, editable)}</td>
              <td>${renderObjectCheckCommentCell(task, collateral, row, editable)}</td>
              ${showEvidence ? `<td>${escapeHtml(row.evidence || "-")}</td>` : ""}
            </tr>
          `).join("")}</tbody>
        </table>
      </div>
    </section>
  `;
}

function getObjectCheckSummary(rows = []) {
  if (!rows.length) return { label: "Нет проверок", tone: "neutral" };
  if (rows.some((row) => /не пройд/i.test(String(row.status || "")))) return { label: "Есть блокер", tone: "danger" };
  if (rows.some((row) => /контрол|ожидает|не проверено/i.test(String(row.status || "")))) return { label: "Требует контроля", tone: "warn" };
  return { label: "Готово", tone: "ok" };
}

function renderObjectCheckStatusCell(task, collateral, row, editable = false) {
  if (!editable) return badge(row.status || "-", pledgeCheckStatusTone(row.status));
  return renderPledgeCheckStatusSelect(task, collateral, row);
}

function renderObjectCheckCommentCell(task, collateral, row, editable = false) {
  if (!editable) return escapeHtml(row.comment || "-");
  return `
    <textarea class="object-check-comment-input"
      data-pledge-check-comment
      data-task="${escapeHtml(task?.id || "")}"
      data-collateral="${escapeHtml(collateral?.id || "")}"
      data-check="${escapeHtml(row.id)}"
      aria-label="Комментарий по проверке ${escapeHtml(row.name)}">${escapeHtml(row.comment || "")}</textarea>
  `;
}

function renderPledgeCheckStatusSelect(task, collateral, row) {
  const options = PLEDGE_CHECK_STATUS_OPTIONS
    .map((status) => `<option value="${escapeHtml(status)}" ${status === row.status ? "selected" : ""}>${escapeHtml(status)}</option>`)
    .join("");
  return `
    <select class="pledge-check-status-select ${pledgeCheckStatusTone(row.status)}"
      data-pledge-check-status
      data-task="${escapeHtml(task?.id || "")}"
      data-collateral="${escapeHtml(collateral?.id || "")}"
      data-check="${escapeHtml(row.id)}"
      aria-label="Статус проверки ${escapeHtml(row.name)}">
      ${options}
    </select>
  `;
}

function getPledgeCheckRows(taskOrCollateral, maybeCollateral) {
  const hasTask = Boolean(maybeCollateral);
  const task = hasTask ? taskOrCollateral : null;
  const collateral = hasTask ? maybeCollateral : taskOrCollateral;
  return getCollateralObjectCheckRows(task, collateral, "registration");
}

function getCollateralObjectCheckRows(task, collateral, context = "registration") {
  const external = collateral?.externalData || {};
  const type = String(collateral?.type || "");
  const identifier = getCollateralObjectIdentifier(collateral) || collateral?.id || "-";
  const sourceRows = getCollateralExternalRows(collateral).filter((row) => row.applicable);
  const row = (id, name, source, result, status = "Пройдена", options = {}) => ({
    id,
    name,
    source,
    result,
    status: normalizePledgeCheckStatus(status),
    note: [options.code ? `Код ${options.code}` : "", options.note || ""].filter(Boolean).join(" · "),
    comment: options.comment || "",
    checkedAt: options.checkedAt || getObjectCheckDate(task, collateral, sourceRows, source),
    evidence: options.evidence || getObjectCheckEvidence(task, collateral, context)
  });
  const rows = [];

  if (isRealEstateCollateralType(type)) {
    addRealEstateObjectCheckRows(rows, row, collateral, external, context);
  } else if (isSelfPropelledCollateralType(type)) {
    addSelfPropelledObjectCheckRows(rows, row, collateral, external);
  } else if (isAutoVehicleCollateralType(type)) {
    addVehicleObjectCheckRows(rows, row, collateral, external, context, identifier);
  } else if (isEquipmentCollateralType(type)) {
    addEquipmentObjectCheckRows(rows, row, collateral, external);
  } else if (isGoodsCollateralType(type)) {
    addGoodsObjectCheckRows(rows, row, collateral, external);
  } else if (isRailwayCollateralType(type)) {
    addRailwayObjectCheckRows(rows, row, collateral, external);
  } else if (isAircraftCollateralType(type)) {
    addAircraftObjectCheckRows(rows, row, collateral, external);
  } else if (isVesselCollateralType(type)) {
    addVesselObjectCheckRows(rows, row, collateral, external);
  } else if (isAnimalCollateralType(type)) {
    addAnimalObjectCheckRows(rows, row, collateral, external);
  } else if (isPropertyRightsCollateralType(type)) {
    addPropertyRightsObjectCheckRows(rows, row, collateral);
  } else {
    addOtherMovableObjectCheckRows(rows, row, collateral, external);
  }

  const displayTask = task || (context === "collateral" ? getLatestObjectCheckTask(collateral) : null);
  const checkedRows = applyPledgeCheckManualValues(displayTask, collateral, rows);
  const recheck = collateral?.externalData?.profileIdentifierRecheck;
  if (!recheck) return checkedRows;
  const recheckRowId = isRealEstateCollateralType(type)
    ? "n-1-2"
    : isAutoVehicleCollateralType(type) || isSelfPropelledCollateralType(type) ? "ts-1" : "";
  if (!recheckRowId) return checkedRows;
  return checkedRows.map((item) => item.id === recheckRowId
    ? {
        ...item,
        source: recheck.source,
        checkedAt: recheck.requestedAt,
        result: `Повторная проверка по идентификатору ${recheck.identifier} ожидает ответа источника.`,
        status: "Не проверено"
      }
    : item);
}

function addRealEstateObjectCheckRows(rows, row, collateral, external, context) {
  const fields = collateral?.fields || {};
  const isBuildingLike = /здание|помещен|квартира|склад|окс/i.test(joinCheckResult([fields["Вид объекта"], fields["Подвид"], collateral?.description]));
  const identityResult = joinCheckResult([
    fields["Кадастровый номер"],
    collateral?.address
  ]) || "Кадастровый номер и адрес объекта сверены с ЕГРН.";
  const parametersResult = joinCheckResult([
    fields["Площадь"] || fields["Площадь, кв.м"] || fields["Площадь строений"],
    fields["Назначение"] || fields["Назначение объекта"] || fields["Вид объекта"],
    fields["Категория земель"] || fields["Вид разрешенного использования участка"]
  ]) || "Площадь, назначение и основные характеристики объекта сверены с ЕГРН.";
  const restrictionsResult = joinCheckResult([
    external["Аресты"],
    external["Запреты"] || external["Ограничения"],
    external["Судебные ограничения"],
    external["Внешний залоговый реестр"]
  ]) || "Аресты, запреты и незаявленные обременения не выявлены.";
  rows.push(
    row(
      "n-1-1",
      "Право собственности и правообладатель",
      "СКБ-Техно, выписка ЕГРН",
      external["Право собственности"] || "Право собственности подтверждено; правообладатель соответствует залогодателю или согласованной схеме владения.",
      "Пройдена",
      { code: "Н-1.1" }
    ),
    row(
      "n-1-2",
      "Кадастровый номер и адрес объекта",
      "СКБ-Техно, выписка ЕГРН",
      identityResult,
      "Пройдена",
      { code: "Н-1.2" }
    ),
    row(
      "n-1-3",
      "Площадь, назначение и характеристики объекта",
      "СКБ-Техно/ЕГРН, технические документы",
      parametersResult,
      "Пройдена",
      { code: "Н-1.3" }
    ),
    row(
      "n-1-4",
      "Взаимная привязка ЗУ-ОКС и помещений",
      "СКБ-Техно, выписки ЕГРН по связанным объектам",
      external["Связанные объекты"] || "Связанные земельные участки, ОКС и помещения анализируются по выпискам ЕГРН; при большом составе исполнитель проводит ручной анализ.",
      isRiskText(external["Связанные объекты"]) ? "Требует контроля" : "Пройдена",
      { code: "Н-1.4" }
    ),
    row(
      "n-2-1",
      "Обременения, аресты и запреты регистрационных действий",
      "СКБ-Техно, выписка ЕГРН",
      restrictionsResult,
      hasRiskSignals(external, ["Аресты", "Запреты", "Ограничения", "Судебные ограничения"]) ? "Требует контроля" : "Пройдена",
      { code: "Н-2.1" }
    ),
    row(
      "n-2-2",
      context === "documentary" ? "Долгосрочная аренда и права пользования" : "Зарегистрированная аренда и права пользования",
      "СКБ-Техно/ЕГРН, документы аренды",
      external["Аренда"] || "Долгосрочная аренда и права пользования проверены по ЕГРН; критичные сведения не выявлены.",
      isRiskText(external["Аренда"]) ? "Требует контроля" : "Пройдена",
      { code: "Н-2.2" }
    ),
    row(
      "n-2-3",
      "Новые записи ЕГРН после даты договора ипотеки/залога",
      "СКБ-Техно/ЕГРН, предыдущее заключение/карточка залога",
      external["Сигнал мониторинга"] || (context === "registration"
        ? "Для первичной регистрации строка носит информационный характер; дата договора используется после оформления залога."
        : "Новые неотработанные записи после даты договора не выявлены."),
      context === "registration" ? "Не применимо" : (isRiskText(external["Сигнал мониторинга"]) ? "Требует контроля" : "Пройдена"),
      { code: "Н-2.3" }
    ),
    row(
      "n-3",
      "Комплект документов и дополнительные основания",
      "Документы задачи, матрица обязательности документов",
      "Проверяется наличие выписки ЕГРН, правоустанавливающих документов, документов оплаты, актов приема-передачи, технических документов и документов по обременениям.",
      "Пройдена",
      { code: "Н-3" }
    ),
    row(
      "n-3-1",
      "Наличие нежилых помещений в здании",
      "СКБ-Техно/ЕГРН, выписка ЕГРН",
      isBuildingLike
        ? (external["Нежилые помещения"] || "Перечень кадастровых номеров помещений выводится по выписке ЕГРН здания при наличии связанных объектов.")
        : "Проверка применяется к зданиям и помещениям.",
      isBuildingLike ? "Пройдена" : "Не применимо",
      { code: "Н-3.1" }
    ),
  );
}

