function getObjectCheckDate(task, collateral, sourceRows, source) {
  if (source && !/документы|АБС/i.test(source)) return getRegistrationExternalCheckDate(sourceRows, source, collateral);
  return getTaskObjectCheckDate(task, collateral);
}

function getTaskObjectCheckDate(task, collateral) {
  const lastHistory = task?.history?.slice(-1)?.[0]?.date;
  return lastHistory || task?.createdAt || collateral?.externalData?.["Дата проверки"] || collateral?.updatedAt || "-";
}

function getObjectCheckEvidence(task, collateral, context) {
  if (task?.id) return task.id;
  const latestTask = getLatestObjectCheckTask(collateral);
  if (latestTask?.id) return latestTask.id;
  if (context === "collateral") return collateral?.externalData?.["Выписка"] || collateral?.externalData?.["Внешний отчет"] || "Карточка залога";
  return "Карточка залога";
}

function getLatestObjectCheckTask(collateral) {
  const collateralId = collateral?.id || "";
  if (!collateralId) return null;
  return (state.data.tasks || [])
    .filter((task) => getTaskCollateralIds(task).includes(collateralId))
    .filter((task) => isPledgeOperationTaskType(task.type) || isDocumentaryInspectionTask(task))
    .sort((left, right) => String(getTaskObjectCheckDate(right)).localeCompare(String(getTaskObjectCheckDate(left))))[0] || null;
}

function getObjectCheckSourceSummary(sourceRows = []) {
  return uniqueItems(sourceRows.map((row) => row.source)).join(", ");
}

function isRealEstateCollateralType(type) {
  return /недвиж/i.test(String(type || ""));
}

function isSelfPropelledCollateralType(type) {
  return /самоход|спецтехник/i.test(String(type || "").toLowerCase());
}

function isAutoVehicleCollateralType(type) {
  const value = String(type || "").toLowerCase();
  return !isSelfPropelledCollateralType(value) && /автотранспорт|автомоб|транспортные средства|прицеп|полуприцеп/.test(value);
}

function isVehicleLikeCollateralType(type) {
  return /автотранспорт|самоход/i.test(String(type || "").toLowerCase());
}

function isEquipmentCollateralType(type) {
  return /оборуд/.test(String(type || "").toLowerCase());
}

function isGoodsCollateralType(type) {
  return /товар|тмц|оборот|запас/.test(String(type || "").toLowerCase());
}

function isRailwayCollateralType(type) {
  return /железнодорож|подвижн|вагон/.test(String(type || "").toLowerCase());
}

function isAircraftCollateralType(type) {
  return /воздуш|самолет|самолёт|вертолет|вертолёт/.test(String(type || "").toLowerCase());
}

function isVesselCollateralType(type) {
  return /судн|плавуч|морск|речн|гимс/.test(String(type || "").toLowerCase());
}

function isAnimalCollateralType(type) {
  return /животн|скот|поголов/.test(String(type || "").toLowerCase());
}

function isPropertyRightsCollateralType(type) {
  return /имущественн|прав[ао]|требован|дду/.test(String(type || "").toLowerCase());
}

function joinCheckResult(values = []) {
  return values
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .join("; ");
}

function hasRiskSignals(external = {}, keys = []) {
  return keys.some((key) => isRiskText(external[key]));
}

function applyPledgeCheckManualValues(task, collateral, rows = []) {
  const savedStatuses = task?.registrationCheckStatuses?.[collateral?.id] || {};
  const savedComments = task?.registrationCheckComments?.[collateral?.id] || {};
  return rows.map((row) => ({
    ...row,
    status: PLEDGE_CHECK_STATUS_OPTIONS.includes(normalizePledgeCheckStatus(savedStatuses[row.id])) ? normalizePledgeCheckStatus(savedStatuses[row.id]) : normalizePledgeCheckStatus(row.status),
    comment: savedComments[row.id] || row.comment
  }));
}

function normalizePledgeCheckStatus(status) {
  const value = String(status || "").trim();
  if (value === "Пройдено") return "Пройдена";
  if (value === "Не пройдено") return "Не пройдена";
  return value;
}

function pledgeCheckStatusTone(status) {
  const value = String(status || "").toLowerCase();
  if (value.includes("не пройд")) return "danger";
  if (value.includes("контрол")) return "warn";
  if (value.includes("пройден")) return "ok";
  if (value.includes("не примен")) return "neutral";
  return "info";
}

function updatePledgeCheckStatus(fieldEl) {
  const task = getTask(fieldEl.dataset.task);
  const collateralId = fieldEl.dataset.collateral;
  const checkId = fieldEl.dataset.check;
  if (!task || !collateralId || !checkId) return;
  task.registrationCheckStatuses = task.registrationCheckStatuses || {};
  task.registrationCheckStatuses[collateralId] = task.registrationCheckStatuses[collateralId] || {};
  task.registrationCheckStatuses[collateralId][checkId] = fieldEl.value;
  persistTaskState();
}

function updatePledgeCheckComment(fieldEl) {
  const task = getTask(fieldEl.dataset.task);
  const collateralId = fieldEl.dataset.collateral;
  const checkId = fieldEl.dataset.check;
  if (!task || !collateralId || !checkId) return;
  task.registrationCheckComments = task.registrationCheckComments || {};
  task.registrationCheckComments[collateralId] = task.registrationCheckComments[collateralId] || {};
  task.registrationCheckComments[collateralId][checkId] = fieldEl.value.trim();
  persistTaskState();
}

function updateRegistrationField(fieldEl) {
  const task = getTask(fieldEl.dataset.task);
  const collateralId = fieldEl.dataset.collateral;
  const field = fieldEl.dataset.registrationField;
  if (!task || !field) return;
  if (field === "scenario") {
    task.registrationScenario = fieldEl.value;
  } else if (field === "status" && collateralId) {
    task.registrationStatuses = task.registrationStatuses || {};
    task.registrationStatuses[collateralId] = fieldEl.value;
  } else if (field === "number" && collateralId) {
    task.registrationNumbers = task.registrationNumbers || {};
    task.registrationNumbers[collateralId] = fieldEl.value.trim();
  } else if (field === "error" && collateralId) {
    task.registrationErrors = task.registrationErrors || {};
    task.registrationErrors[collateralId] = fieldEl.value.trim();
  }
  persistTaskState();
}

function renderTaskDocumentsPanel(task, collaterals, activeCollateral) {
  return renderDocumentWidget({
    context: "task",
    ownerId: task.id,
    task,
    documents: getTaskDocumentsForCard(task),
    collaterals,
    activeCollateral,
    title: "Документы",
    subtitle: "Файлы по задаче",
    description: "Отображаются документы текущей задачи, родительской заявки и применимых объектов залога."
  });
}

function getTaskDocumentsForCard(task) {
  const taskDocs = (task?.documents || []).map((doc) => ({
    ...(typeof doc === "string" ? { name: doc } : doc),
    documentSourceContext: "task"
  }));
  const application = getTaskApplication(task);
  const applicationDocs = getApplicationDocumentsForTask(task, application);
  const existingKeys = new Set(taskDocs.map(getTaskDocumentDedupKey));
  const linkedApplicationDocs = applicationDocs.filter((doc) => {
    const key = getTaskDocumentDedupKey(doc);
    if (existingKeys.has(key)) return false;
    existingKeys.add(key);
    return true;
  });
  return [...taskDocs, ...linkedApplicationDocs];
}

function getApplicationDocumentsForTask(task, application) {
  if (!task || !application) return [];
  return (application.documents || [])
    .map((doc) => (typeof doc === "string" ? { name: doc } : { ...doc }))
    .filter((doc) => doesApplicationDocumentApplyToTask(doc, task))
    .map((doc) => ({
      ...doc,
      title: doc.title || "Документы заявки",
      status: doc.status || "Из карточки заявки",
      target: doc.target || "application",
      targetIds: doc.targetIds || [doc.target || "application"],
      applyScope: doc.applyScope || "application",
      applyValue: doc.applyValue || "",
      attachedAt: doc.attachedAt || doc.uploadedAt || doc.createdAt || doc.date || application.createdAt || "",
      author: doc.author || doc.uploadedBy || application.initiator || "Инициатор",
      readonly: true,
      documentSourceContext: "application"
    }));
}

function doesApplicationDocumentApplyToTask(doc, task) {
  const source = doc || {};
  const explicitTaskId = source.requestTaskId || source.requestedByTaskId || source.returnedTaskId || "";
  if (explicitTaskId && explicitTaskId !== task.id) return false;
  const targetIds = getDocumentTargetIds(source, "application");
  if (targetIds.some((id) => /^TSK-/i.test(id))) return targetIds.includes(task.id);
  const taskCollateralIds = getTaskCollateralIds(task);
  const collateralIds = getDocumentExplicitCollateralIds(source, "application");
  if (collateralIds.length) return collateralIds.some((id) => taskCollateralIds.includes(id));
  const target = String(source.target || source.collateralId || "").trim();
  if (/^COL-/i.test(target)) return taskCollateralIds.includes(target);
  return true;
}

function getTaskDocumentDedupKey(doc) {
  const source = typeof doc === "string" ? { name: doc } : (doc || {});
  const target = source.target || source.applyValue || source.collateralId || "";
  return `${getDocumentComparableName(source)}::${target}`;
}

function renderTaskExpertConclusion(task, collaterals = getTaskCollaterals(task)) {
  const defaults = getTaskExpertDefaults(task, collaterals);
  const template = getSelectedTaskExpertTemplate(task, collaterals);
  const canGenerate = canGenerateTaskExpertConclusion(task, template, collaterals);
  const expertAttachment = getTaskExpertAttachment(task);
  const expertAttrs = (field) => `data-task-expert="${field}" data-task="${escapeHtml(task.id)}"`;
  const expertOutcome = task.expertOutcome || getTaskExpertConclusionOutcome(defaults.result);
  const showTemplateField = !isPledgeOperationTaskType(task.type);
  const conclusionFields = [
    ...(showTemplateField ? [{ label: "Шаблон печатной формы", value: template.name, readonly: true, wide: true }] : []),
    { label: "Дата документа", value: task.expertDocumentDate || task.dueDate || "2026-06-19", type: "date", attrs: expertAttrs("expertDocumentDate") },
    { label: "Ответственный", value: task.assignee || getRole().user, readonly: true },
    { label: "Итог заключения", value: expertOutcome, type: "select", options: getTaskPrintResultOptions(task), attrs: expertAttrs("expertOutcome") }
  ];
  const negativeReasonField = expertOutcome === "Отрицательное"
    ? `<label class="expert-negative-reason">Причина отрицательного заключения<textarea data-task-expert="negativeConclusionReason" data-task="${task.id}">${escapeHtml(task.negativeConclusionReason || "")}</textarea></label>`
    : "";
  return `
    <section class="panel expert-conclusion-panel">
      <div class="panel-title">
        <div><h2>Экспертное заключение по задаче</h2></div>
        ${canGenerate ? `<button class="btn btn-secondary" data-action="generate-task-conclusion" data-task="${task.id}">Сформировать документ</button>` : ""}
      </div>
      ${renderTaskFormGrid(conclusionFields, "task-form-grid compact")}
      <div class="expert-conclusion-grid">
        ${negativeReasonField}
        <label>Комментарии<textarea data-task-expert="expertComment" data-task="${task.id}">${escapeHtml(task.expertComment ?? defaults.comment)}</textarea></label>
        <label>Выводы<textarea data-task-expert="expertConclusion" data-task="${task.id}">${escapeHtml(task.expertConclusion ?? defaults.conclusion)}</textarea></label>
        <div class="expert-conclusion-attachment">
          ${renderTaskExpertAttachmentRow(task, expertAttachment)}
        </div>
      </div>
    </section>
  `;
}

function getTaskExpertAttachment(task) {
  return (task.documents || [])
    .map((doc, index) => ({ ...doc, __documentIndex: index }))
    .find((doc) => doc.category === "expertConclusion" || doc.title === "Файл экспертного заключения") || null;
}

function renderTaskExpertAttachmentRow(task, attachment) {
  const hasFile = Boolean(attachment?.name);
  const row = attachment || {
    title: "Экспертное заключение по задаче",
    name: "",
    target: "task",
    status: "Ожидает файл",
    required: false
  };
  return `
    <div class="document-file-row expert-file-row ${hasFile ? "has-file" : "empty-file"}">
      <div>
        <strong>${escapeHtml(row.title)}</strong>
        <span>${hasFile ? escapeHtml(row.name) : "Файл еще не прикреплен"}</span>
        <small>Задача: ${escapeHtml(task.id)} · ${escapeHtml(row.status || "Ожидает файл")}</small>
      </div>
      <div class="document-file-meta">${badge("Дополнительный", "neutral")}${hasFile ? badge("Файл", "ok") : badge("Нет файла", "neutral")}</div>
      <div class="document-row-actions">
        ${hasFile ? `
          <a class="doc-download-button" href="${createDocumentDownloadHref(row, "task", task.id)}" download="${escapeHtml(row.name)}" title="Скачать файл" aria-label="Скачать файл ${escapeHtml(row.name)}">
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path d="M12 3v12m0 0 4-4m-4 4-4-4M5 21h14"></path>
            </svg>
          </a>
          <button type="button" class="doc-delete-button" data-action="delete-document" data-doc-context="task" data-doc-owner="${escapeHtml(task.id)}" data-doc-index="${escapeHtml(row.__documentIndex ?? "")}" data-doc-title="${escapeHtml(row.title)}" data-doc-target="${escapeHtml(row.target || "task")}" data-doc-name="${escapeHtml(row.name)}" title="Удалить файл" aria-label="Удалить файл ${escapeHtml(row.name)}">
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path d="M4 7h16M10 11v6M14 11v6M6 7l1 14h10l1-14M9 7V4h6v3"></path>
            </svg>
          </button>
        ` : ""}
        <label class="doc-add-button ${hasFile ? "secondary" : ""}" title="Прикрепить файл">+
          <input type="file" data-task-expert-file="${escapeHtml(task.id)}">
        </label>
      </div>
    </div>
  `;
}

function getTaskExpertDefaults(task, collaterals = getTaskCollaterals(task)) {
  const scope = getTaskExpertCollateralScopeText(collaterals);
  if (isInspectionCardTaskType(task.type)) {
    const results = collaterals.length ? collaterals.map((collateral) => getInspectionResult(task, collateral)) : [getInspectionResult(task, null)];
    const hasCritical = results.some((result) => result.canAccept === "НЕТ" || result.criticalCount > 0);
    const hasWarnings = results.some((result) => result.warningCount > 0 || result.tone === "warn");
    return {
      result: hasCritical ? "Отрицательное" : (hasWarnings ? "Положительное с замечаниями" : "Положительное"),
      comment: task.result || `По результатам осмотра проверены ${scope}: состояние, идентификаторы, документы и материалы фиксации.`,
      conclusion: hasCritical
        ? `По задаче ${task.id} требуется устранить критичные замечания по объектам залога.`
        : hasWarnings
          ? `По задаче ${task.id} результат осмотра может быть принят с учетом зафиксированных замечаний.`
          : `По задаче ${task.id} объекты залога проверены без существенных замечаний.`
    };
  }
  if (isRevaluationTaskType(task.type)) {
    return {
      result: "Стоимость подтверждена",
      comment: task.result || `Оценка выполняется по ${scope} с учетом документов задачи, внешних источников и залоговых дисконтов.`,
      conclusion: `Стоимость по объектам задачи ${task.id} отражена в печатной форме оценки.`
    };
  }
  if (isPledgeOperationTaskType(task.type)) {
    return {
      result: "Готово к передаче в АБС",
      comment: task.result || "Проверены регистрационные данные, документы и результаты внешних проверок.",
      conclusion: `Объекты задачи ${task.id} могут быть переданы для регистрации залога.`
    };
  }
  return { result: "Результат зафиксирован", comment: task.result || "Комментарий исполнителя по результату обработки задачи.", conclusion: "Результат задачи зафиксирован и готов к дальнейшему маршруту." };
}

function getTaskExpertCollateralScopeText(collaterals = []) {
  if (!collaterals.length) return "объектам задачи";
  if (collaterals.length === 1) return `объекту ${collaterals[0].id}`;
  return `${collaterals.length} ${pluralize(collaterals.length, "объекту", "объектам", "объектам")} залога`;
}

function getTaskPrintResultOptions(task) {
  return ["Положительное", "Положительное с замечаниями", "Отрицательное"];
}

function getTaskExpertConclusionOutcome(value) {
  const text = String(value || "").toLowerCase();
  if (/не подтвержден|отриц|ошибка|не готов|отказ/i.test(text)) return "Отрицательное";
  if (/замеч|услов/i.test(text)) return "Положительное с замечаниями";
  return "Положительное";
}

function canGenerateTaskExpertConclusion(task, template = null, collaterals = getTaskCollaterals(task)) {
  if (!task || isReportingTaskType(task.type) || isPledgeOperationTaskType(task.type) || isDefectInspectionTaskType(task.type)) return false;
  if (isDocumentaryInspectionTask(task)) return false;
  if (isHeterogeneousExpertConclusionScope(task, collaterals)) return false;
  const selectedTemplate = template || getTaskExpertConclusionTemplate(task);
  return !/не формирует|отсутствует/i.test(String(selectedTemplate?.name || ""));
}

function isHeterogeneousExpertConclusionScope(task, collaterals = getTaskCollaterals(task)) {
  if (!isRevaluationTaskType(task?.type)) return false;
  const collateralTypes = uniqueItems((collaterals || []).map((collateral) => getTaskCollateralGroupType(collateral)).filter(Boolean));
  return collateralTypes.length > 1;
}

function getTaskExpertConclusionTemplate(task) {
  return getSelectedTaskExpertTemplate(task, getTaskCollaterals(task));
}

function getSelectedTaskExpertTemplate(task, collaterals = getTaskCollaterals(task)) {
  return getDefaultTaskExpertTemplate(task, collaterals);
}

function getDefaultTaskExpertTemplate(task, collaterals = getTaskCollaterals(task)) {
  if (isRevaluationTaskType(task?.type)) return { id: "corporate-value-conclusion", name: "Корп_Заключение ОБРАЗЕЦ.doc" };
  if (isInspectionCardTaskType(task.type) || isMobileInspectionTaskType(task.type)) {
    return isDocumentaryInspectionTask(task)
      ? { id: "documentary-no-print-form", name: "Залоговый модуль не формирует печатную форму." }
      : getPhysicalInspectionPrintTemplate(collaterals);
  }
  if (isDefectInspectionTaskType(task.type)) return { id: "defect-no-print-form", name: "Автоматизированная печатная форма отсутствует" };
  if (isPledgeOperationTaskType(task.type)) return { id: "pledge-registration-no-print-form", name: "Залоговый модуль не формирует печатную форму." };
  return { id: "expert-conclusion", name: "Экспертное заключение по задаче" };
}

function getPhysicalInspectionPrintTemplate(collaterals = []) {
  const type = collaterals.length === 1 ? collaterals[0]?.type : "";
  if (isVehicleLikeCollateralType(type) || /прочие движимые/i.test(String(type || ""))) return { id: "inspection-vehicle-act", name: "Акт осмотра ТС/СМ" };
  if (type === "Оборудование") return { id: "inspection-equipment-act", name: "Акт осмотра оборудования" };
  if (isRealEstateCollateralType(type)) return { id: "inspection-realty-act", name: "Акт осмотра недвижимости" };
  if (type === "Товары в обороте") return { id: "inspection-goods-act", name: "Акт осмотра товара в обороте по справке" };
  if (["Воздушные суда", "Животные", "Имущественные права (требования)"].includes(type)) {
    return { id: "inspection-no-print-form", name: "Залоговый модуль не формирует печатную форму." };
  }
  return { id: "inspection-conclusion", name: "Заключение по результатам осмотра имущества" };
}

function getTaskExpertTemplateOptions(task, collaterals = getTaskCollaterals(task)) {
  const options = [
    getDefaultTaskExpertTemplate(task, collaterals),
    { id: "expert-conclusion", name: "Экспертное заключение по задаче" }
  ];
  if (isInspectionCardTaskType(task.type) || isMobileInspectionTaskType(task.type)) {
    if (isDocumentaryInspectionTask(task)) {
      options.push({ id: "documentary-no-print-form", name: "Залоговый модуль не формирует печатную форму." });
    } else {
      options.push(
        { id: "inspection-vehicle-act", name: "Акт осмотра ТС/СМ" },
        { id: "inspection-equipment-act", name: "Акт осмотра оборудования" },
        { id: "inspection-realty-act", name: "Акт осмотра недвижимости" },
        { id: "inspection-goods-act", name: "Акт осмотра товара в обороте по справке" }
      );
    }
  }
  if (isRevaluationTaskType(task.type)) {
    options.push(
      { id: "corporate-value-conclusion", name: "Корп_Заключение ОБРАЗЕЦ.doc" }
    );
  }
  if (isPledgeOperationTaskType(task.type)) options.push({ id: "pledge-registration-kit", name: "Комплект данных для регистрации залога" });
  return uniqueOptionsById(options);
}

function uniqueOptionsById(options = []) {
  const seen = new Set();
  return options.filter((item) => {
    if (!item?.id || seen.has(item.id)) return false;
    seen.add(item.id);
    return true;
  });
}

function getTaskPrintFormTemplate(task, collateral) {
  if (isListRevaluationTaskType(task.type)) return { id: "list-revaluation-statement", name: "Ведомость списочной переоценки" };
  if (isInspectionTaskType(task.type) || isMonitoringTaskType(task.type) || isMobileInspectionTaskType(task.type)) return getInspectionPrintFormTemplate(task, collateral);
  if (isRevaluationTaskType(task.type)) {
    if (["Автотранспорт", "Оборудование"].includes(collateral?.type)) return { id: "urz-conclusion", name: "Заключение УРЗ" };
    return { id: "corporate-value-conclusion", name: "Заключение о рыночной, залоговой и справедливой стоимости имущества" };
  }
  if (isPledgeOperationTaskType(task.type)) return { id: "pledge-registration-kit", name: "Комплект данных для регистрации залога" };
  return { id: "task-result-document", name: "Документ по результату задачи" };
}

function getInspectionPrintFormTemplate(task, collateral) {
  if (collateral?.type === "Автотранспорт") return { id: "vehicle-inspection-act", name: "Акт осмотра ТС/СМ" };
  if (collateral?.type === "Оборудование") return { id: "equipment-inspection-act", name: "Акт осмотра оборудования" };
  if (collateral?.type === "Недвижимость") return { id: "realty-inspection-act", name: "Акт осмотра недвижимого имущества" };
  if (collateral?.type === "Товары в обороте") return { id: "goods-inspection-act", name: "Акт проверки товаров в обороте по справке" };
  return { id: "inspection-report", name: "Отчет об осмотре имущества" };
}

function getGeneratedExpertConclusionText(task, collaterals = getTaskCollaterals(task)) {
  const scope = getTaskExpertCollateralScopeText(collaterals);
  const template = getSelectedTaskExpertTemplate(task, collaterals);
  if (isInspectionCardTaskType(task.type) || isMobileInspectionTaskType(task.type)) return `Осмотр по ${scope} обработан. Данные чек-листов, документов и материалов фиксации подготовлены для формы "${template.name}".`;
  if (isRevaluationTaskType(task.type)) return `Оценка по ${scope} обработана. Рыночная, справедливая и залоговая стоимости подготовлены для формы "${template.name}".`;
  if (isPledgeOperationTaskType(task.type)) return `Залоговая операция по ${scope} обработана. Данные договоров, залогодателей и проверок подготовлены для формы "${template.name}".`;
  return `Задача ${task.id} обработана. Основные данные подготовлены для формы "${template.name}".`;
}

function buildTaskExpertConclusionContent(task, collateral, collaterals, template, generatedAt) {
  const taskCollaterals = collaterals.length ? collaterals : [collateral].filter(Boolean);
  const taskContracts = getTaskContracts(task, taskCollaterals);
  const contract = taskContracts[0] || getContract(task.contractId);
  const application = getTaskApplication(task);
  const contractText = taskContracts.length > 1
    ? taskContracts.map((item) => item.number).join(", ")
    : contract?.number || task.contractNumber || task.contractId || "-";
  const clientName = summarizeNames(taskContracts.map((item) => item.clientName)) || task.dealClientName || application?.clientName || application?.participantName || "-";
  const clientInn = uniqueItems([...(taskContracts.map((item) => item.inn)), task.dealClientInn, application?.participantInn, task.participantInn].filter(Boolean)).join(", ") || "-";
  const product = normalizeApplicationDealProduct(task.dealProduct || application?.product, contract?.product) || "-";
  const dealCurrency = task.dealCurrency || application?.currency || contract?.currency || "RUB";
  const dealLimit = parseNumericInput(task.dealLimit ?? application?.limit ?? contract?.limit ?? 0);
  const defaults = getTaskExpertDefaults(task, taskCollaterals);
  const expertOutcome = task.expertOutcome || getTaskExpertConclusionOutcome(defaults.result);
  const negativeReason = expertOutcome === "Отрицательное" ? String(task.negativeConclusionReason || "").trim() : "";
  const objectList = taskCollaterals.length
    ? taskCollaterals.map((item) => `${item.id} - ${item.type} - ${item.description}`).join("; ")
    : "Объекты залога не привязаны";
  const pledgors = uniqueItems(taskCollaterals.map((item) => getMainPledgor(item).name).filter(Boolean)).join(", ") || "-";
  const pledgorInns = uniqueItems(taskCollaterals.map((item) => getMainPledgor(item).idn).filter(Boolean)).join(", ") || "-";
  const base = [
    template.name,
    `Дата формирования: ${generatedAt}`,
    `Номер задачи: ${task.id}`,
    `Тип задачи: ${task.type}`,
    `Наименование задачи: ${task.title}`,
    `Статус задачи: ${task.status}`,
    `Исполнитель: ${task.assignee || "-"}`,
    `Инициатор: ${getTaskInitiator(task)}`,
    `Заявка: ${application?.number || task.applicationNumber || "-"}`,
    `Клиент по договору: ${clientName}`,
    `Роль по договору: ${summarizeNames(taskContracts.map(getContractPartyRole))}`,
    `ИНН клиента по договору: ${clientInn}`,
    `Продукт: ${product}`,
    `Сумма / лимит сделки: ${dealLimit ? formatMoney(dealLimit, dealCurrency) : "-"}`,
    `Валюта сделки: ${dealCurrency}`,
    `Залогодатели: ${pledgors}`,
    `ИНН залогодателей: ${pledgorInns}`,
    `Договор: ${contractText}`,
    `Объекты залога в задаче: ${objectList}`,
    `Итог заключения: ${expertOutcome}`,
    ...(negativeReason ? [`Причина отрицательного заключения: ${negativeReason}`] : []),
    `Комментарий эксперта: ${task.expertComment || defaults.comment}`,
    `Вывод эксперта: ${task.expertConclusion || defaults.conclusion}`
  ];
  if (isListRevaluationTaskType(task.type)) return [...base, ...buildListRevaluationPrintContent(task, taskCollaterals)];
  if (isInspectionTaskType(task.type) || isMonitoringTaskType(task.type) || isMobileInspectionTaskType(task.type)) {
    return [
      ...base,
      ...taskCollaterals.flatMap((item, index) => [
        ...printSection(`Объект ${index + 1}: ${item.id}`, [
          printField("Вид залога", item.type || "-"),
          printField("Залогодатель", getMainPledgor(item).name),
          printField("Описание", item.description || "-")
        ]),
        ...buildInspectionPrintContent(task, item)
      ])
    ];
  }
  if (isRevaluationTaskType(task.type)) {
    return [
      ...base,
      ...taskCollaterals.flatMap((item, index) => [
        ...printSection(`Объект ${index + 1}: ${item.id}`, [
          printField("Вид залога", item.type || "-"),
          printField("Залогодатель", getMainPledgor(item).name),
          printField("Описание", item.description || "-")
        ]),
        ...buildRevaluationPrintContent(task, item, getTaskActiveContract(task, item))
      ])
    ];
  }
  if (isPledgeOperationTaskType(task.type)) {
    return [
      ...base,
      ...taskCollaterals.flatMap((item, index) => [
        ...printSection(`Объект ${index + 1}: ${item.id}`, [
          printField("Вид залога", item.type || "-"),
          printField("Залогодатель", getMainPledgor(item).name),
          printField("Описание", item.description || "-")
        ]),
        ...buildPledgeOperationPrintContent(task, item, getTaskActiveContract(task, item))
      ])
    ];
  }
  return [...base, `Результат задачи: ${task.result || "-"}`];
}

function printSection(title, rows) {
  return ["", title, ...rows.filter((row) => row !== null && row !== undefined && row !== "")];
}

function printField(label, value) {
  const normalized = value === null || value === undefined || value === "" ? "-" : value;
  return `${label}: ${normalized}`;
}

function collateralField(collateral, names, fallback = "-") {
  const fields = collateral?.fields || {};
  const variants = Array.isArray(names) ? names : [names];
  for (const name of variants) {
    const value = fields[name];
    if (value !== undefined && value !== null && value !== "") return value;
  }
  return fallback;
}

function checklistValue(result, code, fallback = "-") {
  const item = result?.groups?.flatMap((group) => group.items || []).find((row) => row.code === code);
  return item?.selected?.label || fallback;
}

function buildChecklistPrintRows(result) {
  return (result?.groups || []).flatMap((group) => [
    group.title,
    ...(group.items || []).map((item) => `- ${item.name}: ${item.selected?.label || "-"}`)
  ]);
}

function buildInspectionPrintContent(task, collateral) {
  const result = getInspectionResult(task, collateral);
  const resolutionResult = getInspectionResolutionResultValue(result, task, collateral);
  const conditionAssessment = getInspectionConditionAssessmentValue(result, task, collateral);
  const physicalWearPercent = getInspectionPhysicalWearPercentValue(result, task, collateral);
  const resolutionComment = getInspectionResolutionCommentValue(result, task, collateral);
  const mismatchRows = getInspectionProblemChecklistRows(result, task, collateral);
  const reportFields = getInspectionReportFields(task, collateral).map((field) => printField(field.label, field.value));
  const contactFields = getInspectionContactRows(task, collateral).map((contact) =>
    printField(contact.role, [contact.name, contact.phone, contact.comment].filter(Boolean).join("; "))
  );
  const photoRows = getCollateralPhotoAngles(collateral).map((angle) => {
    const photo = collateral ? getTaskPhotoValue(task, collateral.id, angle) : null;
    return `- ${angle}: ${photo?.name || "не прикреплено"}`;
  });
  const photoSection = isDocumentaryInspectionTask(task) ? [] : printSection("Фотофиксация", photoRows);
  return [
    ...printSection("Реквизиты осмотра", reportFields),
    ...printSection("Контактные лица", contactFields),
    ...buildTypedInspectionPrintContent(task, collateral, result),
    ...printSection("Чек-лист осмотра", buildChecklistPrintRows(result)),
    ...photoSection,
    ...printSection("Резолюция по объекту", [
      printField("Результат осмотра", resolutionResult),
      printField("Оценка состояния", conditionAssessment),
      printField("Процент физического износа", `${physicalWearPercent}%`),
      printField("Комментарий сотрудника", resolutionComment)
    ]),
    ...printSection("Выявленные несоответствия", mismatchRows.map((row) =>
      `- ${row.name}: ${row.value}; маркер: ${row.marker}; комментарий: ${row.comment}`
    ))
  ];
}

