      "Тип автомобиля": /прицеп/i.test(collateral.description || "") ? "Прицеп / полуприцеп" : "Грузовой",
      "Тип документа": selfPropelled ? "ПСМ" : "ПТС",
      "Дата": "2026-01-12",
      "Серия": "52АА",
      "Номер": `${code.padStart(6, "0")}`,
