function renderPrintPreview(id) {
  const collateral = getCollateral(id);
  const contract = getContract(id);
  const form = printFormCatalog.find((item) => item.id === id);
  const title = collateral ? `${collateral.id} - ${collateral.description}` : contract ? `Договор ${contract.number}` : form ? form.name : id;
  const description = form
    ? `Владелец: ${form.owner}. Объем: ${form.pages} страниц, ${form.params} параметров.`
    : "Форма содержит реквизиты клиента по договору, договора, объекта залога, стоимости, страхования и истории согласования.";
  const backRoute = form ? "/app/reports" : contract ? "/app/applications" : "/app/tasks";
  return `${renderPageHeader("Печатная форма", "Предпросмотр документа.", `<button class="btn btn-secondary" data-route="${backRoute}">Назад</button><button class="btn btn-primary" data-action="print">Печать</button>`)}<section class="print-preview"><h2>${escapeHtml(title)}</h2><p>${escapeHtml(description)}</p></section>`;
}

