function getMobileInspectionFactors(collateral) {
  if (collateral?.type === "Автотранспорт") {
    return mobileInspectionFactorCatalog.map((factor) => factor.code === "technical"
      ? { ...factor, title: "Техническое состояние транспорта" }
      : factor.code === "storage"
        ? { ...factor, title: "Условия стоянки и хранения" }
        : factor);
  }
  if (collateral?.type === "Недвижимость") {
    return mobileInspectionFactorCatalog.map((factor) => factor.code === "technical"
      ? { ...factor, title: "Состояние здания / помещений" }
      : factor.code === "storage"
        ? { ...factor, title: "Условия эксплуатации объекта" }
        : factor);
  }
  return mobileInspectionFactorCatalog;
}

function getMobileChecklistResult(task, collateral) {
  const answers = task?.mobileChecklistAnswers?.[collateral?.id] || {};
  const factors = getMobileInspectionFactors(collateral).map((factor) => {
    const selected = factor.options.find((option) => option.code === answers[factor.code]) || null;
    return { ...factor, selected, status: getMobileChecklistOptionStatus(selected) };
  });
  const completed = factors.filter((factor) => factor.selected).length;
  const criticalCount = factors.filter((factor) => factor.status === "bad").length;
  const warningCount = factors.filter((factor) => factor.status === "warn").length;
  if (completed < factors.length) {
    return { factors, completed, total: factors.length, state: completed ? "Заполняется" : "Не заполнен", tone: "warn", criticalCount, warningCount };
  }
  if (criticalCount) return { factors, completed, total: factors.length, state: "Не подтвержден", tone: "danger", criticalCount, warningCount };
  if (warningCount) return { factors, completed, total: factors.length, state: "Есть замечания", tone: "warn", criticalCount, warningCount };
  return { factors, completed, total: factors.length, state: "Без замечаний", tone: "ok", criticalCount, warningCount };
}

function getMobileChecklistOptionStatus(option) {
  if (!option) return "empty";
  if (["free", "working", "proper", "match", "ready", "complete"].includes(option.code)) return "ok";
  if (["limited", "repair", "remarks", "minor", "partial"].includes(option.code)) return "warn";
  return "bad";
}

