function updateCollateralPickerSelection(modal, collateralId, checked) {
  const selected = new Set(modal.selectedCollateralIds || []);
  if (checked) selected.add(collateralId);
  else selected.delete(collateralId);
  modal.selectedCollateralIds = [...selected];
  return modal.selectedCollateralIds;
}

function getCollateralPickerValues(collateral) {
  const pledgor = collateral?.pledgors?.[0] || {};
  const pledgeContractNumber = [...new Set([
    collateral?.pledgeContractNumber,
    collateral?.ftMainInfo?.["Номер договора залога"],
    collateral?.fields?.["Номер договора залога"],
    ...(collateral?.encumbrances || []).map((item) => item?.pledgeContractNumber || item?.number)
  ].map((value) => String(value || "").trim()).filter(Boolean))].join(", ");
  return {
    type: getCollateralTypeLabel(collateral),
    profileIdentifier: getCollateralObjectIdentifier(collateral),
    name: getCollateralName(collateral),
    pledgeContractNumber,
    pledgorName: pledgor.name || collateral?.clientName || "",
    pledgorInn: pledgor.idn || collateral?.clientId || ""
  };
}

function filterCollateralPickerRows(collaterals, filters = {}) {
  return collaterals.filter((collateral) => {
    const values = getCollateralPickerValues(collateral);
    return Object.entries(filters).every(([key, value]) => !value || matches(values[key], value));
  });
}

function renderCollateralRegistryPickerModal() {
  const isApplicationContext = state.modal.context === "application";
  const search = state.modal.search || "";
  const filters = state.filters.collateralPicker || {};
  const selected = new Set(isApplicationContext
    ? state.modal.selectedCollateralIds || state.newTask.selectedCollateralIds || []
    : state.newTask.selectedCollateralIds || []);
  const hasApplicationSearch = Object.values(filters).some((value) => String(value || "").trim());
  const rows = isApplicationContext
    ? hasApplicationSearch ? filterCollateralPickerRows(state.data.collaterals, filters) : []
    : state.data.collaterals.filter((item) => {
      const values = getCollateralPickerValues(item);
      const haystack = [item.id, values.type, values.profileIdentifier, values.pledgeContractNumber, item.description, item.address, item.clientName, item.clientId].join(" ");
      return matches(haystack, search);
    });
  const tableRows = rows.length
    ? rows.map((item) => {
      const values = getCollateralPickerValues(item);
      return isApplicationContext
        ? `
          <tr>
            <td><input type="checkbox" data-modal-collateral-choice="${escapeHtml(item.id)}" ${selected.has(item.id) ? "checked" : ""}></td>
            <td>${escapeHtml(values.type)}</td>
            <td>${escapeHtml(values.profileIdentifier)}</td>
            <td>${escapeHtml(values.name)}</td>
            <td>${escapeHtml(values.pledgeContractNumber || "-")}</td>
            <td>${escapeHtml(values.pledgorName || "-")}</td>
            <td>${escapeHtml(values.pledgorInn || "-")}</td>
          </tr>
        `
        : `
          <tr>
            <td><input type="checkbox" data-modal-collateral-choice="${escapeHtml(item.id)}" ${selected.has(item.id) ? "checked" : ""}></td>
            <td><strong>${escapeHtml(item.id)}</strong></td>
            <td>${escapeHtml(getCollateralTypeLabel(item))}</td>
            <td>${escapeHtml(getCollateralObjectIdentifier(item))}</td>
            <td>${escapeHtml(item.description)}<br><small>${escapeHtml(item.address)}</small></td>
            <td>${escapeHtml(item.clientName)}<br><small>${escapeHtml(item.clientId)}</small></td>
            <td>${formatMoney(item.pledgeValue || 0)}</td>
            <td>${badge(getCollateralRiskState(item), riskTone(item))}</td>
          </tr>
        `;
    }).join("")
    : isApplicationContext && !hasApplicationSearch
      ? ""
      : `<tr><td class="collateral-picker-empty" colspan="${isApplicationContext ? 7 : 8}">${isApplicationContext ? "По заданным параметрам объекты залога не найдены." : "По заданным параметрам объекты залога не найдены."}</td></tr>`;
  return `
    <div class="modal-backdrop">
      <section class="modal wide">
        <div class="modal-head"><h2>Выбрать объект залога</h2><button class="btn btn-secondary" data-action="close-modal">Закрыть</button></div>
        <p class="hint">Выбранные объекты будут привязаны к заявке в целом.</p>
        ${isApplicationContext ? `
          <div class="application-collateral-picker-filters">
            ${APPLICATION_COLLATERAL_PICKER_FILTERS.map(([key, label]) => `
              <label>${escapeHtml(label)}<input value="${escapeHtml(filters[key] || "")}" data-filter-scope="collateralPicker" data-filter-name="${escapeHtml(key)}"></label>
            `).join("")}
          </div>
          ${hasApplicationSearch ? "" : '<p class="collateral-picker-empty-state">Задайте параметры поиска, чтобы увидеть объекты залога.</p>'}
        ` : `
          <div class="task-pool-search">
            <label>Поиск по ID, профильному идентификатору, залогодателю, адресу, виду залога или договору залога (по номеру)<input value="${escapeHtml(search)}" data-modal-collateral-search></label>
          </div>
        `}
        ${isApplicationContext && !hasApplicationSearch ? "" : `<div class="collateral-picker-result-count">${rows.length} объектов найдено</div>`}
        <div class="table-wrap collateral-picker-table">
          <table>
            <thead><tr>${isApplicationContext
              ? `<th></th><th>Вид залога</th><th>Профильный идентификатор</th><th>Наименование</th><th>Номер договора залога</th><th>Наименование Залогодателя</th><th>ИНН Залогодателя</th>`
              : "<th></th><th>ID</th><th>Вид залога</th><th>Профильный идентификатор</th><th>Объект</th><th>Залогодатель</th><th>Залоговая стоимость</th><th>Риск</th>"}</tr></thead>
            <tbody>${tableRows}</tbody>
          </table>
        </div>
        <div class="modal-actions">
          ${isApplicationContext && hasApplicationSearch && !rows.length ? '<button class="btn btn-secondary" data-action="open-new-collateral-from-picker">Добавить новый объект</button>' : ""}
          <button class="btn btn-primary" data-action="submit-collateral-picker">Добавить выбранные</button>
        </div>
      </section>
    </div>
  `;
}

function createNewCollateralDraft(context = "registry", collateral = null) {
  const collateralRecords = state.data?.collaterals || [];
  const fromApplication = context !== "registry";
  const clientName = fromApplication ? (state.newTask?.dealClientName || state.newTask?.participantName || "") : "";
  const clientInn = fromApplication ? (state.newTask?.dealClientInn || state.newTask?.participantInn || "") : "";
  const subjectType = clientInn.length === 12 ? "ФЛ" : clientInn.length === 10 ? "ЮЛ" : "";
  const clientType = collateral ? getCollateralClientType(collateral) : (clientInn.length === 10 ? "ЮЛ" : clientInn.length === 12 ? "ФЛ" : "");
  const typeLabel = collateral ? getCollateralTypeLabel(collateral) : "";
  const existingMain = collateral?.ftMainInfo || {};
  const existingLegacy = collateral?.fields || {};
  const existingAddress = collateral?.addressFields || {};
  const existingPledgors = (collateral?.pledgors || []).map((row) => ({ ...row }));
  const pledgeContracts = [];
  const addPledgeContract = (record = {}) => {
    const number = String(record.pledgeContractNumber || record.number || "").trim();
    const date = normalizeNewCollateralDate(record.pledgeContractDate || record.date || "");
    if (!number && !date) return;
    const metadata = {
      amount: record.amount !== null && record.amount !== undefined && String(record.amount).trim() !== "" ? record.amount : record.allocated,
      allocated: record.allocated,
      currency: record.currency || record.pledgeContractCurrency,
      product: record.product || record.pledgeProduct,
      linkedContract: record.linkedContract || record.contract || record.pledgeContractMainContractId
    };
    const normalizedNumber = number.toLocaleLowerCase("ru-RU");
    const existing = pledgeContracts.find((item) => item.number.toLocaleLowerCase("ru-RU") === normalizedNumber && item.date === date);
    if (existing) {
      Object.entries(metadata).forEach(([field, value]) => {
        if ((existing[field] === null || existing[field] === undefined || String(existing[field]).trim() === "")
            && value !== null && value !== undefined && String(value).trim() !== "") existing[field] = value;
      });
      return;
    }
    pledgeContracts.push({
      number,
      date,
      ...Object.fromEntries(Object.entries(metadata).filter(([, value]) => value !== null && value !== undefined && String(value).trim() !== ""))
    });
  };
  (Array.isArray(collateral?.pledgeContracts) ? collateral.pledgeContracts : collateral?.encumbrances || []).forEach(addPledgeContract);
  addPledgeContract({
    number: collateral?.pledgeContractNumber || existingMain["Номер договора залога"] || existingLegacy["Номер договора залога"],
    date: collateral?.pledgeContractDate || existingMain["Дата договора залога"] || existingLegacy["Дата договора залога"]
  });
  const basisDocument = getCollateralBasisDocument(collateral);
  const typeFields = collateral
    ? Object.fromEntries(Object.entries(getCollateralTypeSpecificFields(collateral))
      .filter(([field]) => !["Тип документа", "Дата", "Серия", "Номер"].includes(field))
      .map(([field, value]) => [field, /Дата/i.test(field) ? formatNewCollateralDateInput(value) : value]))
    : {};
  const profileIdentifierType = collateral ? getNewCollateralProfileIdentifierType({
    typeLabel,
    profileIdentifierType: collateral.profileIdentifierType,
    typeFields,
    sharedFields: {},
    profileIdentifier: collateral.profileIdentifier,
    suzNumber: getCollateralSuzNumber(collateral)
      || getNextMonthlyCollateralNumber(collateralRecords, new Date()),
    collateralId: collateral.id
  }) : "";
  if (collateral && typeLabel === "Объекты недвижимости") {
    const cadastralNumber = String(existingLegacy["Кадастровый номер"] || "").trim();
    if (cadastralNumber) typeFields["Кадастровый номер"] = cadastralNumber;
    if (String(existingLegacy["Условный номер"] || "").trim()) {
      typeFields["Условный номер"] = String(existingLegacy["Условный номер"]).trim();
    }
  }
  const addressAliases = {
    "Улица": "Улица (в том числе проспект, переулок, квартал)",
    "Дом": "Номер дома (владения)",
    "Корпус": "Номер корпуса (строения)",
    "Квартира": "Номер квартиры (офиса, помещения, комнаты)"
  };
  const addressFields = Object.fromEntries(COLLATERAL_ADDRESS_FIELDS.map((field) => [
    field,
    existingAddress[field] || existingAddress[addressAliases[field]] || (field === "Адрес / место нахождения" ? collateral?.address || "" : "")
  ]));
  addressFields.manualEntry = existingAddress.manualEntry
    ?? (collateral?.manualAddressEntry ? "Да" : "Нет");
  addressFields["Частный дом"] = existingAddress["Частный дом"] || "Нет";
  const inspectionValue = existingMain["Осмотр произведен"]
    ?? existingLegacy["Осмотр произведен"]
    ?? existingMain["Осмотр (проведен/не проведен)"]
    ?? existingLegacy["Осмотр (проведен/не проведен)"]
    ?? "Нет";
  const inspectionText = String(inspectionValue).trim().toLocaleLowerCase("ru-RU");
  const inspectionDone = ["да", "true", "1", "проведен", "проведено"].includes(inspectionText);
  return {
    context,
    id: "NEW-COLLATERAL-DRAFT",
    collateralId: collateral?.id || "",
    typeLabel,
    subtype: collateral ? getCollateralSubtype(collateral) : "",
    clientType,
    clientName: collateral?.clientName || clientName,
    clientId: collateral?.clientId || clientInn,
    name: collateral ? getCollateralName(collateral) : "",
    profileIdentifierType,
    typeFields,
    suzNumber: getCollateralSuzNumber(collateral)
      || getNextMonthlyCollateralNumber(collateralRecords, new Date()),
    basisDocumentExpanded: false,
    typeFieldsExpanded: false,
    basisDocument: Object.fromEntries(Object.entries(basisDocument).map(([field, value]) => [field, field === "date" ? formatNewCollateralDateInput(value) : value])),
    sharedFields: {
      "Единица измерения": [existingMain["Единица измерения"], existingLegacy["Единица измерения"], collateral ? getCollateralUnitDefault(collateral) : ""].find((value) => !isBlankFieldValue(value)) || "",
      "Значение, в указанных ед.изм.": [existingMain["Значение, в указанных ед.изм."], existingLegacy["Значение, в указанных ед.изм."], existingMain["Параметры единицы измерения"], existingLegacy["Параметры единицы измерения"]].find((value) => !isBlankFieldValue(value)) || "",
      "Дополнительная информация": [existingMain["Дополнительная информация"], existingLegacy["Дополнительная информация"], collateral?.additionalInfo].find((value) => !isBlankFieldValue(value)) || "",
      "Осмотр произведен": inspectionDone ? "Да" : "Нет",
      "Контактное лицо для осмотра": existingMain["Контактное лицо для осмотра"] || existingLegacy["Контактное лицо для осмотра"] || ""
    },
    pledgeContracts: pledgeContracts.length ? pledgeContracts : [{ number: "", date: "" }],
    addressFields,
    pledgors: existingPledgors.length
      ? existingPledgors
      : [{ share: "", name: clientName, idn: clientInn, subjectType, role: "Залогодатель", subjectCode: clientInn }],
    documents: (collateral?.documents || []).map((doc) => typeof doc === "string" ? { name: doc } : { ...doc }),
    documentFiles: []
  };
}

function openNewCollateralModal(context = "registry", modalFields = {}) {
  state.modal = { type: "newCollateral", context, ...modalFields };
  state.newCollateralDraft = createNewCollateralDraft(context);
}

function openEditCollateralModal(collateralId) {
  const collateral = getCollateral(collateralId);
  if (!collateral) {
    addToast("Объект не найден", "Выберите строку залога в таблице заявки.", "warn");
    return;
  }
  const context = "applicationCreate";
  state.modal = { type: "newCollateral", context, mode: "edit", collateralId };
  state.newCollateralDraft = createNewCollateralDraft(context, collateral);
}

function getNewCollateralSubtypeField(typeLabel) {
  const collateral = { type: getCollateralTypeCodeFromLabel(typeLabel) };
  return getCollateralEditableOptions(collateral, "type", "Подвид залога").length ? "Подвид залога" : "";
}

function getNewCollateralFieldGroups(typeLabel, draft = {}) {
  const subtypeField = typeLabel ? getNewCollateralSubtypeField(typeLabel) : "";
  const typeFields = typeLabel ? [...(FT_COLLATERAL_V8_TYPE_FIELDS[typeLabel] || [])] : [];
  const subtypeAliases = new Set([subtypeField, "Подвид залога", "Подвид", "Подтип"]);
  const identityFields = new Set(["Наименование"]);
  const basisFields = new Set(["Вид документа-основания", "Дата документа-основания", "Серия документа-основания", "Номер документа-основания", "Статус ЭПТС"]);
  return {
    identity: ["Вид залога", subtypeField || "Подвид залога", "Наименование", "Вид профильного идентификатора", "Профильный идентификатор объекта"],
    typeSpecific: typeFields.filter((label) => {
      if (subtypeAliases.has(label) || identityFields.has(label) || basisFields.has(label) || NEW_COLLATERAL_SHARED_FIELDS.includes(label)) return false;
      return isCollateralV6CardTypeFieldApplicable(typeLabel, label, draft);
    }),
    shared: [...NEW_COLLATERAL_SHARED_FIELDS],
    address: isCollateralAddressApplicable(typeLabel) ? COLLATERAL_ADDRESS_FIELDS : [],
    pledgors: ["share", "name", "idn", "subjectType", "role", "subjectCode"]
  };
}

function getNewCollateralCharacteristicTypeFields(draft, groups = getNewCollateralFieldGroups(draft?.typeLabel, draft)) {
  if (draft?.typeLabel === "Объекты недвижимости") return groups.typeSpecific;
  const selectedProfileSource = getNewCollateralProfileSource(draft, draft?.profileIdentifierType);
  if (draft?.characteristicsCardView) return groups.typeSpecific;
  return groups.typeSpecific.filter((label) => FT_COLLATERAL_PROFILE_FIELDS_VISIBLE_IN_CHARACTERISTICS.has(`${draft?.typeLabel}|${label}`)
    || !(selectedProfileSource?.group === "type" && selectedProfileSource.field === label));
}

function isNewCollateralModalTypeFieldApplicable(typeLabel, label, draft = {}) {
  return isCollateralV6TypeFieldApplicable(typeLabel, label, draft);
}

function getNewCollateralProfileIdentifierOptions(typeLabel) {
  const naturalOptions = {
    "Объекты недвижимости": [
      { label: "Кадастровый номер", group: "type", field: "Кадастровый номер" }
    ],
    "Транспортные средства, прицепы (полуприцепы)": [
      { label: "VIN", group: "type", field: "Идентификационный номер транспортного средства (VIN)" },
      { label: "Номер карточки залога", group: "system", field: "" }
    ],
    "Транспортные средства (самоходная техника)": [
      { label: "Идентификационный номер ТС или СМ (VIN, PIN, заводской)", group: "type", field: "Идентификационный номер ТС или СМ (VIN, PIN, заводской)" },
      { label: "Номер карточки залога", group: "system", field: "" }
    ],
    "Оборудование": [
      { label: "Заводской номер", group: "type", field: "Заводской номер" },
      { label: "Серийный номер", group: "type", field: "Серийный номер" },
      { label: "Инвентарный номер", group: "type", field: "Инвентарный номер" },
      { label: "Номер карточки залога", group: "system", field: "" }
    ],
    "Воздушные суда": [
      { label: "Серийный (заводской) номер", group: "type", field: "Серийный (заводской) номер" },
      { label: "Номер планера", group: "type", field: "Номер планера" },
      { label: "Опознавательные знаки воздушного судна", group: "type", field: "Опознавательные знаки воздушного судна" },
      { label: "Номер карточки залога", group: "system", field: "" }
    ],
    "Плавучие сооружения": [
      { label: "Идентификационный номер", group: "type", field: "Идентификационный номер" },
      { label: "Номер IMO", group: "type", field: "Номер IMO" },
      { label: "Регистровый номер", group: "type", field: "Регистровый номер" },
      { label: "Номер ИМПС/MMSI", group: "type", field: "Номер ИМПС/MMSI" },
      { label: "Номер карточки залога", group: "system", field: "" }
    ],
    "Железнодорожный подвижной состав": [
      { label: "Заводской номер", group: "type", field: "Заводской номер" },
      { label: "Номер вагона", group: "type", field: "Номер вагона" },
      { label: "Номер карточки залога", group: "system", field: "" }
    ],
    "Имущественные права (требования)": [
      { label: "Номер договора вместе с датой заключения договора", group: "type", field: "Номер договора", includesDate: true },
      { label: "Номер карточки залога", group: "system", field: "" }
    ],
    "Животные": [{ label: "Инвентарный номер", group: "type", field: "Инвентарный номер" }, { label: "Номер карточки залога", group: "system", field: "" }],
    "Товары в обороте": [{ label: "Инвентарный номер", group: "type", field: "Инвентарный номер" }, { label: "Номер карточки залога", group: "system", field: "" }],
    "Прочие движимые вещи (однородные группы)": [
      { label: "Инвентарный номер", group: "type", field: "Инвентарный номер" },
      { label: "Номер карточки залога", group: "system", field: "" }
    ],
    "Прочие движимые вещи (объекты)": [
      { label: "Инвентарный номер", group: "type", field: "Инвентарный номер" },
      { label: "Идентификационный признак (значение)", group: "type", field: "Идентификационный признак (значение)" },
      { label: "Номер карточки залога", group: "system", field: "" }
    ]
  }[typeLabel] || [];
  return naturalOptions;
}

function getNewCollateralProfileSource(draft, identifierType = draft?.profileIdentifierType) {
  return getNewCollateralProfileIdentifierOptions(draft?.typeLabel)
    .find((option) => option.label === identifierType)
    || (identifierType === "Номер карточки залога" ? { label: identifierType, group: "system", field: "" } : null);
}

function getNewCollateralProfileRawSourceValue(draft, option) {
  if (!option || option.group === "system") return "";
  if (option.group === "subtype") return String(draft?.subtype || "").trim();
  const values = option.group === "main" ? draft?.sharedFields : draft?.typeFields;
  return String(values?.[option.field] || "").trim();
}

function getNewCollateralProfileSourceValue(draft, option) {
  const value = getNewCollateralProfileRawSourceValue(draft, option);
  if (!option?.includesDate || !value) return value;
  const date = formatProfileIdentifierDate(String(draft?.typeFields?.["Дата заключения договора"] || "").trim());
  return date ? `${value} от ${date}` : value;
}

function getNewCollateralProfileIdentifierType(draft) {
  const options = getNewCollateralProfileIdentifierOptions(draft?.typeLabel);
  if (options.some((option) => option.label === draft?.profileIdentifierType)) return draft.profileIdentifierType;
  if (draft?.profileIdentifierType === "Номер карточки залога") return draft.profileIdentifierType;
  if (!draft?.collateralId && !draft?.profileIdentifier) return options.length === 1 ? options[0].label : "";
  const saved = String(draft?.profileIdentifier || "").trim();
  const naturalOptions = options.filter((item) => item.group !== "system");
  for (const option of naturalOptions) {
    const value = getNewCollateralProfileSourceValue(draft, option);
    const normalize = (item) => String(item || "").replace(/\s+/g, "").toLocaleLowerCase("ru-RU");
    if (value && saved && normalize(value) === normalize(saved)) return option.label;
  }
  const firstExistingNatural = naturalOptions.find((option) => getNewCollateralProfileSourceValue(draft, option));
  if (firstExistingNatural) return firstExistingNatural.label;
  if (saved && options.some((option) => option.group === "system")) return "Номер карточки залога";
  return "";
}

function getNewCollateralProfileIdentifier(draft) {
  const identifierType = getNewCollateralProfileIdentifierType(draft);
  const option = getNewCollateralProfileSource(draft, identifierType);
  if (option?.group === "system") return draft?.collateralId ? (draft?.profileIdentifier || draft?.suzNumber || "") : "";
  return getNewCollateralProfileSourceValue(draft, option);
}

function getNewCollateralProfileInputValue(draft) {
  const option = getNewCollateralProfileSource(draft, getNewCollateralProfileIdentifierType(draft));
  return option?.includesDate
    ? getNewCollateralProfileRawSourceValue(draft, option)
    : getNewCollateralProfileIdentifier(draft);
}

function getNewCollateralProfileFieldLabels(typeLabel) {
  return getNewCollateralProfileIdentifierOptions(typeLabel)
    .filter((option) => option.group === "type")
    .map((option) => option.field);
}

function getNewCollateralBasisDocumentTypes(typeLabel) {
  const byType = {
    "Объекты недвижимости": ["Выписка ЕГРН со сведениями о документе-основании права", "Правоустанавливающий документ, указанный в ЕГРН", "Акт приема-передачи и документы по обременениям"],
    "Транспортные средства, прицепы (полуприцепы)": ["ПТС", "ЭПТС", "СТС", "Договор приобретения или иной правоустанавливающий документ", "Акт приема-передачи"],
    "Транспортные средства (самоходная техника)": ["ПСМ/ЭПСМ", "Свидетельство о регистрации самоходной машины", "Договор приобретения или иной правоустанавливающий документ", "Акт приема-передачи"],
    "Оборудование": ["Договор поставки/купли-продажи, контракт или иной правоустанавливающий документ", "Акт приема-передачи/накладная/ОС-1", "Инвойс и таможенные документы при наличии"],
    "Воздушные суда": ["Свидетельство о регистрации воздушного судна", "Выписка из реестра воздушных судов", "Документ-основание права собственности", "Акт приема-передачи"],
    "Плавучие сооружения": ["Свидетельство о праве собственности/судовой билет", "Выписка из порта регистрации, ГИМС или иного профильного реестра", "Документ-основание права собственности", "Акт приема-передачи"],
    "Железнодорожный подвижной состав": ["Цепочка договоров от последнего зарегистрированного собственника с актами приема-передачи", "Технический паспорт вагона", "Справка/выгрузка из ЛК РЖД или иная справка профильного учета"],
    "Животные": ["Договоры купли-продажи/контракты со спецификациями", "Акты приема-передачи", "Товарные накладные/инвойсы и реестр поголовья"],
    "Имущественные права (требования)": ["Договор, из которого возникает право требования", "Реестр требований/дебиторской задолженности", "Документы, подтверждающие объем и действительность права"],
    "Товары в обороте": ["Складская справка/реестр остатков", "Документы приобретения товаров: договоры поставки, УПД/накладные, платежные документы при необходимости"],
    "Прочие движимые вещи (однородные группы)": ["Перечень имущества", "Документы приобретения", "Акты приема-передачи/накладные", "Учетные документы"],
    "Прочие движимые вещи (объекты)": ["Документ приобретения или иной правоустанавливающий документ", "Акт приема-передачи/накладная", "Идентификационные документы по объекту при наличии"]
  };
  return byType[typeLabel] || [];
}

function isNewCollateralResidentialDraft(draft) {
  const typeLabel = draft?.typeLabel || "";
  const subtypeField = getNewCollateralSubtypeField(typeLabel);
  return isCollateralResidentialAddress({
    type: getCollateralTypeCodeFromLabel(typeLabel),
    fields: { ...(draft?.typeFields || {}), [subtypeField || "Подтип"]: draft?.subtype || "" },
    description: draft?.name || ""
  });
}

function refreshNewCollateralProfileIdentifier(draft) {
  const field = document.querySelector("[data-new-collateral-profile-preview]");
  if (field) field.value = getNewCollateralProfileInputValue(draft);
}

function getNewCollateralValidationFieldError(draft, group, field, index) {
  const error = draft?.validationError;
  return error && error.group === group && error.field === field && error.index === index ? error.message : "";
}

function isNewCollateralRequiredTypeField(typeLabel, field, draft = {}) {
  if (typeLabel === "Оборудование") {
    return ["Заводской номер", "Серийный номер", "Марка", "Модель", "Инвентарный номер", "Год выпуска", "Группа"].includes(field);
  }
  return false;
}

function normalizeNewCollateralDate(value) {
  const match = String(value || "").trim().match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  return match ? `${match[3]}-${match[2]}-${match[1]}` : String(value || "").trim();
}

function normalizeCollateralMeasuredInput(value) {
  let text = String(value || "").replace(/[^\d,]/g, "");
  const commaIndex = text.indexOf(",");
  if (commaIndex >= 0) text = `${text.slice(0, commaIndex).slice(0, 6)},${text.slice(commaIndex + 1).replace(/,/g, "").slice(0, 3)}`;
  else text = text.slice(0, 6);
  return text;
}

function formatNewCollateralDateInput(value) {
  const text = String(value || "").trim();
  const match = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return match ? `${match[3]}.${match[2]}.${match[1]}` : text;
}

function getNewCollateralDraftValidationError(draft) {
  const fail = (group, field, message, index) => ({ group, field, message, index });
  const typeLabel = String(draft?.typeLabel || "").trim();
  if (!typeLabel) return fail("identity", "Вид залога", "Выберите вид залога.");
  const subtypeField = getNewCollateralSubtypeField(typeLabel);
  if (subtypeField && !String(draft.subtype || "").trim()) {
    return fail("identity", subtypeField, "Выберите подвид залога.");
  }
  const name = String(draft.name || "").trim();
  if (!name) return fail("identity", "Наименование", "Заполните наименование объекта.");
  if (name.length > 50) return fail("identity", "Наименование", "Не более 50 символов.");

  const additionalInfo = String(draft.sharedFields?.["Дополнительная информация"] || "").trim();
  if (!additionalInfo) return fail("main", "Дополнительная информация", "Заполните дополнительную информацию.");

  const identifierType = getNewCollateralProfileIdentifierType(draft);
  const identifierOption = getNewCollateralProfileSource(draft, identifierType);
  if (!identifierOption) return fail("identity", "Вид профильного идентификатора", "Выберите вид профильного идентификатора.");
  if (identifierOption.includesDate && !String(draft.typeFields?.["Дата заключения договора"] || "").trim()) {
    return fail("type", "Дата заключения договора", "Укажите дату договора: она входит в профильный идентификатор.");
  }
  if (getNewCollateralProfileIdentifier(draft).length > 50) {
    return fail("identity", "Профильный идентификатор объекта", "Не более 50 символов.");
  }

  const profileSource = getNewCollateralProfileSource(draft, identifierType);
  const profileValue = getNewCollateralProfileIdentifier(draft);
  if (profileSource?.group !== "system" && !profileValue) {
    return fail("identity", "Профильный идентификатор объекта", "Укажите выбранный профильный идентификатор или выберите номер карточки залога.");
  }
  if (typeLabel === "Объекты недвижимости" && !profileValue) {
    return fail("identity", "Кадастровый номер", "Укажите кадастровый номер; для недвижимости он используется как профильный идентификатор.");
  }
  if (profileValue && profileSource?.field === "Кадастровый номер"
      && !/^\d{2}:\d{2}:\d{6,7}:\d+$/.test(profileValue)) {
    return fail("identity", "Профильный идентификатор объекта", "Введите кадастровый номер в формате 00:00:0000000:0000.");
  }
  if (profileValue && /\bVIN\b/i.test(profileSource?.label || "")
      && !/^[A-HJ-NPR-Z0-9]{17}$/.test(profileValue.toUpperCase())) {
    return fail("identity", "Профильный идентификатор объекта", "VIN должен содержать 17 заглавных латинских букв или цифр; I, O и Q не допускаются.");
  }

  const shared = draft.sharedFields || {};
  const measuredValue = String(shared["Значение, в указанных ед.изм."] || "").trim();
  if (measuredValue && !/^\d{1,6},\d{3}$/.test(measuredValue)) {
    return fail("main", "Значение, в указанных ед.изм.", "Введите до 6 цифр, запятую и 3 цифры после запятой.");
  }
  for (const field of ["Идентификатор в АБС"]) {
    if (String(shared[field] || "").trim().length > 50) {
      return fail("main", field, "Не более 50 символов.");
    }
  }
  if (String(shared["Дополнительная информация"] || "").length > 255) {
    return fail("main", "Дополнительная информация", "Не более 255 символов.");
  }
  if (!Array.isArray(draft.pledgeContracts) || draft.pledgeContracts.length < 1) {
    return fail("pledgeContract", "number", "Добавьте хотя бы одну строку договора залога.", 0);
  }

  if (typeLabel === "Оборудование") {
    for (const field of ["Заводской номер", "Серийный номер", "Марка", "Модель", "Инвентарный номер", "Год выпуска", "Группа"]) {
      if (!String(draft.typeFields?.[field] || "").trim()) {
        return fail("type", field, "Заполните обязательное поле для оборудования.");
      }
    }
  }
  for (const [field, value] of Object.entries(draft.typeFields || {})) {
    const maxLength = getNewCollateralFieldMaxLength("type", field, draft);
    if (maxLength && String(value || "").trim().length > maxLength) {
      return fail("type", field, `Не более ${maxLength} символов.`);
    }
  }
  for (const [field, value] of Object.entries(draft.typeFields || {})) {
    if (!/Дата/i.test(field) || !String(value || "").trim()) continue;
    if (!/^\d{2}\.\d{2}\.\d{4}$/.test(String(value).trim())) {
      return fail("type", field, "Введите дату в формате ДД.ММ.ГГГГ.");
    }
    const normalizedDate = normalizeNewCollateralDate(value);
    const [year, month, day] = normalizedDate.split("-").map(Number);
    const date = new Date(Date.UTC(year, month - 1, day));
    if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) {
      return fail("type", field, "Укажите существующую календарную дату.");
    }
  }
  for (const field of ["Год выпуска", "Год постройки"]) {
    const value = String(draft.typeFields?.[field] || "").trim();
    if (value && !/^\d{4}$/.test(value)) return fail("type", field, "Укажите год четырьмя цифрами.");
  }
  const measuredFields = new Set([
    "Кадастровая стоимость", "Площадь застройки, кв. м", "Длина сооружения, м",
    "Мощность двигателя, л.с.", "Объем двигателя, куб. см", "Мощность двигателя, кВт",
    "Пробег", "Первоначальная стоимость", "Остаточная стоимость",
    "Размер доли в праве общей долевой собственности, числитель",
    "Размер доли в праве общей долевой собственности, знаменатель"
  ]);
  for (const [field, value] of Object.entries(draft.typeFields || {})) {
    if (!measuredFields.has(field) || !String(value || "").trim()) continue;
    if (!/^\d+(?:[,.]\d+)?$/.test(String(value).trim())) return fail("type", field, "Введите числовое значение без пробелов.");
    if (field.includes("размера доли") || field.endsWith("числитель") || field.endsWith("знаменатель")) {
      if (!/^\d{1,5}$/.test(String(value).trim()) || Number(value) <= 0) return fail("type", field, "Введите положительное целое число не более чем из 5 цифр.");
    }
  }
  for (const [field, value] of Object.entries(draft.typeFields || {})) {
    if (String(value || "").trim().length > 255 && ["Адрес по ЕГРН", "Идентификационный номер объекта недвижимости в стране регистрации"].includes(field)) {
      return fail("type", field, "Не более 255 символов.");
    }
    if (field === "Кадастровый номер" && value && !/^\d{2}:\d{2}:\d{6,7}:\d+$/.test(String(value).trim())) {
      return fail("type", field, "Введите кадастровый номер в формате 00:00:0000000:0000.");
    }
    if (field === "Кадастровый номер в пределах, которого находится объект" && value && !/^\d{2}:\d{2}:\d{6,7}:\d+$/.test(String(value).trim())) {
      return fail("type", field, "Введите кадастровый номер в формате 00:00:0000000:0000.");
    }
    if (field === "VIN" || field === "Идентификационный номер транспортного средства (VIN)") {
      if (value && !/^[A-HJ-NPR-Z0-9]{17}$/.test(String(value).trim().toUpperCase())) return fail("type", field, "VIN должен содержать 17 заглавных латинских букв или цифр; I, O и Q не допускаются.");
    }
  }
  const basisDate = String(draft.basisDocument?.date || "").trim();
  if (basisDate) {
    if (!/^\d{2}\.\d{2}\.\d{4}$/.test(basisDate)) {
      return fail("basisDocument", "Дата документа-основания", "Введите дату в формате ДД.ММ.ГГГГ.");
    }
    const normalizedDate = normalizeNewCollateralDate(basisDate);
    const [year, month, day] = normalizedDate.split("-").map(Number);
    const date = new Date(Date.UTC(year, month - 1, day));
    if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) {
      return fail("basisDocument", "Дата документа-основания", "Укажите существующую календарную дату.");
    }
  }

  const pledgors = draft.pledgors || [];
  const primaryPledgorIndex = pledgors.findIndex((row) => String(row.name || "").trim());
  if (primaryPledgorIndex < 0) return fail("pledgor", "name", "Укажите ФИО или наименование хотя бы одного залогодателя.", 0);
  for (let index = 0; index < pledgors.length; index += 1) {
    const row = pledgors[index];
    const pledgorName = String(row.name || "").trim();
    if (pledgorName.length > 50) return fail("pledgor", "name", "Не более 50 символов.", index);
    const inn = String(row.idn || "").trim();
    if (inn && !/^(?:\d{10}|\d{12})$/.test(inn)) {
      return fail("pledgor", "idn", "ИНН должен содержать 10 или 12 цифр.", index);
    }
    if (!pledgorName) return fail("pledgor", "name", "Заполните наименование или ФИО.", index);
    if (!inn) return fail("pledgor", "idn", "Заполните ИНН.", index);
    if (!row.subjectType) return fail("pledgor", "subjectType", "Выберите тип субъекта.", index);
    if (!row.role) return fail("pledgor", "role", "Выберите роль субъекта.", index);
    if (row.share && !/^\d{1,2}\/\d{1,2}$/.test(String(row.share).trim())) {
      return fail("pledgor", "share", "Доля должна содержать числитель и знаменатель в формате 1/2.", index);
    }
    const expectedSubjectType = inn.length === 12 ? "ФЛ" : inn.length === 10 ? "ЮЛ" : "";
    if (expectedSubjectType && row.subjectType !== expectedSubjectType && row.subjectType !== "Кредитная организация") {
      return fail("pledgor", "subjectType", `Для ИНН из ${inn.length} цифр укажите тип субъекта «${expectedSubjectType}».`, index);
    }
    if (String(row.subjectCode || "").trim().length > 50) {
      return fail("pledgor", "subjectCode", "Не более 50 символов.", index);
    }
  }

  const address = draft.addressFields || {};
  const addressApplicable = isCollateralAddressApplicable(typeLabel);
  const manualAddress = addressApplicable && isAffirmativeValue(address.manualEntry);
  if (addressApplicable && !manualAddress && !String(address["Адрес / место нахождения"] || "").trim()) {
    return fail("address", "Адрес / место нахождения", "Укажите адрес объекта одной строкой.");
  }
  const addressHasStructuredData = manualAddress && [
    "Регион", "Район", "Населенный пункт", "Город", "Почтовый индекс",
    "Улица", "Дом", "Корпус", "Квартира"
  ].some((field) => String(address[field] || "").trim());
  if (manualAddress && !addressHasStructuredData) return fail("address", "Регион", "Заполните адресные поля.");
  if (addressHasStructuredData) {
    for (const [field, message] of [["Регион", "Укажите регион."], ["Дом", "Укажите номер дома."]]) {
      if (!String(address[field] || "").trim()) return fail("address", field, message);
    }
    if (!String(address["Город"] || "").trim() && !String(address["Населенный пункт"] || "").trim()) {
      return fail("address", "Город", "Укажите город или населенный пункт.");
    }
    if (isNewCollateralResidentialDraft(draft)) {
      const apartment = String(address["Квартира"] || "").trim();
      const rawAddress = String(address["Адрес / место нахождения"] || "");
      const apartmentInRawAddress = /(?:кв\.?|квартира|пом\.?|помещение)\s*\d+/i.test(rawAddress);
      if (!apartment && !apartmentInRawAddress && !isAffirmativeValue(address["Частный дом"])) {
        return fail("address", "Частный дом", "Укажите номер помещения или отметьте, что объект находится в частном доме.");
      }
    }
  }
  if (manualAddress) {
    const postalCode = String(address["Почтовый индекс"] || "").trim();
    if (postalCode && !/^\d{6}$/.test(postalCode)) {
      return fail("address", "Почтовый индекс", "Введите ровно 6 цифр.");
    }
    const apartment = String(address["Квартира"] || "").trim();
    if (apartment && !/^\d+$/.test(apartment)) {
      return fail("address", "Квартира", "Используйте только цифры.");
    }
  }
  return null;
}

function renderNewCollateralField(label, group, value, draft, options = [], { readOnly = false, wide = false, fieldClass = "", inputTypeOverride = "", derived = false } = {}) {
  const typeCode = getCollateralTypeCodeFromLabel(draft.typeLabel);
  const collateral = { type: typeCode, fields: draft.typeFields, addressFields: draft.addressFields };
  const fieldOptions = options.length ? options : getCollateralEditableOptions(collateral, group, label);
  const fieldValue = value ?? "";
  const derivedAttrs = derived ? ` data-new-collateral-derived-field="${escapeHtml(label)}"` : "";
  const attrs = readOnly ? `disabled aria-readonly="true"${derivedAttrs}` : `data-new-collateral-field="${escapeHtml(label)}" data-new-collateral-group="${escapeHtml(group)}"`;
  const error = readOnly ? "" : getNewCollateralValidationFieldError(draft, group, label);
  const errorAttrs = error ? ' aria-invalid="true"' : "";
  const inputType = inputTypeOverride || getCollateralEditableInputType(label, fieldValue);
  const isWide = wide || inputType === "textarea" || ["Наименование", "Профильный идентификатор объекта", "Адрес / место нахождения"].includes(label);
  const maxlength = getNewCollateralFieldMaxLength(group, label, draft) || (inputType === "date" ? 10 : 0);
  let control = "";
  if (group === "identity" && label === "Профильный идентификатор объекта") {
    const option = getNewCollateralProfileSource(draft, getNewCollateralProfileIdentifierType(draft));
    const isSystemIdentifier = option?.group === "system";
    const disabled = readOnly || !option || isSystemIdentifier;
    const identifierAttrs = readOnly
      ? 'disabled aria-readonly="true"'
      : `data-new-collateral-field="Профильный идентификатор объекта" data-new-collateral-group="identity"${disabled ? ' disabled aria-readonly="true"' : ""}`;
    const placeholder = isSystemIdentifier ? "Сформируется автоматически" : option ? "Введите выбранный идентификатор" : "Сначала выберите тип идентификатора";
    const inputValue = getNewCollateralProfileInputValue(draft);
    const profileHint = option?.includesDate ? `<small class="new-collateral-inline-hint">Укажите номер договора; дата берется из поля «Дата заключения договора».</small>` : "";
    control = `<input class="new-collateral-profile-input ${disabled ? "new-collateral-derived-field" : ""}" value="${escapeHtml(inputValue)}" ${identifierAttrs} ${errorAttrs} maxlength="50" data-new-collateral-profile-preview placeholder="${placeholder}">${profileHint}`;
  } else if (isCollateralCheckboxField(group, label)) {
    const checkbox = `<label class="application-preinspection-field application-preinspection-check new-collateral-checkbox-control"><input type="checkbox" ${attrs} ${error ? 'aria-invalid="true"' : ""} ${isAffirmativeValue(fieldValue) ? "checked" : ""}><span>${escapeHtml(label)}</span></label>`;
    const spacer = '<span class="new-collateral-checkbox-label-spacer" aria-hidden="true"></span>';
    const wrapperClass = `new-collateral-field ${fieldClass} ${isWide ? "is-wide" : ""} ${readOnly ? "is-readonly" : ""} ${error ? "has-error" : ""}`;
    const errorMarkup = error ? `<small class="new-collateral-validation-error">${escapeHtml(error)}</small>` : "";
    return `<div class="${wrapperClass}">${spacer}${checkbox}${errorMarkup}</div>`;
  } else if (fieldOptions.length) {
    const preserveUnknownValue = (readOnly || group === "basisDocument") && fieldValue && !fieldOptions.includes(String(fieldValue));
    const visibleOptions = preserveUnknownValue ? [String(fieldValue), ...fieldOptions] : fieldOptions;
    control = `<select ${attrs}${errorAttrs} ${group === "type" && !draft.typeLabel ? "disabled" : ""}><option value="">Не выбрано</option>${visibleOptions.map((option) => `<option value="${escapeHtml(option)}" ${String(option) === String(fieldValue) ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}</select>`;
  } else if (inputType === "textarea") {
    const maxlengthAttr = maxlength ? ` maxlength="${maxlength}"` : "";
    control = `<textarea ${attrs}${readOnly ? "" : errorAttrs} ${readOnly ? "" : 'placeholder="При наличии данных"'}${readOnly ? "" : maxlengthAttr}>${escapeHtml(fieldValue)}</textarea>`;
  } else {
    const placeholder = readOnly ? "" : inputType === "date"
      ? "ДД.ММ.ГГГГ"
      : label === "Профильный идентификатор объекта"
      ? "Если нет естественного идентификатора, оставьте пустым"
      : "При наличии данных";
    const maxlengthAttr = maxlength ? ` maxlength="${maxlength}"` : "";
    const measuredValueAttrs = !readOnly && group === "main" && label === "Значение, в указанных ед.изм."
      ? ' inputmode="decimal" pattern="[0-9]{1,6},[0-9]{3}" placeholder="000000,000"'
      : "";
    const inputValue = readOnly && inputType === "date" ? formatNewCollateralDateInput(fieldValue) : fieldValue;
    control = `<input type="${inputType === "date" ? "text" : escapeHtml(inputType)}" ${attrs}${readOnly ? "" : errorAttrs} value="${escapeHtml(inputValue)}"${measuredValueAttrs || (placeholder ? ` placeholder="${escapeHtml(placeholder)}"` : "")}${readOnly ? "" : maxlengthAttr}>`;
  }
  const profileSource = group === "identity" && label === "Профильный идентификатор объекта"
    ? getNewCollateralProfileSource(draft, getNewCollateralProfileIdentifierType(draft))
    : null;
  const required = (group === "identity" && ["Наименование", "Вид профильного идентификатора"].includes(label))
    || (group === "identity" && label === "Профильный идентификатор объекта" && profileSource?.group !== "system")
    || (group === "identity" && label === getNewCollateralSubtypeField(draft.typeLabel))
    || (group === "type" && isNewCollateralRequiredTypeField(draft.typeLabel, label, draft))
    || (group === "type" && label === "Дата заключения договора" && Boolean(getNewCollateralProfileSource(draft, getNewCollateralProfileIdentifierType(draft))?.includesDate))
    || (group === "address" && label === "Адрес / место нахождения");
  return renderCollateralFieldShell(label, control, { readOnly, isWide, required, error, fieldClass });
}

function renderNewCollateralPrivateHouse(draft, { readOnly = false } = {}) {
  if (!isNewCollateralResidentialDraft(draft)) return "";
  const error = readOnly ? "" : getNewCollateralValidationFieldError(draft, "address", "Частный дом");
  const attrs = readOnly ? 'disabled aria-readonly="true"' : 'data-new-collateral-field="Частный дом" data-new-collateral-group="address"';
  return `<label class="new-collateral-private-home ${readOnly ? "is-readonly" : ""} ${error ? "has-error" : ""}"><input type="checkbox" ${attrs} ${isAffirmativeValue(draft.addressFields["Частный дом"]) ? "checked" : ""}${error ? ' aria-invalid="true"' : ""}><span>Объект расположен в частном доме</span>${error ? `<small class="new-collateral-validation-error">${escapeHtml(error)}</small>` : ""}</label>`;
}

function renderNewCollateralAddress(draft, groups, { readOnly = false } = {}) {
  if (!draft.typeLabel || !groups.address.length) {
    return `<p class="new-collateral-empty-note">${draft.typeLabel ? "Для этого вида залога адресный блок не применяется." : "Выберите вид залога."}</p>`;
  }
  const manual = isAffirmativeValue(draft.addressFields.manualEntry);
  const userFields = groups.address.filter((label) => label !== "Адрес / место нахождения");
  const switchAttributes = readOnly ? 'disabled aria-readonly="true"' : "data-new-collateral-address-toggle";
  return `
    <div class="new-collateral-address-editor${readOnly ? " collateral-address-readonly" : ""}">
      <div class="new-collateral-address-summary-row">
        ${manual ? "" : renderNewCollateralField("Адрес / место нахождения", "address", draft.addressFields["Адрес / место нахождения"] || "", draft, [], { readOnly })}
        <label class="new-collateral-address-toggle">
          <input type="checkbox" role="switch" aria-label="Ввести вручную" ${switchAttributes} ${manual ? "checked" : ""}>
          <span class="address-switch-track" aria-hidden="true"></span>
          <strong>Ввести вручную</strong>
        </label>
      </div>
      ${manual ? `
        ${renderNewCollateralPrivateHouse(draft, { readOnly })}
        <div class="new-collateral-fields new-collateral-address-fields">
          ${userFields.map((label) => renderNewCollateralField(label, "address", draft.addressFields[label] || "", draft, [], { readOnly })).join("")}
        </div>
      ` : ""}
    </div>
  `;
}

function getNewCollateralFieldMaxLength(group, label, draft) {
  if (group === "identity" && label === "Наименование") return 50;
  if (group === "identity" && label === "Профильный идентификатор объекта") return 50;
  if (group === "type" && getNewCollateralProfileFieldLabels(draft?.typeLabel).includes(label)) return 50;
  if (group === "type" && ["Описание по ЕГРН", "Адрес по ЕГРН", "Адрес по СТС", "Адрес в неструктурированном виде", "Идентификационный номер объекта недвижимости в стране регистрации"].includes(label)) return 255;
  if (group === "main" && [COLLATERAL_GROUP_ATTRIBUTE, "Идентификатор в АБС"].includes(label)) return 50;
  if (group === "main" && label === "Значение, в указанных ед.изм.") return 10;
  if (group === "main" && label === "Дополнительная информация") return 255;
  if (group === "basisDocument" && ["Серия документа-основания", "Номер документа-основания"].includes(label)) return 50;
  if (group === "address") {
    if (label === "Почтовый индекс") return 6;
    if (["Город", "Улица", "Дом", "Корпус"].includes(label)) return 50;
    if (["Район", "Населенный пункт", "Адрес / место нахождения"].includes(label)) return 255;
    if (label === "Квартира") return 20;
  }
  return 0;
}

function renderNewCollateralPledgorRow(row, index, draft) {
  const field = (name) => getNewCollateralValidationFieldError(draft, "pledgor", name, index);
  const errorMarkup = (message) => message ? `<small class="new-collateral-validation-error">${escapeHtml(message)}</small>` : "";
  const invalid = (message) => message ? ' aria-invalid="true"' : "";
  const subjectType = ({ "Юридическое лицо": "ЮЛ", "Физическое лицо / индивидуальный предприниматель": "ФЛ" })[row.subjectType] || row.subjectType;
  const subjectTypes = [["ЮЛ", "Юридическое лицо"], ["ФЛ", "Физическое лицо / индивидуальный предприниматель"], ["Кредитная организация", "Кредитная организация"]];
  const roles = ["Залогодатель", "Собственник", "Залогодатель и собственник", "Иной субъект по договору залога"];
  return `
    <tr>
      <td><input value="${escapeHtml(row.share)}" data-new-collateral-pledgor-field="share" data-index="${index}" placeholder="При наличии"></td>
      <td><input value="${escapeHtml(row.name)}" data-new-collateral-pledgor-field="name" data-index="${index}" placeholder="Наименование / ФИО" maxlength="50"${invalid(field("name"))}>${errorMarkup(field("name"))}</td>
      <td><input value="${escapeHtml(row.idn)}" data-new-collateral-pledgor-field="idn" data-index="${index}" inputmode="numeric" maxlength="12" placeholder="ИНН"${invalid(field("idn"))}>${errorMarkup(field("idn"))}</td>
      <td><select data-new-collateral-pledgor-field="subjectType" data-index="${index}"${invalid(field("subjectType"))}><option value="">Не указан</option>${subjectTypes.map(([value, label]) => `<option value="${escapeHtml(value)}" ${subjectType === value ? "selected" : ""}>${escapeHtml(label)}</option>`).join("")}</select>${errorMarkup(field("subjectType"))}</td>
      <td><select data-new-collateral-pledgor-field="role" data-index="${index}"${invalid(field("role"))}><option value="">Не указана</option>${roles.map((role) => `<option value="${escapeHtml(role)}" ${row.role === role ? "selected" : ""}>${escapeHtml(role)}</option>`).join("")}</select>${errorMarkup(field("role"))}</td>
      <td><input value="${escapeHtml(row.subjectCode)}" data-new-collateral-pledgor-field="subjectCode" data-index="${index}" placeholder="При наличии" maxlength="50"${invalid(field("subjectCode"))}>${errorMarkup(field("subjectCode"))}</td>
      <td><button class="icon-btn" title="Удалить залогодателя" aria-label="Удалить залогодателя" data-action="remove-new-collateral-pledgor" data-index="${index}" ${draft.pledgors.length === 1 ? "disabled" : ""}>×</button></td>
    </tr>
  `;
}

function renderNewCollateralPledgors(draft) {
  const rows = draft.pledgors.length ? draft.pledgors : [{ share: "", name: "", idn: "", subjectType: "", role: "Залогодатель", subjectCode: "" }];
  return `
    <div class="new-collateral-pledgors-wrap">
      <div class="new-collateral-table-scroll"><table class="new-collateral-pledgors-table">
      <thead><tr><th>Доля в праве / участии</th><th>Наименование / ФИО</th><th>ИНН</th><th>Тип субъекта</th><th>Роль</th><th>Идентификационный код субъекта</th><th></th></tr></thead>
          <tbody>${rows.map((row, index) => renderNewCollateralPledgorRow(row, index, draft)).join("")}</tbody>
        </table></div>
      <button class="btn btn-secondary btn-small" data-action="add-new-collateral-pledgor">Добавить строку</button>
    </div>
  `;
}

function isNewCollateralTypeEditable(draft, modal) {
  return !(modal?.mode === "edit" && Boolean(draft?.collateralId));
}

function renderNewCollateralModal() {
  const draft = state.newCollateralDraft || createNewCollateralDraft(state.modal?.context || "registry");
  state.newCollateralDraft = draft;
  const isRegistryContext = state.modal?.context === "registry";
  const isEditing = state.modal?.mode === "edit";
  const groups = getNewCollateralFieldGroups(draft.typeLabel, draft);
  const typeOptions = FT_COLLATERAL_TYPE_OPTIONS
    .map((item) => `<option value="${escapeHtml(item)}" ${item === draft.typeLabel ? "selected" : ""}>${escapeHtml(item)}</option>`).join("");
  const subtypeField = getNewCollateralSubtypeField(draft.typeLabel);
  const subtypeOptions = subtypeField ? getCollateralEditableOptions({ type: getCollateralTypeCodeFromLabel(draft.typeLabel), fields: draft.typeFields }, "type", subtypeField) : [];
  const characteristicCommonFields = groups.shared.filter((label) => COLLATERAL_CHARACTERISTIC_COMMON_FIELDS.includes(label));
  const documentCollateral = draft.typeLabel ? {
    id: "NEW-COLLATERAL-DRAFT",
    type: getCollateralTypeCodeFromLabel(draft.typeLabel),
    clientType: draft.clientType || "",
    fields: draft.typeFields,
    pledgors: draft.pledgors
  } : null;
  const identifierOptions = getNewCollateralProfileIdentifierOptions(draft.typeLabel).map((option) => option.label);
  if (draft.profileIdentifierType === "Номер карточки залога" && !identifierOptions.includes(draft.profileIdentifierType)) {
    identifierOptions.push(draft.profileIdentifierType);
  }
  const hint = isRegistryContext
    ? "Заполните известные сведения. После сохранения объект появится в реестре без привязки к заявке."
    : isEditing
      ? "Изменения сохранятся в выбранной карточке залога; идентификатор и связь с заявкой останутся прежними."
      : "";
  return `
    <div class="modal-backdrop">
      <section class="modal wide new-collateral-modal" aria-labelledby="newCollateralTitle">
        <div class="modal-head"><h2 id="newCollateralTitle">${isEditing ? "Редактировать объект залога" : "Добавить объект залога"}</h2><button class="btn btn-secondary" data-action="close-modal">Закрыть</button></div>
        ${hint ? `<p class="hint">${escapeHtml(hint)}</p>` : ""}
        <fieldset class="new-collateral-section">
          <legend>1. Идентификация объекта</legend>
          <div class="new-collateral-fields new-collateral-identity-fields">
            ${(() => {
              const error = getNewCollateralValidationFieldError(draft, "identity", "Вид залога");
              const typeReadOnly = !isNewCollateralTypeEditable(draft, state.modal);
              return `<label class="new-collateral-field ${error ? "has-error" : ""}"><span>Вид залога *</span><select data-new-collateral-type${error ? ' aria-invalid="true"' : ""}${typeReadOnly ? ' disabled aria-disabled="true" title="Вид залога нельзя изменить при редактировании карточки"' : ""}><option value="">Выберите вид залога</option>${typeOptions}</select>${error ? `<small class="new-collateral-validation-error">${escapeHtml(error)}</small>` : ""}</label>`;
            })()}
            ${draft.typeLabel && subtypeField ? renderNewCollateralField("Подвид залога", "identity", draft.subtype, draft, subtypeOptions) : `<label class="new-collateral-field"><span>Подвид залога</span><select disabled><option>Сначала выберите вид залога</option></select></label>`}
            ${renderNewCollateralField("Наименование", "identity", draft.name, draft)}
            ${draft.typeLabel ? renderNewCollateralField("Вид профильного идентификатора", "identity", draft.profileIdentifierType || "", draft, identifierOptions) : `<label class="new-collateral-field"><span>Вид профильного идентификатора *</span><select disabled><option>Сначала выберите вид залога</option></select></label>`}
            ${renderNewCollateralField("Профильный идентификатор объекта", "identity", getNewCollateralProfileIdentifier(draft), draft)}
          </div>
        </fieldset>
        <details class="new-collateral-section new-collateral-disclosure new-collateral-type-details" data-new-collateral-type-details ${draft.typeFieldsExpanded ? "open" : ""}>
          <summary><span>2. Характеристики объекта</span><small>Необязательные сведения</small><span class="new-collateral-collapse-icon" aria-hidden="true"></span></summary>
          <div class="new-collateral-disclosure-content">
            ${draft.typeLabel
              ? `<div class="new-collateral-fields new-collateral-type-fields collateral-characteristics-type-fields">${getNewCollateralCharacteristicTypeFields(draft, groups).map((label) => {
                  const profileSource = getNewCollateralProfileSource(draft, draft.profileIdentifierType);
                  const derived = profileSource?.group === "type" && profileSource.field === label;
                  return renderNewCollateralField(label, "type", draft.typeFields[label] || "", draft, [], { readOnly: derived, derived });
                }).join("")}</div>`
              : `<p class="new-collateral-empty-note">Выберите вид залога, чтобы показать соответствующие поля.</p>`}
            <div class="new-collateral-fields collateral-characteristics-common-fields">${characteristicCommonFields.map((label, index) => renderNewCollateralField(label, "main", draft.sharedFields[label] ?? "", draft, [], { fieldClass: ["new-collateral-main-field-unit", "new-collateral-main-field-unit-parameters", "new-collateral-main-field-additional-info"][index] })).join("")}</div>
          </div>
        </details>
        <details class="new-collateral-section new-collateral-disclosure new-collateral-basis-details" data-new-collateral-basis-details ${draft.basisDocumentExpanded ? "open" : ""}>
          <summary><span>3. Документ-основание</span><small>Необязательные сведения</small><span class="new-collateral-collapse-icon" aria-hidden="true"></span></summary>
          <div class="new-collateral-disclosure-content">
            ${draft.typeLabel
              ? `<div class="new-collateral-fields new-collateral-basis-fields">${[
                  ["Вид документа-основания", draft.basisDocument?.type || ""],
                  ["Дата документа-основания", draft.basisDocument?.date || ""],
                  ["Номер документа-основания", draft.basisDocument?.number || ""],
                  ["Серия документа-основания", draft.basisDocument?.series || ""],
                  ...(draft.typeLabel === "Транспортные средства, прицепы (полуприцепы)" && draft.basisDocument?.type === "ЭПТС"
                    ? [["Статус ЭПТС", draft.basisDocument?.status || ""]]
                    : [])
                ].map(([label, value]) => renderNewCollateralField(label, "basisDocument", value, draft)).join("")}</div>`
              : `<p class="new-collateral-empty-note">Выберите вид залога, чтобы показать подходящие документы-основания.</p>`}
          </div>
        </details>
        <fieldset class="new-collateral-section">
          <legend>4. Адрес местонахождения</legend>
          ${renderNewCollateralAddress(draft, groups)}
        </fieldset>
        <fieldset class="new-collateral-section">
          <legend>5. Залогодатели</legend>
          <p class="new-collateral-optional-note">Укажите сведения о залогодателе.</p>
          ${renderNewCollateralPledgors(draft)}
        </fieldset>
        <fieldset class="new-collateral-section">
          <legend>6. Договоры залога</legend>
          <div class="new-collateral-pledge-contracts-wrap">
            <div class="new-collateral-table-scroll">
              <table class="new-collateral-pledge-contracts-table">
                <thead><tr><th>Номер договора</th><th>Дата договора</th><th class="new-collateral-contract-actions-header"></th></tr></thead>
                <tbody>${draft.pledgeContracts?.length
                  ? draft.pledgeContracts.map((contract, index) => `
                    <tr>
                      <td><input value="${escapeHtml(contract.number || "")}" data-new-collateral-pledge-contract-field="number" data-index="${index}" aria-label="Номер договора"></td>
                      <td><input type="date" value="${escapeHtml(contract.date || "")}" data-new-collateral-pledge-contract-field="date" data-index="${index}" aria-label="Дата договора"></td>
                      <td class="new-collateral-contract-actions"><button class="icon-btn" title="Удалить договор" aria-label="Удалить договор" data-action="remove-new-collateral-pledge-contract" data-index="${index}">×</button></td>
                    </tr>`).join("")
                  : `<tr><td class="new-collateral-contracts-empty" colspan="3">Договоры залога не добавлены.</td></tr>`}</tbody>
              </table>
            </div>
            <button class="btn btn-secondary btn-small" data-action="add-new-collateral-pledge-contract">Добавить договор</button>
          </div>
        </fieldset>
        <section class="new-collateral-documents">
          ${documentCollateral
            ? renderDocumentWidget({ context: "collateralDraft", ownerId: "NEW-COLLATERAL-DRAFT", documents: draft.documents || [], activeCollateral: documentCollateral, title: "Документы по объекту", subtitle: "Файлы карточки залога", description: "Типы документов показаны для выбранного вида залога." })
            : `<section class="panel document-widget"><div class="panel-title"><div><h2>Документы по объекту</h2><p class="hint">Выберите вид залога, чтобы отобразить соответствующие типы документов.</p></div></div></section>`}
        </section>
        <div class="modal-actions"><button class="btn btn-primary" data-action="submit-new-collateral">${isEditing ? "Сохранить изменения" : isRegistryContext ? "Добавить в реестр" : "Добавить объект"}</button></div>
      </section>
    </div>
  `;
}

function updateNewCollateralDraftField(fieldEl) {
  const draft = state.newCollateralDraft;
  if (!draft) return;
  const group = fieldEl.dataset.newCollateralGroup;
  const label = fieldEl.dataset.newCollateralField;
  if (!group || !label) return;
  clearNewCollateralDraftValidationError(draft, fieldEl, group, label);
  let value = fieldEl.type === "checkbox" ? (fieldEl.checked ? "Да" : "Нет") : fieldEl.value;
  if (group === "identity" && label === "Профильный идентификатор объекта") {
    const source = getNewCollateralProfileSource(draft, getNewCollateralProfileIdentifierType(draft));
    if (source?.label === "VIN") {
      value = value.toLocaleUpperCase("en-US");
      fieldEl.value = value;
    }
  }
  if (group === "main" && label === "Значение, в указанных ед.изм.") {
    value = normalizeCollateralMeasuredInput(value);
    fieldEl.value = value;
  }
  if (group === "identity") {
    if (label === "Наименование") draft.name = value;
    else if (label === "Вид профильного идентификатора") draft.profileIdentifierType = value;
    else if (label === "Профильный идентификатор объекта") {
      const source = getNewCollateralProfileSource(draft, getNewCollateralProfileIdentifierType(draft));
      if (source?.group === "type") {
        draft.typeFields[source.field] = value;
        if (typeof document !== "undefined") {
          document.querySelectorAll("[data-new-collateral-derived-field]").forEach((field) => {
            if (field.dataset.newCollateralDerivedField === source.field) field.value = value;
          });
        }
      }
      else if (source?.group === "main") draft.sharedFields[source.field] = value;
    }
    else if (label === "Подвид залога") {
      const subtypeField = getNewCollateralSubtypeField(draft.typeLabel);
      draft.subtype = value;
      if (subtypeField) draft.typeFields[subtypeField] = value;
    }
  } else if (group === "type") {
    draft.typeFields[label] = value;
    if (label === getNewCollateralSubtypeField(draft.typeLabel)) draft.subtype = value;
  } else if (group === "main") {
    draft.sharedFields[label] = value;
  } else if (group === "basisDocument") {
    const basisKey = {
      "Вид документа-основания": "type",
      "Дата документа-основания": "date",
      "Номер документа-основания": "number",
      "Серия документа-основания": "series",
      "Статус ЭПТС": "status"
    }[label];
    if (basisKey) draft.basisDocument[basisKey] = value;
  } else if (group === "address") {
    draft.addressFields[label] = value;
  }
  refreshNewCollateralProfileIdentifier(draft);
  if (fieldEl.type === "checkbox") {
    const text = fieldEl.closest(".new-collateral-checkbox")?.querySelector("strong");
    if (text) text.textContent = value;
  }
}

function clearNewCollateralDraftValidationError(draft, fieldEl, group, field, index) {
  const error = draft.validationError;
  if (!error || error.group !== group) return;
  const matchesField = group === "address"
    || (error.field === field && (error.index === undefined || error.index === index));
  if (!matchesField) return;
  draft.validationError = null;
  fieldEl.removeAttribute("aria-invalid");
  const container = fieldEl.closest(".new-collateral-field, .new-collateral-private-home, td");
  container?.classList.remove("has-error");
  container?.querySelector(".new-collateral-validation-error")?.remove();
}

function updateNewCollateralPledgorField(fieldEl) {
  const draft = state.newCollateralDraft;
  const index = Number(fieldEl.dataset.index);
  const field = fieldEl.dataset.newCollateralPledgorField;
  const row = draft?.pledgors?.[index];
  if (!row || !field) return;
  clearNewCollateralDraftValidationError(draft, fieldEl, "pledgor", field, index);
  const previousInn = row.idn || "";
  row[field] = fieldEl.value;
  if (field === "idn") {
    if (!row.subjectCode || row.subjectCode === previousInn) {
      row.subjectCode = fieldEl.value;
      const subjectCode = document.querySelector(`[data-new-collateral-pledgor-field="subjectCode"][data-index="${index}"]`);
      if (subjectCode) subjectCode.value = fieldEl.value;
    }
    if (fieldEl.value.length === 10 || fieldEl.value.length === 12) {
      row.subjectType = fieldEl.value.length === 12 ? "ФЛ" : "ЮЛ";
      const subjectType = document.querySelector(`[data-new-collateral-pledgor-field="subjectType"][data-index="${index}"]`);
      if (subjectType) subjectType.value = row.subjectType;
    }
  }
}

function addNewCollateralPledgorRow() {
  if (!state.newCollateralDraft) return;
  state.newCollateralDraft.validationError = null;
  state.newCollateralDraft.pledgors.push({ share: "", name: "", idn: "", subjectType: "", role: "Залогодатель", subjectCode: "" });
}

function removeNewCollateralPledgorRow(index) {
  const rows = state.newCollateralDraft?.pledgors;
  if (!rows || rows.length <= 1 || !Number.isInteger(index) || index < 0 || index >= rows.length) return;
  state.newCollateralDraft.validationError = null;
  rows.splice(index, 1);
}

function updateNewCollateralPledgeContractField(fieldEl) {
  const rows = state.newCollateralDraft?.pledgeContracts;
  const index = Number(fieldEl.dataset.index);
  const field = fieldEl.dataset.newCollateralPledgeContractField;
  if (!rows || !rows[index] || !["number", "date"].includes(field)) return;
  rows[index][field] = fieldEl.value;
}

function addNewCollateralPledgeContractRow() {
  if (!state.newCollateralDraft) return;
  state.newCollateralDraft.pledgeContracts ||= [];
  state.newCollateralDraft.pledgeContracts.push({ number: "", date: "" });
}

function removeNewCollateralPledgeContractRow(index) {
  const rows = state.newCollateralDraft?.pledgeContracts;
  if (!rows || !Number.isInteger(index) || index < 0 || index >= rows.length) return;
  rows.splice(index, 1);
}

function renderImportCollateralsModal() {
  const modal = state.modal || {};
  const rows = getImportPreviewRows();
  const isTaskContext = state.modal.context === "taskCreate";
  const isApplicationContext = state.modal.context === "applicationCreate";
  const subtypeField = modal.collateralType ? getNewCollateralSubtypeField(modal.collateralType) : "";
  const subtypeOptions = subtypeField
    ? getCollateralEditableOptions({ type: getCollateralTypeCodeFromLabel(modal.collateralType) }, "type", subtypeField)
    : [];
  const columns = getImportTemplateColumns(modal.collateralType);
  const header = columns.map((column) => `<th>${escapeHtml(column)}</th>`).join("");
  return `
    <div class="modal-backdrop">
      <section class="modal wide">
        <div class="modal-head"><h2>Загрузка объектов залога из таблицы</h2><button class="btn btn-secondary" data-action="close-modal">Закрыть</button></div>
        <p class="hint">${isApplicationContext ? "Корректные строки будут добавлены в заявку и распределены по договорам из файла." : isTaskContext ? "Корректные строки будут добавлены в пул объектов создаваемой задачи." : "Корректные новые объекты будут созданы; существующие карточки в реестре не изменяются."}</p>
        <div class="form-grid">
          <label>Вид залога *<select data-import-collateral-type><option value="">Выберите вид залога</option>${FT_COLLATERAL_TYPE_OPTIONS.map((type) => `<option value="${escapeHtml(type)}" ${modal.collateralType === type ? "selected" : ""}>${escapeHtml(type)}</option>`).join("")}</select></label>
          <label>Подвид залога *<select data-import-collateral-subtype ${!modal.collateralType ? "disabled" : ""}><option value="">Выберите подвид</option>${subtypeOptions.map((subtype) => `<option value="${escapeHtml(subtype)}" ${modal.collateralSubtype === subtype ? "selected" : ""}>${escapeHtml(subtype)}</option>`).join("")}</select></label>
        </div>
        <label class="import-file-drop">Excel-файл<input type="file" accept=".xlsx,.xls" data-import-file ${!modal.collateralType || !modal.collateralSubtype ? "disabled" : ""}></label>
        ${rows.length ? `<table class="import-preview-table">
            <thead><tr><th>Строка</th>${header}<th>Результат проверки</th></tr></thead>
            <tbody>${rows.map((row) => {
              const canConfirmUpdate = (isTaskContext || isApplicationContext)
                && ["Найдено в системе", "Обновить после подтверждения"].includes(row.status);
              const resultTone = row.status === "Ошибка" ? "danger" : row.status === "Создать" ? "ok" : "warn";
              return `<tr><td>${row.row}</td>${columns.map((column) => `<td>${escapeHtml(getImportTemplateValue(row, column))}</td>`).join("")}<td class="import-preview-result-cell">${badge(row.status, resultTone)}<small>${escapeHtml(row.message || "")}</small>${(row.warnings || []).map((warning) => `<small class="import-preview-warning">${escapeHtml(warning)}</small>`).join("")}${canConfirmUpdate ? `<label class="import-update-confirm"><input type="checkbox" data-import-update-confirm="${escapeHtml(row.row)}" ${row.updateConfirmed ? "checked" : ""}> Подтвердить обновление существующей карточки</label>` : ""}</td></tr>`;
            }).join("")}</tbody>
          </table>`
        : `<div class="empty-state import-empty-state"><h2>${modal.fileLoaded ? "Совпадающие строки не найдены" : "Файл не загружен"}</h2><p>${modal.fileLoaded ? "В загруженной таблице нет строк выбранного вида и подвида залога." : "Сначала выберите вид и подвид залога, затем выберите Excel-файл."}</p></div>`}
        <div class="modal-actions"><button class="btn btn-primary" data-action="confirm-import" ${rows.some((row) => row.status === "Создать" || row.updateConfirmed) ? "" : "disabled"}>Загрузить корректные строки</button></div>
      </section>
    </div>
  `;
}

function renderMobileInspectionModal() {
  return "";
}

function renderModal() {
  if (!state.modal) return "";
  if (state.modal.type === "deleteApplication") {
    const application = (state.data.applications || []).find((item) => item.id === state.modal.applicationId);
    if (!application) return "";
    return `
      <div class="modal-backdrop">
        <section class="modal" role="dialog" aria-modal="true" aria-labelledby="deleteApplicationTitle">
          <div class="modal-head"><h2 id="deleteApplicationTitle">Удалить черновик заявки?</h2></div>
          <p>Вы действительно хотите удалить заявку ${escapeHtml(application.number || application.id)}?</p>
          <div class="modal-actions">
            <button type="button" class="btn btn-secondary" data-action="close-modal">Отменить</button>
            <button type="button" class="btn btn-danger" data-action="confirm-delete-application" data-application="${escapeHtml(application.id)}">Удалить</button>
          </div>
        </section>
      </div>
    `;
  }
  if (state.modal.type === "deferTask") return renderDeferTaskModal();
  if (state.modal.type === "reassign") return renderReassignModal();
  if (state.modal.type === "taskParticipant") return renderTaskParticipantModal();
  if (state.modal.type === "approver") return renderApproverModal();
  if (state.modal.type === "returnToInitiator") return renderReturnToInitiatorModal();
  if (state.modal.type === "subtask") return renderSubtaskModal();
  if (state.modal.type === "followup") {
    const parent = getTask(state.modal.parentTaskId);
    const applicationNumber = parent ? getTaskApplicationNumber(parent) : "";
    const collateralSummary = parent ? getTaskCollaterals(parent).map((item) => item.id).join(", ") : "";
    const isInspection = isInspectionTaskType(state.modal.taskType);
    const title = isInspection ? "Создать задачу на осмотр" : "Создать задачу на оценку";
    return `
      <div class="modal-backdrop">
        <section class="modal">
          <div class="modal-head"><h2>${escapeHtml(title)}</h2><button class="btn btn-secondary" data-action="close-modal">Закрыть</button></div>
          <div class="form-grid">
            <label>Заявка<input value="${escapeHtml(applicationNumber || "-")}" readonly></label>
            <label>Залоги<input value="${escapeHtml(collateralSummary || "-")}" readonly></label>
            <label>Исполнитель<select id="followupAssignee">${employees.map((item) => `<option>${escapeHtml(item)}</option>`).join("")}</select></label>
            <label>Срок<input id="followupDue" type="date" value="2026-06-24"></label>
          </div>
          <label>Комментарий<textarea id="followupComment">${escapeHtml(`${title} создана из маршрута ${state.modal.parentTaskId}.`)}</textarea></label>
          <div class="modal-actions"><button class="btn btn-primary" data-action="submit-followup">Создать</button></div>
        </section>
      </div>
    `;
  }
  if (state.modal.type === "import") return renderImportCollateralsModal();
  if (state.modal.type === "collateralPicker") return renderCollateralRegistryPickerModal();
  if (state.modal.type === "newCollateral") return renderNewCollateralModal();
	  return "";
}

