function openMobileInspectionTask(taskId) {
  return;
}

function submitMobileInspectionTask() {
  state.modal = null;
  return;
}

function mergeCollateralPickerSelection() {
  const checked = [...document.querySelectorAll("[data-modal-collateral-choice]:checked")].map((item) => item.dataset.modalCollateralChoice);
  const isApplicationContext = state.modal?.context === "application";
  const selected = isApplicationContext
    ? [...new Set([...(state.modal.selectedCollateralIds || state.newTask.selectedCollateralIds || []), ...checked])]
    : [...new Set([...(state.newTask.selectedCollateralIds || []), ...checked])];
  state.newTask.selectedCollateralIds = selected;
  if (isApplicationContext && checked.length) {
    state.newTask.applicationSelectedCollateralId = checked[checked.length - 1];
  }
  hydrateNewTaskContextFromSelectedCollaterals();
  const activeId = state.taskActiveCollateral["new-task-draft"];
  if (!selected.includes(activeId)) state.taskActiveCollateral["new-task-draft"] = selected[0] || "";
  return selected;
}

function submitCollateralPicker() {
  const selected = mergeCollateralPickerSelection();
  state.modal = null;
  addToast("Пул объектов обновлен", selected.length ? `Выбрано объектов: ${selected.length}` : "Объекты не выбраны", selected.length ? "ok" : "warn");
}

function submitNewCollateral() {
  const result = createDraftCollateralFromForm();
  if (!result) return;
  const isExisting = Boolean(result.existingCollateral);
  const isEditing = state.modal?.mode === "edit";
  const collateral = result.updatedCollateral || result.existingCollateral || result;
  const isRegistryContext = state.modal?.context === "registry";
  if (isEditing) {
    const index = state.data.collaterals.findIndex((item) => item.id === collateral.id);
    if (index >= 0) state.data.collaterals[index] = collateral;
  } else if (!isExisting) state.data.collaterals.push(collateral);
  if (!isRegistryContext) {
    state.newTask.selectedCollateralIds = [...new Set([...(state.newTask.selectedCollateralIds || []), collateral.id])];
    state.newTask.applicationSelectedCollateralId = collateral.id;
    hydrateNewTaskContextFromSelectedCollaterals();
    state.taskActiveCollateral["new-task-draft"] = collateral.id;
  }
  if (!isExisting || isEditing) persistTaskState();
  state.modal = null;
  state.newCollateralDraft = null;
  if (isRegistryContext) window.location.hash = `/app/collaterals/${collateral.id}`;
  addToast(isEditing ? "Объект залога обновлен" : isExisting ? "Объект уже есть в системе" : "Объект залога добавлен", collateral.id, isExisting && !isEditing ? "warn" : "ok");
}

function submitImportCollaterals() {
  const context = state.modal?.context || "registry";
  const selectedType = state.modal?.collateralType || "";
  const selectedSubtype = state.modal?.collateralSubtype || "";
  const selectedTypeCode = getCollateralTypeCodeFromLabel(selectedType);
  const importedPairs = [];
  let created = 0;
  let updated = 0;
  let skipped = 0;
  getImportPreviewRows().forEach((row) => {
    if (row.status === "Ошибка") {
      skipped += 1;
      return;
    }
    const importedRow = { ...row, type: selectedTypeCode, subtype: selectedSubtype };
    if (row.status === "Создать") {
      const collateral = ensureImportedCollateral(importedRow);
      if (!collateral) {
        skipped += 1;
        return;
      }
      created += 1;
      importedPairs.push({ row: importedRow, collateral });
      return;
    }
    if (row.status === "Обновить после подтверждения" && row.updateConfirmed) {
      const collateral = ensureImportedCollateral(importedRow, { updateExisting: true });
      if (!collateral) {
        skipped += 1;
        return;
      }
      updated += 1;
      importedPairs.push({ row: importedRow, collateral });
      return;
    }
    skipped += 1;
  });
  const imported = importedPairs.map((item) => item.collateral);

  if (context === "taskCreate" || context === "applicationCreate") {
    const ids = imported.map((item) => item.id);
    state.newTask.selectedCollateralIds = [...new Set([...(state.newTask.selectedCollateralIds || []), ...ids])];
    const linked = linkImportedCollateralsToApplicationDeals(importedPairs);
    hydrateNewTaskContextFromSelectedCollaterals();
    const activeId = state.taskActiveCollateral["new-task-draft"];
    if (!state.newTask.selectedCollateralIds.includes(activeId)) state.taskActiveCollateral["new-task-draft"] = ids[0] || state.newTask.selectedCollateralIds[0] || "";
    if (created || updated) persistTaskState();
    state.modal = null;
    addToast(
      "Таблица обработана",
      `Создано: ${created}; обновлено: ${updated}; пропущено: ${skipped}; договорных строк обработано: ${linked}`,
      created || updated ? "ok" : "warn"
    );
    return;
  }

  if (created || updated) persistTaskState();
  state.modal = null;
  addToast(
    "Таблица обработана",
    `Создано: ${created}; обновлено: ${updated}; пропущено: ${skipped}`,
    created || updated ? "ok" : "warn"
  );
}

function ensureImportedCollateral(row, { updateExisting = false } = {}) {
  const existing = getImportExistingCollateral(row);
  if (existing) {
    if (!updateExisting) return null;
    const imported = createImportedCollateral(row, { id: existing.id });
    const mergeNonblank = (current = {}, next = {}) => ({
      ...current,
      ...Object.fromEntries(Object.entries(next).filter(([, value]) => !isBlankFieldValue(value)))
    });
    if (!isBlankFieldValue(imported.name)) existing.name = imported.name;
    if (!isBlankFieldValue(imported.description)) existing.description = imported.description;
    if (!isBlankFieldValue(imported.absId)) existing.absId = existing.absId || imported.absId;
    existing.basisDocument = mergeNonblank(existing.basisDocument, imported.basisDocument);
    existing.ftMainInfo = mergeNonblank(existing.ftMainInfo, imported.ftMainInfo);
    existing.fields = mergeNonblank(existing.fields, imported.fields);
    existing.addressFields = mergeNonblank(existing.addressFields, imported.addressFields);
    if (!isBlankFieldValue(imported.address)) existing.address = imported.address;
    if (imported.pledgors?.length) {
      const pledgors = [...(existing.pledgors || [])];
      imported.pledgors.forEach((incoming) => {
        const index = pledgors.findIndex((item) => item.role === incoming.role && item.idn === incoming.idn);
        if (index < 0) pledgors.push(incoming);
        else pledgors[index] = { ...pledgors[index], ...mergeNonblank(pledgors[index], incoming) };
      });
      existing.pledgors = pledgors;
    }
    existing.pledgeContracts = mergeImportedPledgeContracts(existing.pledgeContracts, imported.pledgeContracts);
    existing.contractIds = uniqueItems([...(existing.contractIds || []), ...(imported.contractIds || [])]);
    const importedStatus = row.objectStatus || row.fields?.["Статус объекта"];
    if (COLLATERAL_STATUS_OPTIONS.includes(importedStatus)) existing.status = importedStatus;
    existing.source = "Excel";
    existing.updatedAt = formatTaskHistoryDate(new Date());
    existing.history = existing.history || [];
    existing.history.unshift({
      date: existing.updatedAt,
      user: getRole().user,
      field: "Карточка залога",
      oldValue: "Текущие данные",
      newValue: "Обновлены заполненные данными файла поля",
      reason: "Загрузка из Excel",
      source: "Excel"
    });
    return existing;
  }

  if (updateExisting) return null;
  const collateral = createImportedCollateral(row);
  state.data.collaterals.push(collateral);
  return collateral;
}

function mergeImportedPledgeContracts(existing = [], incoming = []) {
  const result = (Array.isArray(existing) ? existing : []).map((item) => ({ ...item }));
  (Array.isArray(incoming) ? incoming : []).forEach((item) => {
    const number = String(item.number || "").trim();
    const date = String(item.date || "").trim();
    if (!number && !date) return;
    const match = result.find((candidate) => String(candidate.number || "").trim().toLowerCase() === number.toLowerCase()
      && String(candidate.date || "").trim() === date);
    if (match) {
      Object.entries(item).forEach(([key, value]) => {
        if (isBlankFieldValue(match[key]) && !isBlankFieldValue(value)) match[key] = value;
      });
    } else result.push({ ...item, number, date });
  });
  return result;
}

function createImportedCollateral(row, { id: providedId = "" } = {}) {
  const importValue = (column) => {
    const value = getImportTemplateValue(row, column);
    return value === "-" ? "" : value;
  };
  const dealReference = importValue("Номер кредитного договора / продукт заявки");
  const productOnly = APPLICATION_DEAL_PRODUCT_TYPES.some((product) => product.toLocaleLowerCase("ru-RU") === String(dealReference).toLocaleLowerCase("ru-RU"));
  const contractNumber = productOnly ? "" : dealReference;
  const contract = getContractByNumber(contractNumber);
  const id = providedId || getNextCollateralId();
  const createdAt = formatTaskHistoryDate(new Date());
  const suzNumber = getNextMonthlyCollateralNumber(state.data.collaterals, createdAt);
  const typeLabel = row.collateralTypeLabel || getCollateralTypeLabel({ type: row.type || "Оборудование" });
  const type = getCollateralTypeCodeFromLabel(typeLabel);
  const owner = importValue("Залогодатель");
  const ownerInn = importValue("ИНН залогодателя");
  const ownerType = importValue("Тип субъекта залогодателя");
  const ownerName = importValue("Собственник");
  const ownerIdn = importValue("ИНН собственника");
  const ownerSubjectType = importValue("Тип субъекта собственника");
  const normalizeSubjectType = (value, inn) => {
    const text = String(value || "").trim();
    if (/физическое лицо|индивидуальный предприниматель/i.test(text) || text === "ФЛ") return "ФЛ";
    if (/кредитная организация/i.test(text)) return "Кредитная организация";
    if (/юридическое лицо/i.test(text) || text === "ЮЛ") return "ЮЛ";
    return String(inn || "").replace(/\D/g, "").length === 12 ? "ФЛ" : String(inn || "").replace(/\D/g, "").length === 10 ? "ЮЛ" : "";
  };
  const pledgors = [];
  if (owner || ownerInn) {
    const sameOwner = ownerName && ownerIdn && ownerIdn === ownerInn;
    pledgors.push({
      share: "",
      name: owner,
      idn: ownerInn,
      subjectType: normalizeSubjectType(ownerType, ownerInn),
      role: sameOwner ? "Залогодатель и собственник" : "Залогодатель",
      subjectCode: ownerInn
    });
    if (ownerName && ownerIdn && !sameOwner) {
      pledgors.push({
        share: "",
        name: ownerName,
        idn: ownerIdn,
        subjectType: normalizeSubjectType(ownerSubjectType, ownerIdn),
        role: "Собственник",
        subjectCode: ownerIdn
      });
    }
  }
  const address = importValue("Адрес / местонахождение");
  const requestedProfileIdentifierType = importValue("Вид профильного идентификатора");
  const requestedProfileSource = getNewCollateralProfileIdentifierOptions(typeLabel).find((option) => option.label === requestedProfileIdentifierType);
  const importedProfileIdentifier = requestedProfileSource?.group === "system"
    ? ""
    : importValue("Профильный идентификатор объекта");
  const profileIdentifierType = importedProfileIdentifier ? requestedProfileIdentifierType : "Номер карточки залога";
  const profileIdentifier = importedProfileIdentifier || suzNumber;
  const basisDocument = {
    type: importValue("Документ-основание"),
    date: normalizeNewCollateralDate(importValue("Дата документа-основания")),
    number: importValue("Номер документа-основания")
  };
  const unit = importValue("Единица измерения") || getCollateralUnitDefault({ type });
  const additionalInfo = importValue("Дополнительная информация");
  const measuredValue = importValue("Значение, в указанных ед.изм.")
    || importValue("Параметры единицы измерения");
  const pledgeContractNumber = importValue("Номер договора залога");
  const pledgeContractDate = normalizeNewCollateralDate(importValue("Дата договора залога"));
  const importColumnByTypeField = {
    "Площадь застройки, кв. м": "S",
    "Мощность двигателя, л.с.": "Мощность, л.с.",
    "Объем двигателя, куб. см": "Объем двигателя, куб.м.",
    "Пробег": "Пробег/наработка",
    "Договор имущественных прав": "Договор имущественных прав"
  };
  const fields = {};
  for (const field of FT_COLLATERAL_V8_TYPE_FIELDS[typeLabel] || []) {
    if (field === "Дополнительная информация") continue;
    let value = importValue(importColumnByTypeField[field] || field);
    if (!value && field === "Договор имущественных прав") value = importValue("Вид договора");
    if (!value && requestedProfileSource?.group === "type" && requestedProfileSource.field === field) value = importedProfileIdentifier;
    if (value) fields[field] = /Дата/i.test(field) ? normalizeNewCollateralDate(value) : value;
  }
  if (requestedProfileSource?.includesDate && importedProfileIdentifier) {
    const combined = importedProfileIdentifier.match(/^(.*?)\s+от\s+(\d{2}\.\d{2}\.\d{4})$/i);
    if (combined) {
      fields["Номер договора"] = combined[1].trim();
      fields["Дата заключения договора"] = normalizeNewCollateralDate(combined[2]);
    }
  }
  const statusValue = importValue("Статус объекта");
  const status = COLLATERAL_STATUS_OPTIONS.includes(statusValue) ? statusValue : "Новый";
  const addressFields = address ? { "Адрес / место нахождения": address } : {};
  const mainFields = {
    "Единица измерения": unit,
    "Значение, в указанных ед.изм.": measuredValue || row.unitValue || row.fields?.["Значение, в указанных ед.изм."] || row.unitParameters || row.fields?.["Параметры единицы измерения"] || "",
    "Дополнительная информация": additionalInfo
  };
  if (fields["Вид договора"] && !fields["Договор имущественных прав"]) {
    fields["Договор имущественных прав"] = fields["Вид договора"];
    delete fields["Вид договора"];
  }
  const rawImportedSubtype = String(row.subtype || row.fields?.["Подвид залога"] || row.fields?.["Подвид"] || "").trim();
  const importedSubtype = rawImportedSubtype
    ? resolveCollateralSubtype({ type: typeLabel, description: row.description || row.name || "", fields: { ...(row.fields || {}), "Подвид залога": rawImportedSubtype } }) || rawImportedSubtype
    : "";
  fields["Категория"] = typeLabel;
  if (importedSubtype) {
    fields["Подвид залога"] = importedSubtype;
    fields["Подтип"] = importedSubtype;
  }
  fields["Источник создания"] = "Excel";
  const dealContractNumber = productOnly ? "" : dealReference;
  const matchedContract = getContractByNumber(dealContractNumber) || contract;
  const product = productOnly ? dealReference : matchedContract?.product || "";
  const contextualImport = ["applicationCreate", "taskCreate"].includes(state.modal?.context);
  const clientNameForHeader = matchedContract?.clientName || (contextualImport ? state.newTask?.dealClientName : "") || "";
  const clientInnForHeader = matchedContract?.inn || (contextualImport ? state.newTask?.dealClientInn : "") || "";
  const reportStatus = importValue("Статус объекта");
  return {
    id,
    suzNumber,
    type,
    subtype: importedSubtype,
    name: importValue("Наименование") || `${typeLabel}: объект из таблицы`,
    profileIdentifier,
    profileIdentifierType,
    basisDocument,
    absId: importValue("Идентификатор в АБС"),
    clientType: normalizeSubjectType("", clientInnForHeader),
    clientName: clientNameForHeader,
    clientId: clientInnForHeader,
    gsz: matchedContract?.gsz || "",
    groupIdentificationCode: "",
    region: address.split(",")[0] || "Город не указан",
    address,
    addressFields,
    description: additionalInfo || `${typeLabel}: объект загружен из таблицы`,
    contractIds: matchedContract ? [matchedContract.id] : [],
    contractNumber: dealContractNumber,
    product,
    pledgeContractNumber,
    pledgeContractDate,
    pledgeContracts: pledgeContractNumber || pledgeContractDate
      ? [{ number: pledgeContractNumber, date: pledgeContractDate }]
      : [],
    status: COLLATERAL_STATUS_OPTIONS.includes(reportStatus) ? reportStatus : status,
    source: "Excel",
    responsible: getRole().user,
    initiator: getRole().user,
    fields,
    ftMainInfo: mainFields,
    sourceImportData: !isBlankFieldValue(importValue("S")) ? { S: importValue("S") } : {},
    evaluations: [],
    encumbrances: [],
    pledgors,
    documents: [],
    history: [{ date: createdAt, user: getRole().user, field: "Карточка залога", oldValue: "-", newValue: "Создана из Excel", reason: row.message, source: "Excel" }],
    createdAt,
    updatedAt: createdAt
  };
}

function createDraftCollateralFromForm() {
  const normalizePledgeContracts = (records = []) => {
    const uniqueRecords = new Map();
    (Array.isArray(records) ? records : []).forEach((record) => {
      const number = String(record?.number || "").trim();
      const date = normalizeNewCollateralDate(record?.date || "");
      if (!number && !date) return;
      const key = `${number.toLocaleLowerCase("ru-RU")}\u0000${date}`;
      const existing = uniqueRecords.get(key);
      if (!existing) {
        uniqueRecords.set(key, { ...record, number, date });
        return;
      }
      Object.entries(record || {}).forEach(([field, value]) => {
        if (["number", "date"].includes(field)) return;
        const currentValue = existing[field];
        const currentIsSet = currentValue !== null && currentValue !== undefined && String(currentValue).trim() !== "";
        const nextIsSet = value !== null && value !== undefined && String(value).trim() !== "";
        if (!currentIsSet && nextIsSet) existing[field] = value;
      });
    });
    return [...uniqueRecords.values()];
  };
  const draft = state.newCollateralDraft;
  const validationError = getNewCollateralDraftValidationError(draft);
  if (validationError) {
    if (draft) {
      draft.validationError = validationError;
      if (validationError.group === "type") draft.typeFieldsExpanded = true;
    }
    const label = validationError.group === "pledgor"
      ? (validationError.field === "name" ? "Залогодатель" : validationError.field === "idn" ? "ИНН залогодателя" : validationError.field)
      : validationError.field;
    addToast("Проверьте данные объекта", `${label}: ${validationError.message}`, "warn");
    return null;
  }
  if (draft) draft.validationError = null;
  const editingCollateral = state.modal?.mode === "edit" ? getCollateral(state.modal.collateralId) : null;
  if (state.modal?.mode === "edit" && !editingCollateral) {
    addToast("Объект не найден", "Редактируемая карточка залога больше не существует.", "warn");
    return null;
  }
  const typeLabel = draft?.typeLabel || "";

  const subtypeField = getNewCollateralSubtypeField(typeLabel);
  const selectedIdentifierOption = getNewCollateralProfileSource(draft, getNewCollateralProfileIdentifierType(draft));
  const naturalIdentifier = selectedIdentifierOption?.group === "system" ? "" : getNewCollateralProfileIdentifier(draft);
  const identifierToCheck = normalizeProfileIdentifier(naturalIdentifier);
  const existing = identifierToCheck
    ? state.data.collaterals.find((item) => item.id !== editingCollateral?.id
      && getCollateralTypeLabel(item) === typeLabel
      && normalizeProfileIdentifier(getCollateralObjectIdentifier(item)) === identifierToCheck)
    : null;
  if (existing && editingCollateral) {
    addToast("Профильный идентификатор уже используется", `Он указан в карточке ${existing.id}.`, "warn");
    return null;
  }
  if (existing) {
    addToast(
      "Профильный идентификатор уже используется",
      `Он указан в карточке ${existing.id}. Закройте окно и выберите существующий объект из реестра.`,
      "warn"
    );
    return null;
  }

  const id = editingCollateral?.id || getNextCollateralId();
  const type = getCollateralTypeCodeFromLabel(typeLabel);
  const name = draft.name.trim();
  const timestamp = formatTaskHistoryDate(new Date());
  const suzNumber = getCollateralSuzNumber(editingCollateral)
    || getNextMonthlyCollateralNumber(state.data.collaterals, timestamp);
  const profileIdentifierType = naturalIdentifier ? getNewCollateralProfileIdentifierType(draft) : "Номер карточки залога";
  const profileIdentifier = naturalIdentifier || suzNumber;
  const source = editingCollateral?.source || (state.modal?.context === "registry" ? "Реестр залогов" : "Форма заявки");
  const savedTypeFieldDraft = { ...draft.typeFields };
  const typeFields = Object.fromEntries(getCollateralTypeDisplayFieldLabels(typeLabel)
    .filter((label) => label !== "Дополнительная информация")
    .filter((label) => isCollateralV6TypeFieldApplicable(typeLabel, label, draft))
    .filter((label) => label !== subtypeField && !isBlankFieldValue(savedTypeFieldDraft[label]))
    .map((label) => [label, /Дата/i.test(label) ? normalizeNewCollateralDate(savedTypeFieldDraft[label]) : savedTypeFieldDraft[label]]));
  if (subtypeField) typeFields[subtypeField] = draft.subtype.trim();
  const pledgors = (draft.pledgors || [])
    .filter((row) => row.name?.trim() || row.idn?.trim())
    .map((row) => ({
      share: row.share?.trim() || "",
      name: row.name?.trim() || "",
      idn: row.idn?.trim() || "",
      subjectType: row.subjectType || "",
      role: row.role?.trim() || "Залогодатель",
      subjectCode: row.subjectCode?.trim() || row.idn?.trim() || ""
    }));
  let pledgeContracts = normalizePledgeContracts(draft.pledgeContracts || []);
  const legacyPledgeContract = {
    number: String(draft.sharedFields?.["Номер договора залога"] || "").trim(),
    date: normalizeNewCollateralDate(draft.sharedFields?.["Дата договора залога"] || "")
  };
  if ((legacyPledgeContract.number || legacyPledgeContract.date)
      && !pledgeContracts.some((item) => item.number === legacyPledgeContract.number && item.date === legacyPledgeContract.date)) {
    pledgeContracts.push(legacyPledgeContract);
  }
  pledgeContracts = normalizePledgeContracts(pledgeContracts);
  const primaryPledgeContract = pledgeContracts[0] || { number: "", date: "" };
  const sharedFields = {
    "Единица измерения": [draft.sharedFields?.["Единица измерения"]].find((value) => !isBlankFieldValue(value)) || "",
    "Значение, в указанных ед.изм.": [draft.sharedFields?.["Значение, в указанных ед.изм."], draft.sharedFields?.["Параметры единицы измерения"]].find((value) => !isBlankFieldValue(value)) || "",
    "Дополнительная информация": [draft.sharedFields?.["Дополнительная информация"]].find((value) => !isBlankFieldValue(value)) || "",
    "Осмотр произведен": draft.sharedFields?.["Осмотр произведен"] || "Нет",
    "Контактное лицо для осмотра": draft.sharedFields?.["Контактное лицо для осмотра"] || ""
  };
  const mainFields = {
    ...(editingCollateral?.ftMainInfo || {}),
    ...sharedFields,
    "Наименование": name
  };
  delete mainFields[COLLATERAL_GROUP_ATTRIBUTE];
  delete mainFields["Параметры единицы измерения"];
  delete mainFields["Номер договора залога"];
  delete mainFields["Дата договора залога"];
  delete mainFields["Осмотр (проведен/не проведен)"];
  const basisDocument = {
    type: String(draft.basisDocument?.type || "").trim(),
    date: normalizeNewCollateralDate(draft.basisDocument?.date || ""),
    series: String(draft.basisDocument?.series || "").trim(),
    number: String(draft.basisDocument?.number || "").trim(),
    status: String(draft.basisDocument?.status || "").trim()
  };
  delete mainFields[LEGACY_COLLATERAL_GROUP_ATTRIBUTE];
  const addressApplicable = isCollateralAddressApplicable(typeLabel);
  const addressFields = addressApplicable
    ? groupsAddressFields(typeLabel, draft.addressFields)
    : (editingCollateral ? { ...(editingCollateral.addressFields || {}), ...(draft.addressFields || {}) } : {});
  if (addressApplicable) {
    addressFields["Частный дом"] = draft.addressFields["Частный дом"] || "Нет";
    addressFields.manualEntry = isAffirmativeValue(draft.addressFields.manualEntry) ? "Да" : "Нет";
  }
  const structuredAddress = isAffirmativeValue(addressFields.manualEntry)
    ? [
        addressFields["Почтовый индекс"], addressFields["Регион"], addressFields["Район"],
        addressFields["Населенный пункт"], addressFields["Город"], addressFields["Улица"], addressFields["Дом"],
        addressFields["Корпус"], addressFields["Квартира"]
      ].filter(Boolean).join(", ")
    : "";
  const address = addressApplicable
    ? (addressFields["Адрес / место нахождения"] || structuredAddress)
    : (editingCollateral?.address || "");
  if (addressApplicable) addressFields["Адрес / место нахождения"] = address;
  const primaryPledgor = pledgors[0] || {};
  const documents = (draft.documents || []).map((doc, index) => {
    const sourceDoc = typeof doc === "string" ? { name: doc } : { ...doc };
    return {
      ...sourceDoc,
      id: sourceDoc.id || `DOC-${id}-${index + 1}`,
      target: id,
      targetIds: [id],
      collateralIds: [id],
      applyScope: "collateral",
      applyValue: id
    };
  });
  const fields = {
    ...typeFields,
    "Категория": typeLabel,
    "Подтип": draft.subtype.trim(),
    "Источник создания": source
  };
  const normalizedMainInfo = { ...(editingCollateral?.ftMainInfo || {}) };
  delete normalizedMainInfo[COLLATERAL_GROUP_ATTRIBUTE];
  delete normalizedMainInfo[LEGACY_COLLATERAL_GROUP_ATTRIBUTE];
  delete normalizedMainInfo["Параметры единицы измерения"];
  delete normalizedMainInfo["Номер договора залога"];
  delete normalizedMainInfo["Дата договора залога"];
  const profileSourceChanged = editingCollateral && selectedIdentifierOption?.group === "type"
    ? normalizeProfileIdentifier(getCollateralProfileFieldValue(editingCollateral, selectedIdentifierOption))
      !== normalizeProfileIdentifier(naturalIdentifier)
    : false;
  const shouldRecheckIdentifier = profileSourceChanged && (
    (typeLabel === "Объекты недвижимости" && selectedIdentifierOption?.field === "Кадастровый номер")
    || (typeLabel === "Транспортные средства, прицепы (полуприцепы)"
      && selectedIdentifierOption?.field === "Идентификационный номер транспортного средства (VIN)")
    || (typeLabel === "Транспортные средства (самоходная техника)"
      && selectedIdentifierOption?.field === "Идентификационный номер ТС или СМ (VIN, PIN, заводской)")
  );
  const recheckRequest = shouldRecheckIdentifier
    ? {
        sourceId: typeLabel === "Объекты недвижимости" ? "mobile-appraiser" : "spectrum-auto",
        source: typeLabel === "Объекты недвижимости" ? "Мобильный оценщик" : "SpectrumData",
        identifier: naturalIdentifier,
        requestedAt: timestamp,
        status: "Ожидает ответа"
      }
    : editingCollateral?.externalData?.profileIdentifierRecheck || null;
  const updatedExternalData = recheckRequest
    ? { ...(editingCollateral?.externalData || {}), profileIdentifierRecheck: recheckRequest }
    : (editingCollateral?.externalData || { "Источник": "Не запрашивался", "Дата проверки": "-", "Статус проверки": "Ожидает обогащения" });
  if (shouldRecheckIdentifier) {
    const sourceIntegration = state.data.integrations?.find((item) => item.id === recheckRequest.sourceId);
    if (sourceIntegration) {
      sourceIntegration.logs ||= [];
      sourceIntegration.logs.unshift({
        time: timestamp,
        result: "Ожидает ответа",
        object: id,
        message: `Повторная проверка по идентификатору ${naturalIdentifier}`
      });
    }
  }
  const createdCollateral = {
    id,
    createdAt: editingCollateral?.createdAt || (editingCollateral ? "" : timestamp),
    suzNumber,
    type,
    name,
    profileIdentifier,
    profileIdentifierType,
    basisDocument,
    pledgeContracts,
    pledgeContractNumber: primaryPledgeContract.number,
    pledgeContractDate: primaryPledgeContract.date,
    clientType: draft?.clientType || getCollateralClientType(editingCollateral) || "",
    clientName: draft?.clientName || editingCollateral?.clientName || "",
    clientId: draft?.clientId || editingCollateral?.clientId || "",
    gsz: "",
    region: addressFields["Регион"] || addressFields["Город"] || "",
    address,
    addressFields,
    manualAddressEntry: isAffirmativeValue(addressFields.manualEntry),
    description: mainFields["Дополнительная информация"] || name,
    contractIds: [],
    status: "Новый",
    source: "Вручную",
    responsible: getRole().user,
    initiator: getRole().user,
    marketValue: 0,
    pledgeValue: 0,
    allocatedValue: 0,
    appraisalStatus: "Требуется оценка",
    appraisalDue: "Не назначена",
    insuranceStatus: "Требуется проверка",
    insuranceDue: "Не назначено",
    riskState: "Новый",
    riskScore: 0,
    crossPledge: false,
    fields,
    ftMainInfo: mainFields,
    groupIdentificationCode: editingCollateral?.groupIdentificationCode || editingCollateral?.groupCode || "",
    absId: mainFields["Идентификатор в АБС"] || "",
    includeReportData: mainFields["Признак включения в отчетные данные"] || "Да",
    additionalInfo: mainFields["Дополнительная информация"] || "",
    monitoring: { required: "Нет", periodicity: "", lastInspection: "-", nextInspection: "-", condition: "Не проверялся", schedule: [] },
    insurance: { company: "Не выбрана", policy: "Не указан", from: "-", to: "-", amount: 0, premiumStatus: "Не проверено", source: "Вручную" },
    evaluations: [],
    encumbrances: [],
    pledgors,
    risks: [],
    documents,
    history: [{ date: timestamp, user: getRole().user, field: "Карточка залога", oldValue: "-", newValue: "Создана вручную", reason: "Ручное добавление объекта", source: "АРМ" }],
    externalData: updatedExternalData,
    updatedAt: timestamp
  };
  if (!editingCollateral) return createdCollateral;

  const previousTypeFields = new Set(getCollateralTypeDisplayFieldLabels(getCollateralTypeLabel(editingCollateral)));
  const preservedFields = Object.fromEntries(Object.entries(editingCollateral.fields || {}).filter(([field]) => !previousTypeFields.has(field)));
  for (const field of ["Тип документа", "Дата", "Серия", "Номер", "Номер договора залога", "Дата договора залога"]) delete preservedFields[field];
  delete preservedFields["Осмотр (проведен/не проведен)"];
  delete preservedFields[COLLATERAL_GROUP_ATTRIBUTE];
  delete preservedFields[LEGACY_COLLATERAL_GROUP_ATTRIBUTE];
  const editHistory = {
    date: timestamp,
    user: getRole().user,
    field: "Карточка залога",
    oldValue: editingCollateral.name || editingCollateral.profileIdentifier || editingCollateral.id,
    newValue: createdCollateral.name || createdCollateral.profileIdentifier,
    reason: "Данные обновлены из формы заявки",
    source: "АРМ"
  };
  return {
    ...editingCollateral,
    ...createdCollateral,
    fields: { ...preservedFields, ...createdCollateral.fields },
    ftMainInfo: { ...normalizedMainInfo, ...mainFields },
    groupIdentificationCode: editingCollateral.groupIdentificationCode || editingCollateral.groupCode || "",
    groupCode: editingCollateral.groupCode || editingCollateral.groupIdentificationCode || "",
    address: addressApplicable ? address : (editingCollateral.address || ""),
    addressFields: addressApplicable ? addressFields : { ...(editingCollateral.addressFields || {}), ...(addressFields || {}) },
    absId: editingCollateral.absId || editingCollateral.absIdentifier || editingCollateral.ftMainInfo?.["Идентификатор в АБС"] || "",
    includeReportData: editingCollateral.includeReportData || editingCollateral.include310 || editingCollateral.ftMainInfo?.["Признак включения в отчетные данные"] || "Да",
    contractIds: editingCollateral.contractIds || [],
    contractId: editingCollateral.contractId || "",
    contractNumber: editingCollateral.contractNumber || "",
    status: editingCollateral.status,
    marketValue: editingCollateral.marketValue,
    pledgeValue: editingCollateral.pledgeValue,
    allocatedValue: editingCollateral.allocatedValue,
    appraisalStatus: editingCollateral.appraisalStatus,
    appraisalDue: editingCollateral.appraisalDue,
    insuranceStatus: editingCollateral.insuranceStatus,
    insuranceDue: editingCollateral.insuranceDue,
    riskState: editingCollateral.riskState,
    riskScore: editingCollateral.riskScore,
    crossPledge: editingCollateral.crossPledge,
    monitoring: editingCollateral.monitoring,
    insurance: editingCollateral.insurance,
    evaluations: editingCollateral.evaluations || [],
    encumbrances: editingCollateral.encumbrances || [],
    risks: editingCollateral.risks || [],
    history: [editHistory, ...(editingCollateral.history || [])],
    externalData: updatedExternalData,
    history: shouldRecheckIdentifier
      ? [{
          date: timestamp,
          user: getRole().user,
          field: "Профильный идентификатор объекта",
          oldValue: getCollateralProfileFieldValue(editingCollateral, selectedIdentifierOption) || "-",
          newValue: naturalIdentifier,
          reason: `Запущена повторная проверка через ${recheckRequest.source}`,
          source: recheckRequest.source
        }, editHistory, ...(editingCollateral.history || [])]
      : [editHistory, ...(editingCollateral.history || [])],
    source: editingCollateral.source,
    responsible: editingCollateral.responsible,
    initiator: editingCollateral.initiator
  };
}

function groupsAddressFields(typeLabel, values = {}) {
  if (!isCollateralAddressApplicable(typeLabel)) return {};
  const aliases = {
    "Улица": "Улица (в том числе проспект, переулок, квартал)",
    "Дом": "Номер дома (владения)",
    "Корпус": "Номер корпуса (строения)",
    "Квартира": "Номер квартиры (офиса, помещения, комнаты)"
  };
  return {
    ...Object.fromEntries(COLLATERAL_ADDRESS_FIELDS.map((label) => [label, values[label] || values[aliases[label]] || ""])),
    manualEntry: values.manualEntry || "Нет",
    "Частный дом": values["Частный дом"] || "Нет"
  };
}

function normalizeProfileIdentifier(value = "") {
  return String(value || "").replace(/\s+/g, "").toLowerCase();
}

function getPrimaryIdentifierFieldName(typeLabel) {
  const normalized = FT_COLLATERAL_TYPE_LABELS[typeLabel] || typeLabel;
  const fields = {
    "Объекты недвижимости": "Кадастровый номер",
    "Транспортные средства, прицепы (полуприцепы)": "Идентификационный номер транспортного средства (VIN)",
    "Транспортные средства (самоходная техника)": "Идентификационный номер самоходной машины",
    "Оборудование": "Заводской номер",
    "Воздушные суда": "Серийный (заводской) номер",
    "Плавучие сооружения": "Идентификационный номер",
    "Железнодорожный подвижной состав": "Номер вагона",
    "Имущественные права (требования)": "Номер договора",
    "Товары в обороте": "Вид товара в обороте",
    "Прочие движимые вещи (однородные группы)": "Инвентарный номер",
    "Прочие движимые вещи (объекты)": "Идентификационный признак (значение)"
  };
  return fields[normalized] || "";
}

function getNextCollateralId() {
  const max = state.data.collaterals.reduce((value, item) => {
    const match = String(item.id || "").match(/COL-(\d+)/);
    return match ? Math.max(value, Number(match[1])) : value;
  }, 0);
  let next = max + 1;
  let id = `COL-${String(next).padStart(3, "0")}`;
  while (state.data.collaterals.some((item) => item.id === id)) {
    next += 1;
    id = `COL-${String(next).padStart(3, "0")}`;
  }
  return id;
}

function resetNewTaskDraft() {
  state.newTask = {
    key: "",
    type: "Первичный осмотр",
    applicationNumber: "",
    contractId: "",
    contractNumber: "",
    dealClientName: "",
    dealClientInn: "",
    dealProduct: "",
    dealLimit: "",
    dealCurrency: "RUB",
    participantName: "",
    participantInn: "",
    applicationType: "Оценка залога",
    applicationSubtype: "Первоначальная оценка",
    applicationPurpose: "Новый кредит / новая сделка",
    initiator: "",
    initiatorSegment: "",
    applicationSource: "Ручное создание",
    applicationStatus: "Новая",
    applicationComment: "",
    applicationInspectionCompleted: false,
    applicationInspectionLink: "",
    applicationInspectionActFile: "",
    applicationInspectionRecordedAt: "",
    applicationDeals: [],
    applicationContacts: [],
    registrationScenario: "",
    selectedCollateralIds: [],
    documents: []
  };
}

function getApplicationParameterValidation(params, collateralIds = []) {
  const requiredFields = [
    ["applicationNumber", "Номер заявки"],
    ["applicationType", "Тип заявки"],
    ["applicationSubtype", "Подтип заявки"],
    ["applicationPurpose", "Цель"],
    ["initiator", "Инициатор"],
    ["initiatorSegment", "Сегмент инициатора"],
    ["clientName", "Клиент"],
    ["clientInn", "ИНН клиента"],
    ["status", "Статус заявки"],
    ["comment", "Суть обращения / комментарий"]
  ];
  const missing = requiredFields
    .filter(([field]) => !String(params[field] || "").trim())
    .map(([, label]) => label);
  if (!collateralIds.length) missing.push("хотя бы один залог");
  return missing;
}

function showApplicationValidationToast(missing = []) {
  if (!missing.length) return false;
  const details = missing.length > 3
    ? `${missing.slice(0, 3).join(", ")} и еще ${missing.length - 3}`
    : missing.join(", ");
  addToast("Заполните заявку", `Обязательные данные: ${details}.`, "warn");
  return true;
}

function createInitialTaskForApplication(application, collateralIds, contracts = [], deals = []) {
  const ids = uniqueItems(collateralIds || []).filter((id) => getCollateral(id));
  if (!application || !ids.length) return null;
  const taskType = getApplicationInitialTaskType(application.applicationType, application.applicationSubtype);
  const primaryCollateral = getCollateral(ids[0]);
  const primaryDeal = deals[0] || {};
  const contract = getContract(primaryDeal.contractId)
    || getContractByNumber(primaryDeal.contractNumber)
    || contracts[0]
    || getContract(primaryCollateral?.contractIds?.[0]);
  const createdAt = application.createdAt || formatTaskHistoryDate(new Date());
  return createTask({
    type: taskType,
    title: `${taskType} по заявке ${application.number || application.id}`,
    collateralId: ids[0],
    collateralIds: ids,
    applicationNumber: application.number,
    contractId: primaryDeal.contractId || contract?.id || application.contractId || "",
    contractNumber: primaryDeal.contractNumber || application.contractNumber || contract?.number || "",
    contractDate: primaryDeal.contractDate || contract?.startDate || application.contractDate || "",
    dealClientName: application.clientName || application.participantName,
    dealClientInn: application.participantInn || application.inn,
    dealProduct: normalizeApplicationDealProduct(primaryDeal.product || application.product, contract?.product),
    dealLimit: primaryDeal.limit || application.limit || contract?.limit || "",
    dealCurrency: primaryDeal.currency || application.currency || contract?.currency || "RUB",
    participantName: application.participantName || application.clientName,
    participantInn: application.participantInn || application.inn,
    applicationSource: application.source || "Ручное создание",
    assignee: getDefaultTaskAssigneeForType(taskType),
    dueDate: getDefaultInitialTaskDueDate(createdAt),
    createdAt,
    priority: "Средний",
    comment: `Первая задача создана автоматически из заявки ${application.number || application.id}.`,
    source: "Заявка",
    route: ["Заявка", "Специалист", "Руководитель"],
    autoInitiated: true,
    createdFromApplicationAutomatically: true,
    inspectionFormat: getApplicationInitialInspectionFormat(application.applicationType, application.applicationSubtype),
    registrationScenario: isRegistrationTaskType(taskType) ? application.registrationScenario || application.applicationSubtype || REGISTRATION_SCENARIO_MOVABLE : "",
    documents: clone(application.documents || [])
  });
}

function submitNewApplication() {
  const createdAt = formatTaskHistoryDate(new Date());
  const identity = getNextDataApplicationIdentity(state.data, createdAt);
  const applicationNumber = identity.number;
  state.newTask.applicationNumber = applicationNumber;
  const initiator = state.newTask.initiator || getRole().user;
  const initiatorSegment = document.getElementById("newTaskInitiatorSegment")?.value || "МСБ";
  const clientName = document.getElementById("newTaskDealClientName")?.value.trim() || state.newTask.dealClientName || "";
  const clientInn = document.getElementById("newTaskDealClientInn")?.value.trim() || state.newTask.dealClientInn || "";
  const status = state.newTask.applicationStatus || "Новая";
  const applicationType = normalizeApplicationType(document.getElementById("newTaskApplicationType")?.value || state.newTask.applicationType);
  const applicationSubtype = normalizeApplicationSubtype(applicationType, document.getElementById("newTaskApplicationSubtype")?.value || state.newTask.applicationSubtype);
  const applicationPurpose = normalizeApplicationPurpose(applicationType, applicationSubtype, document.getElementById("newTaskApplicationPurpose")?.value || state.newTask.applicationPurpose);
  const comment = document.getElementById("newTaskComment")?.value.trim() || "";
  const selected = state.newTask.selectedCollateralIds.filter((id) => getCollateral(id));
  const pledgeContractOptions = getApplicationPledgeContractOptions(selected.map(getCollateral).filter(Boolean));
  const deals = normalizeApplicationDealsForSave(getDraftApplicationDeals(), clientName, clientInn, pledgeContractOptions);
  if (!applicationNumber) {
    addToast("Укажите номер заявки", "Номер заявки нужен для группировки залогов, договоров и задач.", "warn");
    return;
  }
  if (getApplicationByNumber(applicationNumber)) {
    addToast("Заявка уже существует", `${applicationNumber} уже есть в реестре заявок.`, "warn");
    return;
  }
  if (showApplicationValidationToast(getApplicationParameterValidation({ applicationNumber, applicationType, applicationSubtype, applicationPurpose, initiator, initiatorSegment, clientName, clientInn, status, comment }, selected))) return;
  const contracts = uniqueItems(deals.map((row) => row.contractId).filter(Boolean)).map(getContract).filter(Boolean);
  const products = uniqueItems(deals.map((row) => row.product));
  const contractNumbers = uniqueItems(deals.map((row) => row.contractNumber).filter(Boolean)).join(", ");
  const currencies = uniqueItems(deals.map((row) => row.currency || "RUB"));
  const collateralIds = uniqueItems(selected);
  const limit = deals.reduce((sum, row) => sum + parseNumericInput(row.limit), 0);
  const contacts = getSerializableApplicationContacts();
  const preInspection = getDraftApplicationPreInspectionPayload();
  const application = {
    id: identity.id,
    number: identity.number,
    createdAt,
    source: "Ручное создание",
    applicationType,
    applicationSubtype,
    applicationPurpose,
    initiator,
    initiatorSegment,
    clientName,
    clientNames: [clientName],
    participantName: clientName,
    participantInn: clientInn,
    clientInns: [clientInn],
    product: products[0] || "",
    products,
    limit,
    currency: currencies[0] || state.newTask.dealCurrency || "RUB",
    status,
    decisionStatus: "Заявка зарегистрирована",
    contractId: contracts[0]?.id || "",
    contractIds: contracts.map((item) => item.id),
    contractNumber: contractNumbers,
    collateralIds,
    taskIds: [],
    deals,
    contacts,
    preInspection,
    comment,
    documents: state.newTask.documents || []
  };
  state.data.applications.unshift(application);
  const initialTask = createInitialTaskForApplication(application, collateralIds, contracts, deals);
  if (initialTask) application.taskIds = uniqueItems([...(application.taskIds || []), initialTask.id]);
  persistTaskState();
  resetNewTaskDraft();
  state.taskActiveCollateral["new-task-draft"] = "";
  window.location.hash = "/app/applications";
  addToast("Заявка создана", initialTask ? `${application.number}: создана задача ${initialTask.id}` : `${application.number}: ${clientName}`, "ok");
}

function saveApplicationCard(applicationId) {
  const application = getApplication(applicationId);
  if (!application) {
    addToast("Заявка не найдена", "Изменения не сохранены.", "warn");
    return;
  }
  const initiator = application.initiator || state.newTask.initiator || getRole().user;
  const initiatorSegment = getApplicationInitiatorSegment(application);
  const clientName = getApplicationClientName(application) === "-" ? "" : getApplicationClientName(application);
  const clientInn = getApplicationInn(application) === "-" ? "" : getApplicationInn(application);
  const status = application.status || state.newTask.applicationStatus || "Новая";
  const applicationType = getApplicationType(application);
  const applicationSubtype = getApplicationSubtype(application);
  const applicationPurpose = getApplicationPurpose(application);
  const comment = application.comment || state.newTask.applicationComment || "Новая заявка для рассмотрения залоговой службой.";
  const selected = uniqueItems((state.newTask.selectedCollateralIds || []).filter((id) => getCollateral(id)));
  const pledgeContractOptions = getApplicationPledgeContractOptions(selected.map(getCollateral).filter(Boolean));
  const deals = normalizeApplicationDealsForSave(getDraftApplicationDeals(), clientName, clientInn, pledgeContractOptions);
  if (showApplicationValidationToast(getApplicationParameterValidation({ applicationNumber: application.number || application.id, applicationType, applicationSubtype, applicationPurpose, initiator, initiatorSegment, clientName, clientInn, status, comment }, selected))) return;
  const contracts = uniqueItems(deals.map((row) => row.contractId).filter(Boolean)).map(getContract).filter(Boolean);
  const products = uniqueItems(deals.map((row) => row.product));
  const contractNumbers = uniqueItems(deals.map((row) => row.contractNumber).filter(Boolean)).join(", ");
  const currencies = uniqueItems(deals.map((row) => row.currency || "RUB"));
  const collateralIds = uniqueItems(selected);
  const limit = deals.reduce((sum, row) => sum + parseNumericInput(row.limit), 0);
  const contacts = getSerializableApplicationContacts();
  const preInspection = getDraftApplicationPreInspectionPayload();
  Object.assign(application, {
    source: application.source || state.newTask.applicationSource || "Ручное создание",
    product: products[0] || "",
    products,
    limit,
    currency: currencies[0] || state.newTask.dealCurrency || application.currency || "RUB",
    contractId: contracts[0]?.id || "",
    contractIds: contracts.map((item) => item.id),
    contractNumber: contractNumbers,
    collateralIds,
    deals,
    contacts,
    preInspection,
    documents: state.newTask.documents || application.documents || []
  });
  persistTaskState();
  window.location.hash = getApplicationCardRoute(application);
  addToast("Заявка сохранена", `${application.number}: ${clientName}`, "ok");
}

function submitNewTask() {
  const selected = state.newTask.selectedCollateralIds.filter((id) => getCollateral(id));
  if (!selected.length) {
    addToast("Выберите объект залога", "Для создания задачи нужно сформировать пул объектов.", "warn");
    return;
  }
  const applicationNumber = document.getElementById("newTaskApplicationNumber")?.value.trim() || "";
  const contractNumber = document.getElementById("newTaskContractNumber")?.value.trim() || "";
  const dealClientName = document.getElementById("newTaskDealClientName")?.value.trim() || "";
  const dealClientInn = document.getElementById("newTaskDealClientInn")?.value.trim() || "";
  const dealProduct = normalizeApplicationDealProduct(document.getElementById("newTaskDealProduct")?.value.trim() || "");
  const dealLimit = document.getElementById("newTaskDealLimit")?.value.trim() || "";
  const dealCurrency = document.getElementById("newTaskDealCurrency")?.value || "RUB";
  const dueDate = document.getElementById("newTaskDue")?.value || "";
  const contract = getContractByNumber(contractNumber);
  const taskType = getUnifiedTaskType(document.getElementById("newTaskType")?.value);
  const selectedCollaterals = selected.map(getCollateral).filter(Boolean);
  const registrationSummary = getRegistrationScenarioSummary(selectedCollaterals);
  const registrationScenario = isRegistrationTaskType(taskType)
    ? document.getElementById("newTaskRegistrationScenario")?.value || registrationSummary.scenario || REGISTRATION_SCENARIO_MOVABLE
    : "";
  if (!applicationNumber) {
    addToast("Укажите номер заявки", "Номер заявки нужен для группировки связанных задач и объектов залога.", "warn");
    return;
  }
  if (!dealClientName || !dealClientInn || !dealProduct) {
    addToast("Заполните реквизиты клиента", "Клиент, ИНН клиента и продукт обязательны для создания задачи.", "warn");
    return;
  }
  if (!dueDate) {
    addToast("Укажите плановый срок", "Для задачи требуется дата и время планового срока выполнения.", "warn");
    return;
  }
  const primary = selected[0];
  state.newTask.applicationNumber = applicationNumber;
  state.newTask.contractNumber = contractNumber;
  state.newTask.contractId = contract?.id || state.newTask.contractId || "";
  state.newTask.dealClientName = dealClientName || state.newTask.dealClientName || "";
  state.newTask.dealClientInn = dealClientInn || state.newTask.dealClientInn || "";
  state.newTask.dealProduct = normalizeApplicationDealProduct(dealProduct || state.newTask.dealProduct);
  state.newTask.dealLimit = dealLimit || state.newTask.dealLimit || "";
  state.newTask.dealCurrency = dealCurrency || state.newTask.dealCurrency || "RUB";
  const draftContext = getNewTaskDraftContext(getCollateral(primary));
  const docs = state.newTask.documents || [];
  const task = createTask({
    type: taskType,
    collateralId: primary,
    collateralIds: selected,
    applicationNumber,
    contractId: contract?.id || (!contractNumber ? draftContext.contractId : ""),
    contractNumber,
    dealClientName: dealClientName || draftContext.dealClientName,
    dealClientInn: dealClientInn || draftContext.dealClientInn,
    dealProduct: normalizeApplicationDealProduct(dealProduct || draftContext.dealProduct),
    dealLimit: dealLimit || draftContext.dealLimit,
    dealCurrency: dealCurrency || draftContext.dealCurrency || "RUB",
    registrationScenario,
    participantName: draftContext.participantName,
    participantInn: draftContext.participantInn,
    applicationSource: "Ручное создание",
    assignee: document.getElementById("newTaskAssignee")?.value,
    dueDate,
	    priority: document.getElementById("newTaskPriority")?.value,
	    comment: document.getElementById("newTaskComment")?.value,
	    documents: docs
	  });
  resetNewTaskDraft();
  state.taskActiveCollateral["new-task-draft"] = "";
	  window.location.hash = getTaskCardRoute(task);
	  addToast("Задача создана", "Документы привязаны к задаче и выбранным залогам.", "ok");
	}

function generateConclusion(taskId) {
  const task = getTask(taskId);
  if (!task) return;
  const collaterals = getTaskCollaterals(task);
  if (!canGenerateTaskExpertConclusion(task, null, collaterals)) {
    addTaskHistoryEvent(task, {
      action: "Неуспешное формирование заключения",
      oldValue: "Не сформировано",
      newValue: "Не сформировано",
      comment: "Формирование не выполнено: проверьте тип задачи, шаблон и состав объектов залога."
    });
    addToast("Печатная форма недоступна", "Проверьте тип задачи, шаблон и однородность объектов залога.", "warn");
    return;
  }
  try {
    const defaults = getTaskExpertDefaults(task, collaterals);
    if (!task.expertComment) task.expertComment = defaults.comment;
    if (!task.expertOutcome) task.expertOutcome = getTaskExpertConclusionOutcome(defaults.result);
    task.expertConclusion = getGeneratedExpertConclusionText(task, collaterals);
    const documentRow = buildTaskExpertConclusionDocument(task, collaterals);
    upsertTaskExpertConclusionDocument(task, documentRow);
    addTaskHistoryEvent(task, {
      action: "Успешное формирование заключения",
      oldValue: "Не сформировано",
      newValue: documentRow.name,
      comment: `Печатная форма: ${documentRow.templateName}.`
    });
    addToast("Документ сформирован", documentRow.name, "ok");
  } catch (error) {
    addTaskHistoryEvent(task, {
      action: "Неуспешное формирование заключения",
      oldValue: "Формирование начато",
      newValue: "Не сформировано",
      comment: error?.message || "При формировании документа произошла ошибка."
    });
    addToast("Не удалось сформировать документ", error?.message || taskId, "warn");
  }
}

function updateDocumentRelation(fieldEl) {
  const owner = getDocumentOwner(fieldEl.dataset.docContext, fieldEl.dataset.docOwner);
  const doc = getDocumentByDataset(owner, fieldEl.dataset);
  if (!owner || !doc) return;
  const collaterals = getDocumentOwnerCollaterals(fieldEl.dataset.docContext, owner, fieldEl.dataset.docOwner);
  const selectedValues = getSelectedDocumentRelationValues(fieldEl);
  const relation = getDocumentRelationFromSelectedValues(selectedValues, fieldEl.dataset, collaterals);
  Object.assign(doc, {
    target: relation.target,
    targetIds: relation.targetIds,
    collateralIds: relation.collateralIds,
    applyScope: relation.applyScope,
    applyValue: relation.applyValue,
    applyAllCollaterals: relation.applyAllCollaterals
  });
  persistTaskState();
}

function getSelectedDocumentRelationValues(fieldEl) {
  const multiselect = fieldEl.closest(".document-apply-multiselect");
  if (multiselect) {
    return Array.from(multiselect.querySelectorAll("[data-doc-relation-option]:checked")).map((item) => item.value).filter(Boolean);
  }
  if (fieldEl.multiple) return Array.from(fieldEl.selectedOptions).map((item) => item.value).filter(Boolean);
  return [fieldEl.value].filter(Boolean);
}

function getDocumentRelationFromSelectedValues(values = [], dataset = {}, collaterals = []) {
  const bindings = uniqueItems(values).map(parseDocumentBinding);
  const baseBinding = [...bindings].reverse().find((binding) => ["application", "task"].includes(binding.scope));
  const allCollateralsSelected = bindings.some((binding) => binding.scope === "collaterals" && binding.value === "all");
  const explicitCollateralIds = bindings.flatMap((binding) => {
    if (binding.scope === "collateral" && binding.value) return [binding.value];
    if (binding.scope === "collaterals" && binding.value !== "all") return splitDocumentCollateralBindingValue(binding.value);
    return [];
  });
  const collateralIds = allCollateralsSelected
    ? collaterals.map((collateral) => collateral.id).filter(Boolean)
    : collaterals
      .filter((collateral) => explicitCollateralIds.includes(collateral.id))
      .map((collateral) => collateral.id);
  const binding = baseBinding || (
    allCollateralsSelected && collateralIds.length > 1
      ? { scope: "collaterals", value: "all" }
      : collateralIds.length > 1
        ? { scope: "collaterals", value: uniqueItems(collateralIds).join(",") }
        : collateralIds.length === 1
          ? { scope: "collateral", value: collateralIds[0] }
          : getDocumentDefaultBindingForContext(dataset.docContext, dataset.docOwner)
  );
  const baseTargetIds = baseBinding ? getDocumentTargetIdsForBinding(baseBinding, []) : [];
  const targetIds = baseBinding ? uniqueItems([...baseTargetIds, ...collateralIds]) : getDocumentTargetIdsForBinding(binding, collateralIds);
  const target = baseBinding
    ? getDocumentStorageTarget(baseBinding, dataset.docTarget || "task", collateralIds)
    : getDocumentStorageTarget(binding, dataset.docTarget || "task", collateralIds);
  return {
    target,
    targetIds,
    collateralIds,
    applyScope: binding.scope,
    applyValue: binding.value,
    applyAllCollaterals: allCollateralsSelected && collateralIds.length > 1
  };
}

function getDocumentDefaultBindingForContext(context, ownerId = "") {
  if (context === "task") return { scope: "task", value: ownerId || "task" };
  if (context === "collateral") return { scope: "collateral", value: ownerId || "" };
  return { scope: "application", value: "" };
}

function updateDocumentApplyFilter(fieldEl) {
  const key = fieldEl.dataset.docApplyFilter || "";
  if (!key) return;
  state.documentApplyFilters = state.documentApplyFilters || {};
  if (fieldEl.value) state.documentApplyFilters[key] = fieldEl.value;
  else delete state.documentApplyFilters[key];
}

function updateDocumentMetadata(fieldEl) {
  const owner = getDocumentOwner(fieldEl.dataset.docContext, fieldEl.dataset.docOwner);
  const doc = getDocumentByDataset(owner, fieldEl.dataset);
  const field = fieldEl.dataset.docMetaField;
  if (!owner || !doc || !["documentName", "documentDate"].includes(field)) return;
  doc[field] = fieldEl.value;
  persistTaskState();
}

function getDocumentByDataset(owner, dataset) {
  if (!owner?.documents) return null;
  const index = Number(dataset.docIndex);
  if (Number.isInteger(index) && index >= 0 && index < owner.documents.length) {
    if (typeof owner.documents[index] === "string") owner.documents[index] = { name: owner.documents[index] };
    return owner.documents[index];
  }
  const foundIndex = owner.documents.findIndex((doc) => {
    const source = typeof doc === "string" ? { name: doc } : doc;
    const title = source.title || source.type || source.name || "Документ";
    const target = source.target || source.collateralId || "task";
    return title === dataset.docTitle && target === dataset.docTarget && source.name === dataset.docName;
  });
  if (foundIndex < 0) return null;
  if (typeof owner.documents[foundIndex] === "string") owner.documents[foundIndex] = { name: owner.documents[foundIndex] };
  return owner.documents[foundIndex];
}

function attachDocument(encoded, files = [], bindingValue = "") {
  const [context, ownerId, title, target] = encoded.split("::");
  const owner = getDocumentOwner(context, ownerId);
  if (!owner) return;
  const uploadFiles = normalizeDocumentUploadFiles(files);
  if (!uploadFiles.length) return;
  const attachedAt = formatTaskHistoryDate();
  const collaterals = getDocumentOwnerCollaterals(context, owner, ownerId);
  const binding = bindingValue ? parseDocumentBinding(bindingValue) : getNormalizedDocumentBinding({ target }, target, target, context, ownerId);
  const collateralIds = getDocumentBindingCollateralIds(binding, collaterals);
  const storageTarget = getDocumentStorageTarget(binding, target, collateralIds);
  owner.documents = owner.documents || [];
  const addedDocuments = uploadFiles.map((file) => ({
    title,
    name: getUploadedDocumentFileName(file, title),
    documentName: getUploadedDocumentBusinessName(file, title),
    target: storageTarget,
    targetIds: getDocumentTargetIdsForBinding(binding, collateralIds),
    collateralIds: ["application", "task"].includes(binding.scope) ? [] : collateralIds,
    applyScope: binding.scope,
    applyValue: binding.value,
    required: true,
    status: "Прикреплен",
    documentDate: "",
    attachedAt,
    author: getRole().user,
    size: getUploadedDocumentFileSize(file)
  }));
  owner.documents.push(...addedDocuments);
  if (context === "task" && ownerId !== "new-task-draft") {
    addTaskHistoryEvent(owner, {
      action: "Добавление/редактирование документа",
      oldValue: "-",
      newValue: addedDocuments.map((doc) => doc.documentName).join(", "),
      comment: `Добавлено файлов: ${addedDocuments.length}. Тип: ${title}.`
    });
  }
  persistTaskState();
  addToast(
    addedDocuments.length > 1 ? "Документы прикреплены" : "Документ прикреплен",
    addedDocuments.length > 1 ? `${title}: файлов ${addedDocuments.length}` : `${title}: ${addedDocuments[0].name}`,
    "ok"
  );
}

function normalizeDocumentUploadFiles(files) {
  if (!files) return [];
  if (Array.isArray(files)) return files.filter(Boolean);
  if (typeof files === "string") return files ? [files] : [];
  if (typeof files.length === "number") return Array.from(files).filter(Boolean);
  return [files].filter(Boolean);
}

function getUploadedDocumentFileName(file, title) {
  return typeof file === "string" ? file : file?.name || `${title}.pdf`;
}

function getUploadedDocumentBusinessName(file, title) {
  const fileName = getUploadedDocumentFileName(file, title);
  return fileName.replace(/\.[^.]+$/, "") || title;
}

function getUploadedDocumentFileSize(file) {
  return typeof file === "string" ? "" : file?.size || "";
}

function attachTaskExpertFile(taskId, file = "") {
  const task = getTask(taskId);
  if (!task) return;
  const filename = typeof file === "string" ? file : file?.name || "";
  const size = typeof file === "string" ? "" : file?.size || "";
  const attachedAt = formatTaskHistoryDate();
  task.documents = task.documents || [];
  const currentIndex = task.documents.findIndex((doc) => doc.category === "expertConclusion" || doc.title === "Файл экспертного заключения");
  const documentRow = {
    title: "Экспертное заключение по задаче",
    name: filename || "Экспертное заключение по задаче.docx",
    target: "task",
    required: false,
    status: "Прикреплен",
    documentDate: attachedAt.split(" ")[0],
    attachedAt,
    author: getRole().user,
    size,
    category: "expertConclusion"
  };
  if (currentIndex >= 0) task.documents[currentIndex] = { ...task.documents[currentIndex], ...documentRow };
  else task.documents.push(documentRow);
  addTaskHistoryEvent(task, {
    action: "Добавление/редактирование документа",
    oldValue: previousName,
    newValue: documentRow.name,
    comment: "Прикреплен файл экспертного заключения по задаче."
  });
  persistTaskState();
  addToast("Файл печатной формы прикреплен", taskId, "ok");
}

function getDocumentOwner(context, ownerId) {
  if (context === "task") return ownerId === "new-task-draft" ? state.newTask : getTask(ownerId);
  if (context === "applicationDraft") return state.newTask;
  if (context === "application") return getApplication(ownerId);
  if (context === "collateralDraft") return ownerId === "NEW-COLLATERAL-DRAFT" ? state.newCollateralDraft : null;
  return getCollateral(ownerId);
}

function getDocumentOwnerCollaterals(context, owner, ownerId) {
  if (context === "task") {
    if (ownerId === "new-task-draft") return (state.newTask.selectedCollateralIds || []).map(getCollateral).filter(Boolean);
    return getTaskCollaterals(owner);
  }
  if (context === "applicationDraft") return (state.newTask.selectedCollateralIds || []).map(getCollateral).filter(Boolean);
  if (context === "application") return getApplicationCollaterals(owner);
  if (context === "collateralDraft") return owner ? [owner] : [];
  return owner ? [owner] : [];
}

function getDocumentBindingCollateralIds(binding, collaterals = []) {
  if (["application", "task"].includes(binding.scope)) return [];
  if (binding.scope === "collateral") return collaterals.some((collateral) => collateral.id === binding.value) ? [binding.value] : [];
  if (binding.scope === "collaterals") {
    if (binding.value === "all") return collaterals.map((collateral) => collateral.id).filter(Boolean);
    const selected = new Set(splitDocumentCollateralBindingValue(binding.value));
    return collaterals.filter((collateral) => selected.has(collateral.id)).map((collateral) => collateral.id);
  }
  return [];
}

function getDocumentTargetIdsForBinding(binding, collateralIds = []) {
  if (binding.scope === "application") return ["application"];
  if (binding.scope === "task") return [binding.value || "task"];
  return collateralIds;
}

function getDocumentStorageTarget(binding, fallbackTarget, collateralIds = []) {
  if (binding.scope === "application") return "application";
  if (binding.scope === "task") return "task";
  return collateralIds[0] || fallbackTarget || "task";
}

function deleteDocument(dataset) {
  const context = dataset.docContext;
  const ownerId = dataset.docOwner;
  const owner = getDocumentOwner(context, ownerId);
  if (!owner?.documents) return;
  const index = Number(dataset.docIndex);
  const canUseIndex = Number.isInteger(index) && index >= 0 && index < owner.documents.length;
  const removed = canUseIndex
    ? owner.documents.splice(index, 1)[0]
    : removeDocumentByIdentity(owner.documents, dataset);
  if (removed) {
    if (context === "task" && ownerId !== "new-task-draft") {
      addTaskHistoryEvent(owner, {
        action: "Добавление/редактирование документа",
        oldValue: removed.documentName || removed.name || dataset.docName || "Документ",
        newValue: "Документ удален",
        comment: `Удален файл «${removed.name || dataset.docName || "Документ"}».`
      });
    }
    persistTaskState();
    addToast("Файл удален", removed.name || dataset.docName || "Документ", "warn");
  }
}

function removeDocumentByIdentity(documents, dataset) {
  const index = documents.findIndex((doc) => {
    const title = doc.title || doc.type || doc.name || "Документ";
    const target = doc.target || doc.collateralId || "task";
    return title === dataset.docTitle && target === dataset.docTarget && doc.name === dataset.docName;
  });
  if (index === -1) return null;
  return documents.splice(index, 1)[0];
}

function attachPhoto(taskId, collateralId, angle, filename = "") {
  const task = getTask(taskId);
  if (!task) return;
  task.photoShots = task.photoShots || {};
  task.photoShots[collateralId] = task.photoShots[collateralId] || {};
  task.photoShots[collateralId][angle] = { name: filename || `${angle} - фото.jpg`, date: "2026-06-17" };
  addToast("Фото прикреплено", `${collateralId}: ${angle}`, "ok");
}

function attachMobilePhoto(taskId, collateralId, angle) {
  const key = `${taskId}::${collateralId}::${angle}`;
  state.mobile.employeePhotos[key] = { name: `${angle} - фото.jpg`, date: "2026-06-19" };
  updateMobileInspectionTaskResult(taskId, collateralId);
  addToast("Фото сделано", angle, "ok");
}

function updateMobileChecklistFactor(fieldEl) {
  const task = getTask(fieldEl.dataset.task);
  const collateralId = fieldEl.dataset.collateral;
  if (!task || !collateralId || !fieldEl.dataset.factor) return;
  task.mobileChecklistAnswers = task.mobileChecklistAnswers || {};
  task.mobileChecklistAnswers[collateralId] = task.mobileChecklistAnswers[collateralId] || {};
  if (fieldEl.value) task.mobileChecklistAnswers[collateralId][fieldEl.dataset.factor] = fieldEl.value;
  else delete task.mobileChecklistAnswers[collateralId][fieldEl.dataset.factor];
  const checklist = getMobileChecklistResult(task, getCollateral(collateralId));
  task.status = task.status === "Передано в АРМ" ? "Изменения не отправлены" : "В работе";
  task.result = `Чек-лист выездного осмотра: ${checklist.completed}/${checklist.total}, результат "${checklist.state}".`;
  if (task.mobileResultSent) task.mobileResultSent = false;
}

function updateMobileInspectionComment(fieldEl) {
  const task = getTask(fieldEl.dataset.task);
  const collateralId = fieldEl.dataset.collateral;
  if (!task || !collateralId) return;
  task.mobileInspectionComments = task.mobileInspectionComments || {};
  task.mobileInspectionComments[collateralId] = fieldEl.value;
  if (task.mobileResultSent) {
    task.mobileResultSent = false;
    task.status = "Изменения не отправлены";
  }
}

function captureMobileInspectionForm(taskId, collateralId) {
  const task = getTask(taskId);
  if (!task || !collateralId) return;
  document.querySelectorAll("[data-mobile-check-factor]").forEach((field) => {
    if (field.dataset.task === taskId && field.dataset.collateral === collateralId) updateMobileChecklistFactor(field);
  });
  document.querySelectorAll("[data-mobile-inspection-comment]").forEach((field) => {
    if (field.dataset.task === taskId && field.dataset.collateral === collateralId) updateMobileInspectionComment(field);
  });
}

function buildMobileInspectionPayload(task, collateral) {
  const collateralId = collateral?.id || task?.collateralId || "";
  const progress = getMobileInspectionProgress(task, collateral);
  const checklist = getMobileChecklistResult(task, collateral);
  const contactDetails = getMobileInspectionContactDetails(task, collateral);
  return {
    kind: "employee",
    taskId: task.id,
    type: task.type,
    collateralId,
    collateralDescription: collateral?.description || "",
    collateralAddress: collateral?.address || "",
    checklist: {
      state: checklist.state,
      completed: checklist.completed,
      total: checklist.total,
      factors: checklist.factors.map((factor) => ({
        code: factor.code,
        title: factor.title,
        value: factor.selected?.label || "Не заполнено",
        status: factor.status
      }))
    },
    comment: getMobileInspectionComment(task, collateral),
    contact: contactDetails,
    photos: progress.angles.map((angle) => {
      const photo = getMobilePhotoValue(task.id, collateralId, angle);
      return { angle, name: photo?.name || "", date: photo?.date || "", status: photo ? "Получено" : "Не получено" };
    }),
    photoProgress: { done: progress.done, total: progress.total }
  };
}

function saveMobileInspectionDraft(taskId, collateralId, silent = false) {
  const task = getTask(taskId);
  const collateral = getCollateral(collateralId || task?.collateralId);
  if (!task || !collateral) return null;
  captureMobileInspectionForm(task.id, collateral.id);
  const payload = buildMobileInspectionPayload(task, collateral);
  task.mobileDraft = { ...payload, savedAt: "2026-06-19 10:15" };
  if (task.status !== "Передано в АРМ") task.status = "В работе";
  task.result = `Черновик осмотра сохранен: ${payload.checklist.completed}/${payload.checklist.total}, результат "${payload.checklist.state}".`;
  if (!silent) addToast("Данные осмотра сохранены", `${task.id}: черновик сохранен.`, "ok");
  return payload;
}

function submitMobileInspectionResult(taskId, collateralId) {
  const task = getTask(taskId);
  const collateral = getCollateral(collateralId || task?.collateralId);
  if (!task || !collateral) return;
  const payload = saveMobileInspectionDraft(task.id, collateral.id, true);
  if (!payload) return;
  const sentAt = "2026-06-19 10:20";
  const transmitted = { ...payload, sentAt, status: "Передано в основной залоговый модуль" };
  task.mobileResult = transmitted;
  task.mobileResultSent = true;
  task.status = "Передано в АРМ";
  task.result = `Передано в основной модуль: ${transmitted.checklist.state}, фото ${transmitted.photoProgress.done}/${transmitted.photoProgress.total}.`;
  pushMobileInspectionResultToParent(task, collateral, transmitted);
  addToast("Данные отправлены", `${task.id}: результат передан в основную задачу.`, "ok");
}

function pushMobileInspectionResultToParent(task, collateral, payload) {
  const parent = task.parentTaskId ? getTask(task.parentTaskId) : task;
  if (!parent) return;
  parent.mobileInspectionResults = parent.mobileInspectionResults || [];
  const index = parent.mobileInspectionResults.findIndex((item) => item.taskId === task.id);
  if (index >= 0) parent.mobileInspectionResults[index] = payload;
  else parent.mobileInspectionResults.unshift(payload);
  addTaskHistoryEvent(parent, {
    date: payload.sentAt,
    user: task.assignee || getRole().user,
    action: "Получен результат осмотра",
    status: parent.status,
    comment: `${task.id}: ${collateral.id}, ${payload.checklist.state}, фото ${payload.photoProgress.done}/${payload.photoProgress.total}`
  });
}

window.addEventListener("hashchange", render);
render();
